#if DEV_LINK_ENABLED
// Where a game frame's time goes: PROF(slot, call) adds the call's time to
// its slot; dev link "prof" prints each slot's average per frame (and calls
// per frame) and starts counting again. Slots can nest (HUD inside RAIN...).
enum { PROF_INPUT, PROF_PLAYER, PROF_MARKET, PROF_ANIM, PROF_OTHER, PROF_WEATHER,
       PROF_RAIN_REPAINT, PROF_RAIN_DRAW, PROF_RAIN_COMPOSE, PROF_HOTBAR, PROF_CLOCK, PROF_MSG, PROF_BTN, PROF_COUNT };
static const char *const k_prof_name[PROF_COUNT] = { "input", "player", "market", "anim", "other", "weather",
                                                     "rain_repaint", "rain_draw", "rain_compose", "hotbar", "clock", "msg", "button" };
static int64_t  s_prof_us[PROF_COUNT];
static uint32_t s_prof_calls[PROF_COUNT];
static uint32_t s_prof_frames;
#define PROF(slot, call) do { int64_t prof_t0_ = esp_timer_get_time(); call; \
                              s_prof_us[slot] += esp_timer_get_time() - prof_t0_; s_prof_calls[slot]++; } while (0)
#else
#define PROF(slot, call) do { call; } while (0)
#endif

