// ============================================================
//  DISPLAY — easy commands, drawing straight into the live buffer
// ============================================================
// The panel has no memory of its own: the frame (s_fb, PSRAM) is streamed
// out the whole time, through two "bounce" buffers in internal RAM that an
// interrupt on Core 0 refills from PSRAM. Each is this many lines (it must
// divide LCD_V_RES); bigger = fewer, longer refills.
#define LCD_BOUNCE_LINES 10

void display_begin(void)
{
    spi_gpio_init();
    st7701_init_sequence();

    // data_gpio_nums[0..15] = bit0..bit15 of RGB565: bits 0-4=B0-B4, 5-10=G0-G5, 11-15=R0-R4.
    esp_lcd_rgb_panel_config_t panel_config = {
        .clk_src = LCD_CLK_SRC_DEFAULT,
        .timings = {
            .pclk_hz = 16 * 1000 * 1000,
            .h_res = LCD_H_RES,
            .v_res = LCD_V_RES,
            .hsync_pulse_width = 8,
            .hsync_back_porch = 50,
            .hsync_front_porch = 10,
            .vsync_pulse_width = 8,
            .vsync_back_porch = 20,
            .vsync_front_porch = 10,
            .flags.pclk_active_neg = false,
        },
        .data_width = 16,
        .num_fbs = 1,
        .bounce_buffer_size_px = LCD_H_RES * LCD_BOUNCE_LINES,
        .dma_burst_size = 64,
        .hsync_gpio_num = 5,
        .vsync_gpio_num = 4,
        .de_gpio_num = 45,
        .pclk_gpio_num = 21,
        .disp_gpio_num = -1,
        .data_gpio_nums = {
            6, 7, 15, 16, 8,        // B0-B4
            0, 9, 14, 47, 48, 3,    // G0-G5
            39, 40, 41, 42, 2,      // R0-R4
        },
        .flags.fb_in_psram = true,
    };

    ESP_ERROR_CHECK(esp_lcd_new_rgb_panel(&panel_config, &s_panel));
    ESP_ERROR_CHECK(esp_lcd_panel_reset(s_panel));
    ESP_ERROR_CHECK(esp_lcd_panel_init(s_panel));

    // Direct pointer to the panel's own buffer — no second copy needed.
    ESP_ERROR_CHECK(esp_lcd_rgb_panel_get_frame_buffer(s_panel, 1, (void **)&s_fb));

    ESP_LOGI(TAG, "display up: %dx%d", LCD_H_RES, LCD_V_RES);
}

static inline void draw_pixel(int x, int y, uint16_t color)
{
    if (x < 0 || y < 0 || x >= s_fb_w || y >= s_fb_h) return;
    s_fb[y * s_fb_w + x] = color;
}

// Clips (x,y,w,h) to the draw target (s_fb_w x s_fb_h). *ox/*oy: how far the
// top-left moved in (the offset into a source image). false = none of it is on it.
static inline bool fb_clip(int *x, int *y, int *w, int *h, int *ox, int *oy)
{
    int x0 = *x < 0 ? 0 : *x, y0 = *y < 0 ? 0 : *y;
    int x1 = *x + *w > s_fb_w ? s_fb_w : *x + *w;
    int y1 = *y + *h > s_fb_h ? s_fb_h : *y + *h;
    if (x0 >= x1 || y0 >= y1) return false;
    *ox = x0 - *x;
    *oy = y0 - *y;
    *x = x0; *y = y0; *w = x1 - x0; *h = y1 - y0;
    return true;
}

// n pixels of one colour from p on — two at a time where it can.
static inline void fill_row16(uint16_t *p, int n, uint16_t color)
{
    if (n > 0 && ((uintptr_t)p & 2)) { *p++ = color; n--; }
    uint32_t  c2 = color | ((uint32_t)color << 16);
    uint32_t *q  = (uint32_t *)p;
    for (int i = 0; i < n / 2; i++) q[i] = c2;
    if (n & 1) p[n - 1] = color;
}

static inline void fill_screen(uint16_t color)
{
    fill_row16(s_fb, LCD_H_RES * LCD_V_RES, color);
}

static inline void fill_rect(int x, int y, int w, int h, uint16_t color)
{
    int ox, oy;
    if (!fb_clip(&x, &y, &w, &h, &ox, &oy)) return;
    for (int j = 0; j < h; j++) fill_row16(&s_fb[(y + j) * s_fb_w + x], w, color);
}

static inline void draw_rect(int x, int y, int w, int h, uint16_t color)
{
    fill_rect(x, y, w, 1, color);
    fill_rect(x, y + h - 1, w, 1, color);
    fill_rect(x, y, 1, h, color);
    fill_rect(x + w - 1, y, 1, h, color);
}

// Draws the placeholder background/test shapes. Call once at startup,
// and again any time something has fully overwritten the screen and
// needs the "scene" put back (e.g. the menu panel closing).
static void draw_static_scene(void)
{
    fill_screen(COLOR_BLACK);
    fill_rect(50, 50, 200, 100, COLOR_RED);
    draw_rect(300, 200, 150, 150, COLOR_GREEN);
    draw_pixel(240, 240, COLOR_WHITE);
}

// Draws a pre-converted RGB565 image (e.g. exported by an image-to-C-array
// tool like image2cpp or LCD Image Converter) at position (x, y). image_data
// must contain exactly w*h uint16_t values, row-major, in RGB565 format —
// the same layout your display already uses, so no conversion happens here.
static inline void draw_image(int x, int y, int w, int h, const uint16_t *image_data)
{
    int stride = w, ox, oy;
    if (!fb_clip(&x, &y, &w, &h, &ox, &oy)) return;
    for (int row = 0; row < h; row++)
        memcpy(&s_fb[(y + row) * s_fb_w + x], &image_data[(oy + row) * stride + ox], (size_t)w * sizeof(uint16_t));
}
// Copies the part of an overlay image (the hotbar, the clock, a message —
// w x h, its top-left at (ox,oy) on screen, row y skipping inset[y] pixels
// at both ends for the rounded corners) that lies inside `clip` to s_fb.
// Putting an overlay back after a small repaint under it: only that bit.
static void overlay_blit(const uint16_t *img, int ox, int oy, int w, int h, const uint8_t *inset, rect_t clip)
{
    int y0 = clip.y > oy ? clip.y - oy : 0, y1 = clip.y + clip.h < oy + h ? clip.y + clip.h - oy : h;
    if (y0 < 0) y0 = 0;
    if (oy + y1 > LCD_V_RES) y1 = LCD_V_RES - oy;
    for (int y = y0; y < y1; y++) {
        int x0 = inset[y], x1 = w - inset[y];
        if (clip.x - ox > x0) x0 = clip.x - ox;
        if (clip.x + clip.w - ox < x1) x1 = clip.x + clip.w - ox;
        if (x0 >= x1 || oy + y < 0) continue;
        memcpy(&s_fb[(oy + y) * LCD_H_RES + ox + x0], &img[y * w + x0], (size_t)(x1 - x0) * sizeof(uint16_t));
    }
}

// Scales one RGB565 pixel's brightness by factor (0.0 = black, 1.0 = unchanged).
static inline uint16_t rgb565_scale(uint16_t color, float factor)
{
    uint8_t r = (color >> 11) & 0x1F;
    uint8_t g = (color >> 5) & 0x3F;
    uint8_t b = color & 0x1F;
    r = (uint8_t)(r * factor);
    g = (uint8_t)(g * factor);
    b = (uint8_t)(b * factor);
    return (uint16_t)((r << 11) | (g << 5) | b);
}

#define FB_TRANSPARENT_COLOR  0x0000 // colorkey sentinel for colorkeyed art (item sprites, breakable hit-flash bundles). NOTE: this equals COLOR_BLACK, so real black colorkeyed art isn't representable — use opaque art instead if you need true black there.

// Like draw_image(), but FB_TRANSPARENT_COLOR pixels are skipped (item icons).
static void draw_image_keyed(int x, int y, int w, int h, const uint16_t *image_data)
{
    int stride = w, ox, oy;
    if (!fb_clip(&x, &y, &w, &h, &ox, &oy)) return;
    for (int row = 0; row < h; row++) {
        uint16_t       *dst = &s_fb[(y + row) * s_fb_w + x];
        const uint16_t *src = &image_data[(oy + row) * stride + ox];
        for (int col = 0; col < w; col++) {
            uint16_t c = src[col];
            if (c != FB_TRANSPARENT_COLOR) dst[col] = c;
        }
    }
}

// ============================================================
//  NIGHT TINT — the colour math of the day/night cycle (DAY / NIGHT section
//  near the end). Stage 0 = day; 1..NIGHT_STAGES = one step darker and a
//  little bluer each hour from 7pm to midnight. The map editor bakes the
//  map's own art with this exact formula (nightLut() in
//  gameTools.html) — keep the two in step. Sprites that aren't map
//  art (the player, the held item) are darkened with it at draw time.
//  0x0000 stays 0x0000: it's the transparent colour key.
// ============================================================
#define NIGHT_STAGES 6
static const double k_night_bright[NIGHT_STAGES + 1] = { 1.00, 0.85, 0.71, 0.58, 0.47, 0.37, 0.28 };

typedef struct { uint16_t r[32], g[64], b[32]; } night_lut_t;   // each channel's share of the output pixel

static void night_lut_build(night_lut_t *L, int stage)
{
    double f = k_night_bright[stage], t = (double)stage / NIGHT_STAGES;
    for (int v = 0; v < 64; v++) {
        if (v < 32) {
            int c8 = (v << 3) | (v >> 2);                                   // 5-bit channel -> 8-bit
            int r  = (int)(c8 * f * (1.0 - 0.12 * t) + 0.5);
            int b  = (int)(c8 * f * (1.0 + 0.10 * t) + 10.0 * t + 0.5);     // the slight blue
            L->r[v] = (uint16_t)(((r > 255 ? 255 : r) & 0xF8) << 8);
            L->b[v] = (uint16_t)((b > 255 ? 255 : b) >> 3);
        }
        int g8 = (v << 2) | (v >> 4);                                       // 6-bit -> 8-bit
        int g  = (int)(g8 * f * (1.0 - 0.05 * t) + 0.5);
        L->g[v] = (uint16_t)(((g > 255 ? 255 : g) & 0xFC) << 3);
    }
}

static inline uint16_t night_px(const night_lut_t *L, uint16_t c)
{
    if (c == 0) return 0;
    uint16_t o = L->r[c >> 11] | L->g[(c >> 5) & 63] | L->b[c & 31];
    return o ? o : 1;   // a colour never turns into the transparent key
}

static int         s_night_shown = 0;   // stage the live map pixels are in, and sprites get tinted to
static night_lut_t s_night_lut;         // built for s_night_shown

// draw_image_keyed(), darkened to the current night stage.
static void draw_image_keyed_night(int x, int y, int w, int h, const uint16_t *image_data)
{
    if (s_night_shown == 0) { draw_image_keyed(x, y, w, h, image_data); return; }
    int stride = w, ox, oy;
    if (!fb_clip(&x, &y, &w, &h, &ox, &oy)) return;
    for (int row = 0; row < h; row++) {
        uint16_t       *dst = &s_fb[(y + row) * s_fb_w + x];
        const uint16_t *src = &image_data[(oy + row) * stride + ox];
        for (int col = 0; col < w; col++) {
            uint16_t c = src[col];
            if (c != FB_TRANSPARENT_COLOR) dst[col] = night_px(&s_night_lut, c);
        }
    }
}

// ============================================================
//  SHARED FULL-SCREEN BUFFERS — features that each need a 450 KB+ PSRAM
//  buffer, but never at the same time, take turns with these two:
//   - the back buffer (back_buffer()): an off-screen canvas that only means
//     something for the length of ONE call — compose_begin()..compose_end(),
//     one ui_redraw() / kb_redraw(), a screen_fade_*() snapshot. None of
//     those runs inside another (compose_begin() checks), and none expects
//     what it drew there to still be there on its next call.
//   - the hold buffer (hold_buffer()): keeps something ACROSS frames — the
//     game snapshot behind an open UI screen (s_ui_under), or a night stage
//     the background loader reads (night_arena()). The loader only starts
//     while the game world is up (night_tick()), and a UI screen opening
//     first waits for it and drops its result (ui_begin()), so the two
//     never hold it at once.
// ============================================================
static uint16_t *s_back_buf    = NULL;   // LCD_H_RES x LCD_V_RES, same layout as s_fb
static bool      s_back_no_mem = false;
static uint16_t *s_hold_buf    = NULL;
static size_t    s_hold_px     = 0;      // its size in pixels (>= one screen once allocated)

static uint16_t *back_buffer(void)
{
    if (!s_back_buf && !s_back_no_mem) {
        s_back_buf = heap_caps_malloc((size_t)LCD_H_RES * LCD_V_RES * sizeof(uint16_t), MALLOC_CAP_SPIRAM);
        if (!s_back_buf) {
            s_back_no_mem = true;
            ESP_LOGW(TAG, "back buffer: no PSRAM - drawing straight to the screen, no fades, no menus");
        }
    }
    return s_back_buf;
}

// At least `px` pixels. Growing it frees the old contents, so only call it
// with a bigger size when nothing holds it (no UI screen open, loader idle).
static uint16_t *hold_buffer(size_t px)
{
    if (s_hold_px < px) {
        heap_caps_free(s_hold_buf);
        s_hold_buf = heap_caps_malloc(px * sizeof(uint16_t), MALLOC_CAP_SPIRAM);
        s_hold_px  = s_hold_buf ? px : 0;
        if (!s_hold_buf) ESP_LOGE(TAG, "hold buffer: no PSRAM for %u KB", (unsigned)(px * sizeof(uint16_t) / 1024));
    }
    return s_hold_buf;
}

// hold_buffer() sized for a new map: at least `px` pixels (and never less
// than a screen, which a UI screen needs), and one left much bigger by an
// earlier, bigger map is given back first. Same rule as hold_buffer(): only
// while nothing holds it.
#define HOLD_SHRINK_SLACK_PX (16 * 1024)
static uint16_t *hold_buffer_fit(size_t px)
{
    if (px < (size_t)LCD_H_RES * LCD_V_RES) px = (size_t)LCD_H_RES * LCD_V_RES;
    if (s_hold_buf && s_hold_px > px + HOLD_SHRINK_SLACK_PX) {
        heap_caps_free(s_hold_buf);
        s_hold_buf = NULL;
        s_hold_px  = 0;
    }
    return hold_buffer(px);
}

// ============================================================
//  OFF-SCREEN COMPOSE — the panel scans s_fb out the whole time (one
//  buffer, no vsync), so erasing something and drawing it again straight
//  on screen gets caught half-way now and then: that's the flicker.
//  Between compose_begin() and compose_end() all drawing goes to the back
//  buffer instead (a copy of the screen), and compose_end() copies the
//  finished area over in one pass — every on-screen pixel changes once,
//  straight to its final colour. Only the rect(s) passed to compose_begin()
//  reach the screen. Nests (an inner call just grows the area). Without the
//  PSRAM for it, or when already drawing into the back buffer (a UI redraw),
//  it quietly draws straight into s_fb.
// ============================================================
static uint16_t *s_compose_live  = NULL;   // the real s_fb while composing; NULL = not composing
static rect_t    s_compose_rect;           // area of the back buffer that is live-accurate; w == 0 = none yet
static int       s_compose_depth = 0;

static rect_t rect_clip_screen(rect_t r)
{
    int x0 = r.x < 0 ? 0 : r.x, y0 = r.y < 0 ? 0 : r.y;
    int x1 = (r.x + r.w > LCD_H_RES) ? LCD_H_RES : r.x + r.w;
    int y1 = (r.y + r.h > LCD_V_RES) ? LCD_V_RES : r.y + r.h;
    if (x0 >= x1 || y0 >= y1) return (rect_t){ 0, 0, 0, 0 };
    return (rect_t){ x0, y0, x1 - x0, y1 - y0 };
}

// Smallest rect holding both (a w == 0 rect counts as empty).
static rect_t rect_union(rect_t a, rect_t b)
{
    if (a.w <= 0 || a.h <= 0) return b;
    if (b.w <= 0 || b.h <= 0) return a;
    int x0 = a.x < b.x ? a.x : b.x, y0 = a.y < b.y ? a.y : b.y;
    int x1 = (a.x + a.w > b.x + b.w) ? a.x + a.w : b.x + b.w;
    int y1 = (a.y + a.h > b.y + b.h) ? a.y + a.h : b.y + b.h;
    return (rect_t){ x0, y0, x1 - x0, y1 - y0 };
}

static void compose_begin(rect_t r)
{
    if (s_compose_depth++ == 0) {
        uint16_t *buf = back_buffer();
        if (!buf || s_fb == buf) return;   // no PSRAM, or already off screen in the back buffer
        s_compose_live = s_fb;
        s_fb           = buf;
        s_compose_rect = (rect_t){ 0, 0, 0, 0 };
    }
    if (s_compose_live == NULL) return;

    // Grow the area, pulling in from the screen every pixel of the new area
    // that the shadow doesn't already hold (what's inside the old area may
    // already be drawn on — keep it).
    rect_t o = s_compose_rect;
    rect_t u = rect_clip_screen(rect_union(o, r));
    if (u.w == 0) return;
    for (int py = u.y; py < u.y + u.h; py++) {
        uint16_t       *dst = &s_back_buf[py * LCD_H_RES];
        const uint16_t *src = &s_compose_live[py * LCD_H_RES];
        if (o.w > 0 && py >= o.y && py < o.y + o.h) {
            memcpy(&dst[u.x], &src[u.x], (size_t)(o.x - u.x) * sizeof(uint16_t));
            memcpy(&dst[o.x + o.w], &src[o.x + o.w], (size_t)(u.x + u.w - o.x - o.w) * sizeof(uint16_t));
        } else {
            memcpy(&dst[u.x], &src[u.x], (size_t)u.w * sizeof(uint16_t));
        }
    }
    s_compose_rect = u;
}

// compose_begin() for a rect the caller is about to paint ALL of (a repaint
// from the map, an animation frame): what's on screen there needn't be
// copied in first. Nested inside another compose, it's a plain
// compose_begin() (that one's area may already hold drawing).
static void compose_begin_over(rect_t r)
{
    if (s_compose_depth == 0) {
        uint16_t *buf = back_buffer();
        rect_t    c   = rect_clip_screen(r);
        if (buf && s_fb != buf && c.w > 0) {
            s_compose_depth = 1;
            s_compose_live  = s_fb;
            s_fb            = buf;
            s_compose_rect  = c;
            return;
        }
    }
    compose_begin(r);
}

static void compose_end(void)
{
    if (--s_compose_depth > 0 || s_compose_live == NULL) return;
    s_fb = s_compose_live;
    s_compose_live = NULL;
    rect_t u = s_compose_rect;
    for (int py = u.y; py < u.y + u.h; py++) {
        memcpy(&s_fb[py * LCD_H_RES + u.x], &s_back_buf[py * LCD_H_RES + u.x], (size_t)u.w * sizeof(uint16_t));
    }
}

// Mixes src over dst. alpha 0 = all dst, 255 = all src.
static inline uint16_t rgb565_blend(uint16_t dst, uint16_t src, uint8_t alpha)
{
    uint32_t a = alpha, ia = 255u - alpha;
    uint32_t r = (((src >> 11) & 0x1F) * a + ((dst >> 11) & 0x1F) * ia) / 255u;
    uint32_t g = (((src >> 5)  & 0x3F) * a + ((dst >> 5)  & 0x3F) * ia) / 255u;
    uint32_t b = (( src        & 0x1F) * a + ( dst        & 0x1F) * ia) / 255u;
    return (uint16_t)((r << 11) | (g << 5) | b);
}

static bool in_round_rect(int px, int py, int x, int y, int w, int h, int r)
{
    if (px < x || py < y || px >= x + w || py >= y + h) return false;
    int cx = (px < x + r) ? x + r : (px >= x + w - r) ? x + w - r - 1 : px;
    int cy = (py < y + r) ? y + r : (py >= y + h - r) ? y + h - r - 1 : py;
    int dx = px - cx, dy = py - cy;
    return dx * dx + dy * dy <= r * r;
}

// Rounded rectangle, blended over whatever s_fb already holds (alpha 255 = opaque).
// Each row of it is one run: found from both ends (at most r tests each), then filled or
// blended in one go, the colour's share of the blend worked out once. A shape too small
// for its corners (w or h under 2r) is done pixel by pixel.
static void fill_round_rect(int x, int y, int w, int h, int r, uint16_t color, uint8_t alpha)
{
    uint32_t a = alpha, ia = 255u - alpha;
    uint32_t sr = ((color >> 11) & 0x1F) * a, sg = ((color >> 5) & 0x3F) * a, sb = (color & 0x1F) * a;
    bool     runs = r >= 0 && w >= 2 * r && h >= 2 * r;
    for (int py = y; py < y + h; py++) {
        if (py < 0 || py >= s_fb_h) continue;
        uint16_t *row = &s_fb[py * s_fb_w];
        if (!runs) {
            for (int px = x; px < x + w; px++) {
                if (px < 0 || px >= s_fb_w || !in_round_rect(px, py, x, y, w, h, r)) continue;
                row[px] = (alpha == 255) ? color : rgb565_blend(row[px], color, alpha);
            }
            continue;
        }
        int x0 = x, x1 = x + w - 1;
        while (x0 <= x1 && !in_round_rect(x0, py, x, y, w, h, r)) x0++;
        while (x1 >= x0 && !in_round_rect(x1, py, x, y, w, h, r)) x1--;
        if (x0 < 0) x0 = 0;
        if (x1 >= s_fb_w) x1 = s_fb_w - 1;
        if (x0 > x1) continue;
        if (alpha == 255) { fill_row16(&row[x0], x1 - x0 + 1, color); continue; }
        for (int px = x0; px <= x1; px++) {
            uint32_t d = row[px];
            row[px] = (uint16_t)((((sr + ((d >> 11) & 0x1F) * ia) / 255u) << 11) |
                                 (((sg + ((d >> 5)  & 0x3F) * ia) / 255u) << 5) |
                                  ((sb + ( d        & 0x1F) * ia) / 255u));
        }
    }
}

// Rounded-rectangle outline, t pixels thick.
static void draw_round_rect(int x, int y, int w, int h, int r, int t, uint16_t color)
{
    int ri   = (r > t) ? r - t : 0;
    int band = (r > t) ? r : t;   // a pixel at least this far from every edge is always interior
    for (int py = y; py < y + h; py++) {
        bool mid_row = (py >= y + band && py < y + h - band);
        for (int px = x; px < x + w; px++) {
            if (mid_row && px == x + band && x + w - band > px) px = x + w - band;   // skip the interior
            if (in_round_rect(px, py, x, y, w, h, r) &&
                !in_round_rect(px, py, x + t, y + t, w - 2 * t, h - 2 * t, ri)) {
                draw_pixel(px, py, color);
            }
        }
    }
}

// One run per row: the widest dx with dx*dx + dy*dy <= r*r.
static void fill_circle(int cx, int cy, int r, uint16_t color)
{
    int dx = r;
    for (int dy = 0; dy <= r; dy++) {
        while (dx >= 0 && dx * dx + dy * dy > r * r) dx--;
        fill_rect(cx - dx, cy + dy, 2 * dx + 1, 1, color);
        if (dy) fill_rect(cx - dx, cy - dy, 2 * dx + 1, 1, color);
    }
}

// Forward declarations — s_master_volume and set_master_volume() are
// both actually defined further down in the AUDIO section, but
// screen_fade_dip() (here in DISPLAY) needs to see them before that
// point in the file. C requires at least a declaration before first
// use; -Werror turns the resulting "implicit declaration" warning into
// a hard build failure, which is exactly what you hit.
static float s_master_volume;
void set_master_volume(float volume);

// A steady beat for loops that draw then wait (the game loop, the fades):
// sleeps until `ms` after the last beat, so the drawing time is inside the
// beat instead of added to it. A beat that ran long still sleeps one tick
// (this core's idle task needs it, for the watchdog) and the beat starts
// again from now instead of rushing to catch up.
static void pace_wait(TickType_t *wake, uint32_t ms)
{
    TickType_t now = xTaskGetTickCount();
    if ((TickType_t)(now - *wake) >= pdMS_TO_TICKS(ms)) {
        vTaskDelay(1);
        *wake = xTaskGetTickCount();
    } else {
        xTaskDelayUntil(wake, pdMS_TO_TICKS(ms));
    }
}

// dst = src at brightness `factor` (0.0 = black, 1.0 = unchanged): what
// rgb565_scale() does, but through three small tables built once per call
// instead of float maths on every pixel — a fade step is the whole screen.
static void fade_pixels(uint16_t *dst, const uint16_t *src, size_t n, float factor)
{
    static night_lut_t L;   // static: off the caller's stack
    int f = (int)(factor * 256.0f + 0.5f);
    if (f < 0) f = 0;
    if (f > 256) f = 256;
    for (int v = 0; v < 64; v++) {
        if (v < 32) {
            L.r[v] = (uint16_t)(((v * f) >> 8) << 11);
            L.b[v] = (uint16_t)((v * f) >> 8);
        }
        L.g[v] = (uint16_t)(((v * f) >> 8) << 5);
    }
    for (size_t i = 0; i < n; i++) {
        uint16_t c = src[i];
        dst[i] = L.r[c >> 11] | L.g[(c >> 5) & 63] | L.b[c & 31];
    }
}

// Darkens the screen to black and drops master volume to silent over 2
// seconds, then brings both back to exactly where they started over 1
// second. Blocking — doesn't return until the whole effect finishes,
// so call this from a task that's OK being paused for ~3 seconds (a
// cutscene trigger, not your main render loop).
void screen_fade_dip(void)
{
    const int STEP_MS = 30;
    const int DARKEN_MS = 2000;
    const int RESTORE_MS = 1000;
    const int darken_steps = DARKEN_MS / STEP_MS;
    const int restore_steps = RESTORE_MS / STEP_MS;

    size_t fb_bytes = LCD_H_RES * LCD_V_RES * sizeof(uint16_t);
    uint16_t *snapshot = back_buffer();   // shared: nothing else draws while this blocks
    if (!snapshot || snapshot == s_fb) {
        ESP_LOGE(TAG, "screen_fade_dip: no snapshot buffer");
        return;
    }
    memcpy(snapshot, s_fb, fb_bytes); // remember exact original colors to restore to

    float start_volume = s_master_volume;
    TickType_t wake = xTaskGetTickCount();

    // Darken: 1.0 -> 0.0 over 2 seconds
    for (int step = 1; step <= darken_steps; step++) {
        float factor = 1.0f - ((float)step / darken_steps);
        fade_pixels(s_fb, snapshot, LCD_H_RES * LCD_V_RES, factor);
        set_master_volume(start_volume * factor);
        pace_wait(&wake, STEP_MS);
    }

    // Restore: 0.0 -> 1.0 over 1 second
    for (int step = 1; step <= restore_steps; step++) {
        float factor = (float)step / restore_steps;
        fade_pixels(s_fb, snapshot, LCD_H_RES * LCD_V_RES, factor);
        set_master_volume(start_volume * factor);
        pace_wait(&wake, STEP_MS);
    }

    memcpy(s_fb, snapshot, fb_bytes);   // land exactly back on original, no rounding drift
    set_master_volume(start_volume);
}

// Fades the CURRENTLY DISPLAYED framebuffer down to black over
// DARKEN_MS. Snapshots it first so the darkening always scales down
// from the exact original colors (matches the no-drift approach
// screen_fade_dip() already uses above) rather than re-scaling an
// already-scaled buffer step after step. Used by load_map() before it
// swaps in a new map's pixels.
static void screen_fade_to_black(void)
{
    const int STEP_MS = 30;
    const int DARKEN_MS = 1000;
    const int steps = DARKEN_MS / STEP_MS;

    size_t fb_bytes = LCD_H_RES * LCD_V_RES * sizeof(uint16_t);
    uint16_t *snapshot = back_buffer();   // shared: nothing else draws while this blocks
    if (!snapshot || snapshot == s_fb) {
        // No PSRAM for it — skip the fade and just cut to black rather than
        // fail the whole map load over a cosmetic step.
        ESP_LOGW(TAG, "screen_fade_to_black: no snapshot buffer, cutting instead of fading");
        fill_screen(COLOR_BLACK);
        return;
    }
    memcpy(snapshot, s_fb, fb_bytes);

    TickType_t wake = xTaskGetTickCount();
    for (int step = 1; step <= steps; step++) {
        fade_pixels(s_fb, snapshot, LCD_H_RES * LCD_V_RES, 1.0f - ((float)step / steps));
        pace_wait(&wake, STEP_MS);
    }
    fill_screen(COLOR_BLACK); // land exactly on black, no rounding drift
}

// Fades pixel_data (must be exactly LCD_H_RES*LCD_V_RES RGB565 pixels —
// a full-screen buffer) UP from black to full brightness over
// RESTORE_MS, writing straight into the live framebuffer as it goes.
// Used by load_map() to reveal a freshly loaded map instead of cutting
// to it instantly.
static void fade_in_from_black(const uint16_t *pixel_data, size_t pixel_count)
{
    const int STEP_MS = 30;
    const int RESTORE_MS = 800;
    const int steps = RESTORE_MS / STEP_MS;

    TickType_t wake = xTaskGetTickCount();
    for (int step = 1; step <= steps; step++) {
        fade_pixels(s_fb, pixel_data, pixel_count, (float)step / steps);
        pace_wait(&wake, STEP_MS);
    }
    memcpy(s_fb, pixel_data, pixel_count * sizeof(uint16_t)); // land exactly on the real colors, no rounding drift
}
// ============================================================
//  AUDIO — 3-channel mono WAV mixer, streamed live from SD card.
//  Each channel has its own volume (0.0-1.0); there's also one
//  master volume that scales the final mixed output. Mixer runs
//  on Core 0.
// ============================================================
#define I2S_BCLK_PIN  GPIO_NUM_20
#define I2S_LRCLK_PIN GPIO_NUM_46
#define I2S_DOUT_PIN  GPIO_NUM_19

// SD card shares the display's 3-wire SPI physical lines (SCK/MOSI) —
// same bus, separate CS pin (SD_SPI_CS) selects the card instead of the panel.
#define SD_SPI_SCK  12
#define SD_SPI_MOSI 11
#define SD_SPI_MISO 13
#define SD_SPI_CS   10
// SD clock. Above 20 MHz the driver first switches the card to high-speed
// mode; the card in this board refuses that in SPI mode (tested 2026-10-08:
// "send_csd returned 0x108" at 40 MHz), so it stays at 20. With a card that
// takes the switch, SDMMC_FREQ_HIGHSPEED (40 MHz) here roughly doubles
// reads; sd_begin() falls back to 20 MHz if the card won't mount at it.
// (The clock is 80 MHz divided by a whole number: 20, 26.7, 40, 80.)
#define SD_FREQ_KHZ SDMMC_FREQ_DEFAULT
static int s_sd_khz = 0;   // what the card actually runs at (dev link "state")

#define AUDIO_MAX_CHANNELS  3
#define MIX_CHUNK_SAMPLES   256
#define AUDIO_READ_SAMPLES  (MIX_CHUNK_SAMPLES * 4)   // read from the card 2 KB at a time: one SD read per 4 mixed chunks

typedef int sound_handle_t;
#define SOUND_HANDLE_INVALID (-1)

typedef struct {
    FILE *file;
    volatile bool active;
    int loops_left;         // -1 = infinite, else counts down; hits 0 = channel frees itself
    float volume;           // 0.0 (silent) to 1.0 (full) for this channel only
    uint32_t data_start;    // file offset where PCM samples begin
    uint32_t data_size;     // total PCM bytes for this file
    uint32_t bytes_read;    // bytes read off the card so far (this time through)
    uint32_t play_id;       // which play_sound() this is — a handle is reused once its sound ends (sound_still_playing())
    // The mixer reads AUDIO_READ_SAMPLES at a time into buf, WITHOUT holding
    // s_channels_mutex (an SD read must not hold up the game's play/stop/volume
    // calls). While it does, `reading` is set: stop_sound() then only marks the
    // channel stopped and the mixer closes the file once the read is back. A
    // channel is free when it's not active, not being read and has no file.
    volatile bool reading;
    bool     rewind;        // looping: seek back to data_start before the next read
    uint16_t buf_pos, buf_len;
    int16_t  buf[AUDIO_READ_SAMPLES];
} audio_channel_t;

static i2s_chan_handle_t s_tx_chan = NULL;
static audio_channel_t s_channels[AUDIO_MAX_CHANNELS];
static SemaphoreHandle_t s_channels_mutex;
static uint32_t s_play_id_last = 0;
static float s_master_volume = 1.0f; // 0.0 (silent) to 1.0 (full), applied to everything

typedef struct {
    uint32_t data_offset;
    uint32_t data_size;
    uint16_t num_channels;
    uint32_t sample_rate;
    uint16_t bits_per_sample;
} wav_info_t;

static inline float clamp01(float v)
{
    if (v < 0.0f) return 0.0f;
    if (v > 1.0f) return 1.0f;
    return v;
}

// Walks a WAV file's RIFF chunks to find "fmt " and "data" — more robust
// than assuming a fixed 44-byte header, since some WAV files have extra
// chunks (metadata, etc.) before the actual audio data.
static bool wav_parse_header(FILE *f, wav_info_t *out)
{
    char riff[4], wave[4];
    uint32_t chunk_size;
    if (fread(riff, 1, 4, f) != 4) return false;
    if (fread(&chunk_size, 4, 1, f) != 1) return false;
    if (fread(wave, 1, 4, f) != 4) return false;
    if (memcmp(riff, "RIFF", 4) != 0 || memcmp(wave, "WAVE", 4) != 0) return false;

    bool got_fmt = false, got_data = false;
    while (!(got_fmt && got_data)) {
        char id[4];
        uint32_t sz;
        if (fread(id, 1, 4, f) != 4) break;
        if (fread(&sz, 4, 1, f) != 1) break;

        if (memcmp(id, "fmt ", 4) == 0) {
            uint16_t audio_format, num_channels, block_align, bits_per_sample;
            uint32_t sample_rate, byte_rate;
            fread(&audio_format, 2, 1, f);
            fread(&num_channels, 2, 1, f);
            fread(&sample_rate, 4, 1, f);
            fread(&byte_rate, 4, 1, f);
            fread(&block_align, 2, 1, f);
            fread(&bits_per_sample, 2, 1, f);
            long extra = (long)sz - 16;
            if (extra > 0) fseek(f, extra, SEEK_CUR);
            out->num_channels = num_channels;
            out->sample_rate = sample_rate;
            out->bits_per_sample = bits_per_sample;
            got_fmt = true;
        } else if (memcmp(id, "data", 4) == 0) {
            out->data_offset = ftell(f);
            out->data_size = sz;
            got_data = true;
            break;
        } else {
            fseek(f, sz, SEEK_CUR); // skip chunk we don't care about
        }
        if (sz % 2 == 1) fseek(f, 1, SEEK_CUR); // chunks are word-aligned
    }
    return got_fmt && got_data;
}

// Plays filename on whichever channel is free. loops: 1 = play once,
// 0 = loop forever (call stop_sound() with the returned handle to stop
// it), N = play exactly N times. Starts at full volume (1.0) — use
// set_sound_volume() afterward to change it. Returns a handle for
// stop_sound()/set_sound_volume(), or SOUND_HANDLE_INVALID if the file
// was rejected or no channel was free.
static sound_handle_t play_sound_id(const char *filename, int loops, uint32_t *id_out);
sound_handle_t play_sound(const char *filename, int loops)
{
    return play_sound_id(filename, loops, NULL);
}

// True while the sound play_sound_id() started as (handle, id) is still on its channel.
static bool sound_still_playing(sound_handle_t handle, uint32_t id)
{
    if (handle < 0 || handle >= AUDIO_MAX_CHANNELS || !s_channels_mutex) return false;
    xSemaphoreTake(s_channels_mutex, portMAX_DELAY);
    bool on = s_channels[handle].active && s_channels[handle].play_id == id;
    xSemaphoreGive(s_channels_mutex);
    return on;
}

// play_sound(), also giving the new sound's play id (for sound_still_playing()).
static sound_handle_t play_sound_id(const char *filename, int loops, uint32_t *id_out)
{
    if (!s_channels_mutex || !s_tx_chan) return SOUND_HANDLE_INVALID;   // audio disabled (audio_begin() never ran) or torn down

    char path[160];
    snprintf(path, sizeof(path), GAME_DIR "/%s", filename);

    FILE *f = fopen(path, "rb");
    if (!f) {
        ESP_LOGE(TAG, "%s: file not found", path);
        return SOUND_HANDLE_INVALID;
    }

    wav_info_t info;
    if (!wav_parse_header(f, &info)) {
        ESP_LOGE(TAG, "%s: not a valid WAV file", filename);
        fclose(f);
        return SOUND_HANDLE_INVALID;
    }
    if (info.num_channels != 1) {
        ESP_LOGE(TAG, "%s: not mono (channels=%d) — refusing to load", filename, info.num_channels);
        fclose(f);
        return SOUND_HANDLE_INVALID;
    }
    if (info.bits_per_sample != 16) {
        ESP_LOGE(TAG, "%s: only 16-bit WAV supported (got %d-bit)", filename, info.bits_per_sample);
        fclose(f);
        return SOUND_HANDLE_INVALID;
    }

    fseek(f, info.data_offset, SEEK_SET);

    xSemaphoreTake(s_channels_mutex, portMAX_DELAY);
    int free_ch = -1;
    for (int ch = 0; ch < AUDIO_MAX_CHANNELS; ch++) {
        const audio_channel_t *c = &s_channels[ch];
        if (!c->active && !c->reading && !c->file) { free_ch = ch; break; }
    }
    if (free_ch < 0) {
        xSemaphoreGive(s_channels_mutex);
        ESP_LOGW(TAG, "%s: no free audio channel, sound dropped", filename);
        fclose(f);
        return SOUND_HANDLE_INVALID;
    }

    audio_channel_t *c = &s_channels[free_ch];
    c->file = f;
    c->data_start = info.data_offset;
    c->data_size = info.data_size;
    c->bytes_read = 0;
    c->rewind = false;
    c->buf_pos = c->buf_len = 0;
    c->loops_left = (loops <= 0) ? -1 : loops; // 0 or negative input = infinite
    c->volume = 1.0f;
    c->play_id = ++s_play_id_last;
    if (id_out) *id_out = c->play_id;
    c->active = true;
    xSemaphoreGive(s_channels_mutex);

    ESP_LOGI(TAG, "channel %d playing %s (loops=%s)", free_ch, filename,
             (loops <= 0) ? "infinite" : "finite");
    return (sound_handle_t)free_ch;
}

// Stops playback on the given handle and frees its channel immediately —
// use this for anything started with loops=0 (infinite), since those
// never stop on their own.
void stop_sound(sound_handle_t handle)
{
    if (handle < 0 || handle >= AUDIO_MAX_CHANNELS || !s_channels_mutex) return;

    xSemaphoreTake(s_channels_mutex, portMAX_DELAY);
    audio_channel_t *c = &s_channels[handle];
    if (c->file && !c->reading) {   // mid-read: the mixer closes it when the read is back
        fclose(c->file);
        c->file = NULL;
    }
    c->active = false;
    xSemaphoreGive(s_channels_mutex);
}

// Sets the volume (0.0-1.0) for one specific playing sound. Values
// outside that range are clamped. Does nothing if the handle is invalid
// or that channel isn't currently playing.
void set_sound_volume(sound_handle_t handle, float volume)
{
    if (handle < 0 || handle >= AUDIO_MAX_CHANNELS || !s_channels_mutex) return;

    xSemaphoreTake(s_channels_mutex, portMAX_DELAY);
    s_channels[handle].volume = clamp01(volume);
    xSemaphoreGive(s_channels_mutex);
}

// Sets the master volume (0.0-1.0), applied on top of every channel's
// individual volume to the final mixed output.
void set_master_volume(float volume)
{
    if (!s_channels_mutex) {                 // audio disabled: nothing is mixing, just remember it
        s_master_volume = clamp01(volume);
        return;
    }
    xSemaphoreTake(s_channels_mutex, portMAX_DELAY);
    s_master_volume = clamp01(volume);
    xSemaphoreGive(s_channels_mutex);
}

// Runs continuously on Core 0: reads a small chunk from every active
// channel's file, scales each by its own volume, sums them, scales the
// sum by master volume, clamps to avoid wraparound distortion, and
// writes the result to I2S. Handles looping and auto-freeing a channel
// once its loop count reaches zero.
static void audio_mixer_task(void *arg)
{
    int32_t mix_buf[MIX_CHUNK_SAMPLES];
    int16_t out_buf[MIX_CHUNK_SAMPLES];

    while (1) {
        // 1) refill each playing channel whose buffer is used up — the SD
        //    read (and a loop's seek) happen with the mutex let go
        for (int ch = 0; ch < AUDIO_MAX_CHANNELS; ch++) {
            audio_channel_t *c = &s_channels[ch];
            xSemaphoreTake(s_channels_mutex, portMAX_DELAY);
            bool need = c->active && c->buf_pos >= c->buf_len && c->bytes_read < c->data_size;
            FILE *f = c->file;
            bool rewind = c->rewind;
            uint32_t want = c->data_size - c->bytes_read;
            if (want > sizeof(c->buf)) want = sizeof(c->buf);
            if (need) { c->reading = true; c->rewind = false; }
            xSemaphoreGive(s_channels_mutex);
            if (!need) continue;

            if (rewind) fseek(f, c->data_start, SEEK_SET);
            size_t got = fread(c->buf, sizeof(int16_t), want / sizeof(int16_t), f);

            xSemaphoreTake(s_channels_mutex, portMAX_DELAY);
            c->reading = false;
            if (!c->active) {   // stopped while we read
                fclose(c->file);
                c->file = NULL;
            } else {
                c->buf_pos = 0;
                c->buf_len = (uint16_t)got;
                c->bytes_read += got * sizeof(int16_t);
                if (got < want / sizeof(int16_t)) c->bytes_read = c->data_size;   // short file / card error: treat as its end
            }
            xSemaphoreGive(s_channels_mutex);
        }

        // 2) mix one chunk from the buffers
        memset(mix_buf, 0, sizeof(mix_buf));
        bool any_active = false;
        float master;

        xSemaphoreTake(s_channels_mutex, portMAX_DELAY);
        master = s_master_volume;
        for (int ch = 0; ch < AUDIO_MAX_CHANNELS; ch++) {
            audio_channel_t *c = &s_channels[ch];
            if (!c->active) continue;
            any_active = true;

            size_t samples_read = c->buf_len - c->buf_pos;
            if (samples_read > MIX_CHUNK_SAMPLES) samples_read = MIX_CHUNK_SAMPLES;
            const int16_t *chunk_buf = &c->buf[c->buf_pos];
            c->buf_pos += (uint16_t)samples_read;

            float vol = c->volume;
            for (size_t i = 0; i < samples_read; i++) {
                mix_buf[i] += (int32_t)((float)chunk_buf[i] * vol);
            }

            if (c->buf_pos >= c->buf_len && c->bytes_read >= c->data_size) {
                if (c->loops_left < 0) {
                    // infinite — just restart from the top (the seek is done with the next read)
                    c->rewind = true;
                    c->bytes_read = 0;
                } else {
                    c->loops_left--;
                    if (c->loops_left > 0) {
                        c->rewind = true;
                        c->bytes_read = 0;
                    } else {
                        fclose(c->file);
                        c->file = NULL;
                        c->active = false; // channel is now free for the next play_sound()
                        ESP_LOGI(TAG, "channel %d finished, now free", ch);
                    }
                }
            }
        }
        xSemaphoreGive(s_channels_mutex);

        if (!any_active) {
            vTaskDelay(pdMS_TO_TICKS(10)); // nothing playing right now — idle
            continue;
        }

        for (int i = 0; i < MIX_CHUNK_SAMPLES; i++) {
            int32_t s = (int32_t)((float)mix_buf[i] * master);
            if (s > 32767) s = 32767;
            if (s < -32768) s = -32768;
            out_buf[i] = (int16_t)s;
        }

        size_t bytes_written;
        i2s_channel_write(s_tx_chan, out_buf, sizeof(out_buf), &bytes_written, portMAX_DELAY);
    }
}

// ============================================================
//  SOUND EFFECTS — short WAVs in GAME_DIR/sounds/sound effects/, played
//  by name: "chop" is .../sound effects/chop.wav (on the PC's card reader,
//  D:\CaptureIt\sounds\sound effects\chop.wav). Same rules as play_sound():
//  16-bit MONO, and 44100 Hz or it plays at the wrong speed.
//
//  sfx_play_list() plays up to SFX_SEQ_MAX names ONE AFTER ANOTHER — a
//  sound bundle from the editor arrives already expanded into its list.
//  Each list gets its own slot, so a new hit doesn't wait for the last
//  one's sounds to finish. Every sound still needs a free mixer channel: if
//  all AUDIO_MAX_CHANNELS are busy that one sound is skipped and the list
//  carries on, as it does past a missing file. The sfx task does the SD
//  opens, so the caller (the game loop) never waits on the card.
// ============================================================
#define SFX_DIR       "sounds/sound effects"   // under GAME_DIR, like every play_sound() name
#define SFX_NAME_MAX  40   // longest sound name, without ".wav" (the editor checks the same)
#define SFX_SEQ_MAX   8    // sounds in one list (the editor caps a breakable's hit/break list at this)
#define SFX_SLOTS     3    // lists playing at once

typedef struct {
    uint8_t count;
    char    names[SFX_SEQ_MAX][SFX_NAME_MAX + 1];
} sfx_list_t;

typedef struct {
    sfx_list_t     list;
    uint8_t        next;   // next name in the list to start
    sound_handle_t ch;     // the one playing now, SOUND_HANDLE_INVALID = none
    uint32_t       id;     // ...its play id
    bool           busy;
} sfx_slot_t;

static QueueHandle_t s_sfx_queue = NULL;   // NULL = audio is off: sfx_play_list() does nothing

// Plays names[0..n) one after another (empty names are skipped, extras past
// SFX_SEQ_MAX dropped). Never blocks. Call from the game task only.
void sfx_play_list(const char *const *names, int n)
{
    static sfx_list_t req;   // static: off the game task's small stack
    if (!s_sfx_queue) return;
    req.count = 0;
    for (int i = 0; i < n && req.count < SFX_SEQ_MAX; i++) {
        if (!names[i] || !names[i][0]) continue;
        strlcpy(req.names[req.count++], names[i], SFX_NAME_MAX + 1);
    }
    if (req.count && xQueueSend(s_sfx_queue, &req, 0) != pdTRUE)
        ESP_LOGW(TAG, "sfx: queue full — \"%s\" dropped", req.names[0]);
}

void sfx_play(const char *name)
{
    sfx_play_list(&name, 1);
}

static void sfx_task(void *arg)
{
    static sfx_slot_t slots[SFX_SLOTS];   // static: off this task's stack
    static sfx_list_t in;
    while (1) {
        bool any = false;
        for (int s = 0; s < SFX_SLOTS; s++) any |= slots[s].busy;
        // nothing playing: sleep until a list arrives; else look again soon, for the next sound's turn
        if (xQueueReceive(s_sfx_queue, &in, any ? pdMS_TO_TICKS(10) : portMAX_DELAY) == pdTRUE) {
            int s = 0;
            while (s < SFX_SLOTS && slots[s].busy) s++;
            if (s == SFX_SLOTS) ESP_LOGW(TAG, "sfx: %d lists already playing — \"%s\" dropped", SFX_SLOTS, in.names[0]);
            else slots[s] = (sfx_slot_t){ .list = in, .ch = SOUND_HANDLE_INVALID, .busy = true };
        }
        for (int s = 0; s < SFX_SLOTS; s++) {
            sfx_slot_t *sl = &slots[s];
            if (!sl->busy || sound_still_playing(sl->ch, sl->id)) continue;
            sl->ch = SOUND_HANDLE_INVALID;
            while (sl->ch == SOUND_HANDLE_INVALID && sl->next < sl->list.count) {   // one that won't play: on to the next
                char file[sizeof(SFX_DIR) + SFX_NAME_MAX + 8];
                snprintf(file, sizeof(file), SFX_DIR "/%s.wav", sl->list.names[sl->next++]);
                sl->ch = play_sound_id(file, 1, &sl->id);
            }
            if (sl->ch == SOUND_HANDLE_INVALID) sl->busy = false;   // the list is done
        }
    }
}

// Mounts the SD card at /sdcard over SPI. Call this once, unconditionally,
// before load_map() or audio_begin() — both depend on the SD card, so this
// no longer lives inside audio_begin() (that let "audio disabled" silently
// skip mounting the card, breaking map loading too). Returns false if the
// mount fails, e.g. no card inserted or a wiring issue.
bool sd_begin(void)
{
    spi_bus_config_t bus_cfg = {
        .mosi_io_num = SD_SPI_MOSI,
        .miso_io_num = SD_SPI_MISO,
        .sclk_io_num = SD_SPI_SCK,
        .quadwp_io_num = -1,
        .quadhd_io_num = -1,
        .max_transfer_sz = 4000,
    };
    ESP_ERROR_CHECK(spi_bus_initialize(SPI2_HOST, &bus_cfg, SDSPI_DEFAULT_DMA));

    sdmmc_host_t host = SDSPI_HOST_DEFAULT();
    host.slot = SPI2_HOST;
    host.max_freq_khz = SD_FREQ_KHZ;
    // PSRAM buffers (a map's pixels, a night stage) are read through a bounce
    // buffer this many 512-byte blocks long — one multi-block read each.
    host.unaligned_multi_block_rw_max_chunk_size = 32;

    sdspi_device_config_t slot_cfg = SDSPI_DEVICE_CONFIG_DEFAULT();
    slot_cfg.gpio_cs = SD_SPI_CS;
    slot_cfg.host_id = SPI2_HOST;

    esp_vfs_fat_sdmmc_mount_config_t mount_cfg = {
        .format_if_mount_failed = false,
        .max_files = 8,   // 3 audio channels + the open map (SD STREAMING) + a map/night file being read + photos
    };

    sdmmc_card_t *card;
    esp_err_t ret = esp_vfs_fat_sdspi_mount("/sdcard", &host, &slot_cfg, &mount_cfg, &card);
    if (ret != ESP_OK && host.max_freq_khz > SDMMC_FREQ_DEFAULT) {   // a card (or the wiring) that can't keep up: the standard speed
        ESP_LOGW(TAG, "SD card: no mount at %d kHz (%s) — trying %d kHz", host.max_freq_khz, esp_err_to_name(ret), SDMMC_FREQ_DEFAULT);
        host.max_freq_khz = SDMMC_FREQ_DEFAULT;
        ret = esp_vfs_fat_sdspi_mount("/sdcard", &host, &slot_cfg, &mount_cfg, &card);
    }
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "SD card mount failed (%s) — map/audio file loading will not work", esp_err_to_name(ret));
        return false;
    }
    s_sd_khz = card->real_freq_khz;
    ESP_LOGI(TAG, "SD card mounted at /sdcard, clock %d kHz", s_sd_khz);
    return true;
}

// Sets up I2S and starts the mixer task pinned to Core 0. Assumes
// sd_begin() has already been called (this only does I2S/mixer setup).
void audio_begin(void)
{
    i2s_chan_config_t chan_cfg = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_0, I2S_ROLE_MASTER);
    ESP_ERROR_CHECK(i2s_new_channel(&chan_cfg, &s_tx_chan, NULL));

    i2s_std_config_t std_cfg = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(44100),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_16BIT, I2S_SLOT_MODE_MONO),
        .gpio_cfg = {
            .mclk = I2S_GPIO_UNUSED,
            .bclk = I2S_BCLK_PIN,
            .ws   = I2S_LRCLK_PIN,
            .dout = I2S_DOUT_PIN,
            .din  = I2S_GPIO_UNUSED,
        },
    };
    ESP_ERROR_CHECK(i2s_channel_init_std_mode(s_tx_chan, &std_cfg));
    ESP_ERROR_CHECK(i2s_channel_enable(s_tx_chan));

    s_channels_mutex = xSemaphoreCreateMutex();
    memset(s_channels, 0, sizeof(s_channels));

    // Pinned to Core 0, with Wi-Fi and the camera decoder (Core 1 has the game and the panel's refresh).
    xTaskCreatePinnedToCore(audio_mixer_task, "audio_mixer", 4096, NULL, 5, NULL, 0);

    s_sfx_queue = xQueueCreate(4, sizeof(sfx_list_t));
    if (s_sfx_queue && xTaskCreatePinnedToCore(sfx_task, "sfx", 4096, NULL, 4, NULL, 0) != pdPASS) {
        vQueueDelete(s_sfx_queue);
        s_sfx_queue = NULL;
        ESP_LOGE(TAG, "sfx: no memory for the sound-effects task — sound effects are off");
    }

    ESP_LOGI(TAG, "audio up: I2S 44.1kHz mono, %d channels", AUDIO_MAX_CHANNELS);
}


// A facing / step direction (the player, tap-to-walk).
typedef enum {
    DIR_CENTER     = 0,
    DIR_UP         = 1,
    DIR_DOWN       = 2,
    DIR_LEFT       = 3,
    DIR_RIGHT      = 4,
    DIR_UP_LEFT    = 5,
    DIR_UP_RIGHT   = 6,
    DIR_DOWN_LEFT  = 7,
    DIR_DOWN_RIGHT = 8
} direction_t;

#if ESPNOW_CAMERA_ENABLED   // game_config.h — the ESP32-CAM link
// ---- ESP32-CAM link ---------------------------------------------------
// The CAM's SoftAP MAC (NOT its STA MAC). The CAM firmware prints it at
// boot; paste it here once the board arrives.
static const uint8_t CAM_MAC[6] = {0x68, 0x09, 0x47, 0x09, 0x81, 0xC5};

#define CAM_MAX_CHUNKS   ((CAM_JPEG_MAX_BYTES + CAM_CHUNK_BYTES - 1) / CAM_CHUNK_BYTES)
#define CAM_TIMEOUT_MS   10000   // give up on a capture that never completes
#define CAM_PREVIEW_TIMEOUT_MS 4000   // a live-view frame later than this is asked for again
#define CAM_IMG_PIXELS   (CAM_OUT_SIZE * CAM_OUT_SIZE)

static SemaphoreHandle_t s_cam_mutex;        // guards everything below
static SemaphoreHandle_t s_cam_decode_sem;   // given when a JPEG is handed to the decoder

// The receive side and the decoder each own a JPEG buffer, so the next live-view
// frame is requested and received while the previous one is still decoding:
//   chunks -> s_cam_jpeg --(last chunk: buffers swap)--> s_cam_dec_jpeg -> decoder
//          -> s_cam_img_back --(swap)--> s_cam_img -> cam_take_result()
static bool        s_cam_active;             // a request is in flight
static bool        s_cam_decoding;           // decode task owns s_cam_dec_jpeg and s_cam_img_back
static bool        s_cam_rx_full;            // s_cam_jpeg holds a whole JPEG the decoder has not taken yet
static TickType_t  s_cam_started;            // when the current request was sent
static uint8_t     s_cam_frame_id;           // id of the last request we sent
static uint8_t     s_cam_gen;                // bumped by cam_cancel(): frames from before it are dropped

static cam_boxes_msg_t s_cam_boxes;          // boxes for the current request
static bool        s_cam_have_boxes;
static bool        s_cam_have_image;         // s_cam_img holds this request's photo
static bool        s_cam_result_new;         // complete (see s_cam_need_boxes) and not yet taken
static bool        s_cam_need_boxes;         // true: photo AND boxes complete a request; false (live-view preview): the photo alone does

static uint8_t    *s_cam_jpeg;               // PSRAM: JPEG being reassembled
static uint32_t    s_cam_jpeg_len;
static uint8_t     s_cam_rx_frame, s_cam_rx_gen;     // request and generation s_cam_jpeg belongs to
static uint16_t    s_cam_chunks_total;
static uint16_t    s_cam_chunks_got;
static uint8_t     s_cam_chunk_seen[CAM_MAX_CHUNKS];

static uint8_t    *s_cam_dec_jpeg;           // PSRAM: JPEG the decoder is working on
static uint32_t    s_cam_dec_len;
static uint8_t     s_cam_dec_frame, s_cam_dec_gen;

static uint16_t   *s_cam_img;                // PSRAM: newest decoded 480x480 RGB565
static uint16_t   *s_cam_img_back;           // PSRAM: the decoder writes here, then swaps it with s_cam_img

// The outline bitmap of the current request (CAM_OUTLINE_BYTES, 1 bit per
// pixel). It arrives before the boxes, which then complete the result.
static uint8_t    *s_cam_outline;            // PSRAM
static bool        s_cam_have_outline;       // all of it arrived for this request
static uint16_t    s_cam_ol_chunks_total, s_cam_ol_chunks_got;
static uint8_t     s_cam_ol_seen[CAM_OUTLINE_CHUNKS];

// The AI flow (CAM_MSG_APPRAISE): what the CAM tells the player, and the AI's
// names for the boxes. The CAM may be away (on the real Wi-Fi) this long.
#define CAM_APPRAISE_TIMEOUT_MS 180000
static char             s_cam_status[CAM_STATUS_MAX + 1];
static uint8_t          s_cam_status_kind, s_cam_status_secs;
static bool             s_cam_status_new;
static cam_labels_msg_t s_cam_labels;
static bool             s_cam_have_labels;
static cam_prices_msg_t s_cam_prices;       // eBay prices for the boxes
static bool             s_cam_have_prices;
static cam_trait_t      s_cam_traits[CAM_MAX_BOXES][CAM_TRAITS_PER];   // the AI's traits for the boxes
static int              s_cam_traits_n;     // boxes covered by the parts so far
static bool             s_cam_have_traits;
static cam_kinds_msg_t  s_cam_kinds;        // each box's kind (the daily selling limit)
static bool             s_cam_have_kinds;

// Marks the result ready once both halves have arrived.
// Caller must hold s_cam_mutex.
static void cam_check_complete(void)
{
    if (s_cam_active && s_cam_have_image && (s_cam_have_boxes || !s_cam_need_boxes)) {
        s_cam_result_new = true;
        s_cam_active = false;
    }
}

// Gives the whole JPEG in s_cam_jpeg to the decoder by swapping the two JPEG
// buffers, so the receive side is free for the next frame at once.
// Caller must hold s_cam_mutex, and the decoder must be idle.
static void cam_start_decode(void)
{
    uint8_t *t = s_cam_dec_jpeg;
    s_cam_dec_jpeg  = s_cam_jpeg;
    s_cam_jpeg      = t;
    s_cam_dec_len   = s_cam_jpeg_len;
    s_cam_dec_frame = s_cam_rx_frame;
    s_cam_dec_gen   = s_cam_rx_gen;
    s_cam_rx_full   = false;
    s_cam_decoding  = true;
    xSemaphoreGive(s_cam_decode_sem);
}

// Sends a request (type + frame id) to the CAM and gets the receive
// side ready for the answer. Returns false if a request is still in flight
// (and has not timed out) or the send could not be queued.
//   fresh_frame: true  = new frame id, forget the previous photo (capture, preview)
//                false = keep the frame id AND the photo already decoded (appraise:
//                        the CAM must be asked about the frame we are looking at)
//   need_boxes:  true  = boxes (and the photo) complete the request
//                false = the photo alone completes it (a live-view preview)
// known: for CAM_MSG_APPRAISE, the kinds the AI should match things to (NULL = none).
static bool cam_send_request(uint8_t type, bool fresh_frame, bool need_boxes, uint32_t timeout_ms,
                             const char (*known)[CAM_KIND_LEN], int known_n)
{
    static cam_appraise_msg_t msg;   // a plain request is just its first two bytes

    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    bool timed_out = s_cam_active &&
                     (xTaskGetTickCount() - s_cam_started) >= pdMS_TO_TICKS(timeout_ms);
    // A preview may go out while the previous frame is still decoding. Anything
    // that needs boxes waits for the decoder, so s_cam_img is settled first.
    bool pipeline_busy = s_cam_rx_full || (need_boxes && s_cam_decoding);
    if (!s_cam_jpeg || !s_cam_img || pipeline_busy || (s_cam_active && !timed_out) ||
        (!fresh_frame && !s_cam_have_image)) {
        xSemaphoreGive(s_cam_mutex);
        ESP_LOGD(TAG, "cam: not ready for a new request (busy, or buffers/photo missing)");
        return false;
    }
    if (fresh_frame) {
        s_cam_frame_id++;
        s_cam_have_image = false;
    }
    s_cam_active       = true;
    s_cam_started      = xTaskGetTickCount();
    s_cam_need_boxes   = need_boxes;
    s_cam_have_boxes   = false;
    if (need_boxes) s_cam_result_new = false;   // a decoded preview not yet shown stays valid
    s_cam_chunks_total = 0;   // stray chunks are rejected until a fresh IMG_START
    s_cam_chunks_got   = 0;
    s_cam_have_outline    = false;
    s_cam_ol_chunks_total = 0;
    s_cam_ol_chunks_got   = 0;
    if (need_boxes) {
        s_cam_have_labels = s_cam_have_prices = s_cam_have_traits = s_cam_have_kinds = s_cam_status_new = false;
        s_cam_traits_n = 0;
    }
    msg.type              = type;
    msg.frame_id          = s_cam_frame_id;
    xSemaphoreGive(s_cam_mutex);

    size_t len = sizeof(cam_request_msg_t);
    if (type == CAM_MSG_APPRAISE) {
        msg.count = (uint8_t)(known_n < 0 ? 0 : known_n > CAM_KNOWN_MAX ? CAM_KNOWN_MAX : known_n);
        if (msg.count) memcpy(msg.known, known, (size_t)msg.count * CAM_KIND_LEN);
        len = CAM_APPRAISE_HEADER_SIZE + (size_t)msg.count * CAM_KIND_LEN;
    }
    esp_err_t err = esp_now_send(CAM_MAC, (const uint8_t *)&msg, len);
    if (err != ESP_OK) {
        ESP_LOGW(TAG, "cam: request 0x%02X failed: %s", (unsigned)type, esp_err_to_name(err));
        xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
        s_cam_active = false;
        xSemaphoreGive(s_cam_mutex);
        return false;
    }
    ESP_LOGI(TAG, "cam: request 0x%02X sent (frame %u)", (unsigned)type, (unsigned)msg.frame_id);
    return true;
}

// Live view: the CAM photographs for the S3 only. The photo alone completes
// the request, so cam_take_result(NULL, pixels) returns it.
bool cam_request_preview(void) { return cam_send_request(CAM_MSG_PREVIEW, true, false, CAM_PREVIEW_TIMEOUT_MS, NULL, 0); }

// Photo button: the CAM takes the photo at 640x640 (kept for the AI and SAM 3)
// and sends back its 480x480 copy, which arrives like a live-view frame.
bool cam_request_snap(void) { return cam_send_request(CAM_MSG_SNAP, true, false, CAM_PREVIEW_TIMEOUT_MS, NULL, 0); }

// Photo button: ask the CAM what is in the frame on screen (it stays in s_cam_img).
// Status lines arrive meanwhile (cam_take_status); the names (cam_take_labels), the
// traits (cam_take_traits), the prices (cam_take_prices) and the outline + boxes
// (cam_take_result) when it is done.
// known: the kinds the player has sold today or holds (the AI matches things to them).
bool cam_request_appraise(const char (*known)[CAM_KIND_LEN], int known_n)
{
    return cam_send_request(CAM_MSG_APPRAISE, false, true, CAM_APPRAISE_TIMEOUT_MS, known, known_n);
}

// ---- Camera Wi-Fi: the networks the CAM goes online with (Settings > Camera Wi-Fi) ----
// One request at a time, with its own ids (s_cam_net_id): only replies to the last one count.
// The CAM never sends passwords back; the S3 only sends a new one when it is changed.
#define CAM_NET_TIMEOUT_MS      3000     // list / save: the CAM answers at once (unless it is online)
#define CAM_NET_TEST_TIMEOUT_MS 200000   // a test may try every network twice
static uint8_t            s_cam_net_id;
static bool               s_cam_net_waiting;     // a request is out
static uint8_t            s_cam_net_type;        // ...which (CAM_MSG_NET_*)
static TickType_t         s_cam_net_sent;
static cam_net_list_msg_t s_cam_net_list;        // the CAM's networks, as last heard
static bool               s_cam_net_list_new;
static char               s_cam_net_status[CAM_STATUS_MAX + 1];
static uint8_t            s_cam_net_status_kind, s_cam_net_status_secs;
static bool               s_cam_net_status_new;

// msg: a cam_request_msg_t (NET_GET, NET_TEST) or a cam_net_set_msg_t; its frame_id is set here.
static bool cam_net_send(void *msg, size_t len)
{
    uint8_t *m = msg;
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    m[1] = ++s_cam_net_id;
    s_cam_net_waiting    = true;
    s_cam_net_type       = m[0];
    s_cam_net_sent       = xTaskGetTickCount();
    s_cam_net_list_new   = false;
    s_cam_net_status_new = false;
    xSemaphoreGive(s_cam_mutex);
    esp_err_t err = esp_now_send(CAM_MAC, m, len);
    if (err != ESP_OK) {
        ESP_LOGW(TAG, "cam: Wi-Fi request 0x%02X failed: %s", (unsigned)m[0], esp_err_to_name(err));
        xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
        s_cam_net_waiting = false;
        xSemaphoreGive(s_cam_mutex);
        return false;
    }
    return true;
}

static bool cam_net_request(uint8_t type)   // CAM_MSG_NET_GET or CAM_MSG_NET_TEST
{
    cam_request_msg_t m = { .type = type };
    return cam_net_send(&m, sizeof(m));
}

// op: CAM_NET_OP_*. net / pass only for CAM_NET_OP_SAVE (pass NULL = keep the saved one).
static bool cam_net_change(uint8_t op, int slot, const cam_net_info_t *net, const char *pass)
{
    static cam_net_set_msg_t m;
    memset(&m, 0, sizeof(m));
    m.type = CAM_MSG_NET_SET;
    m.op   = op;
    m.slot = (uint8_t)slot;
    if (net) m.net = *net;
    if (op == CAM_NET_OP_SAVE) {
        if (pass) strlcpy(m.pass, pass, sizeof(m.pass));
        else      m.net.flags |= CAM_NET_KEEP_PASS;
    }
    bool ok = cam_net_send(&m, sizeof(m));
    memset(m.pass, 0, sizeof(m.pass));
    return ok;
}

typedef enum { CAM_NET_EV_NONE, CAM_NET_EV_LIST, CAM_NET_EV_STATUS, CAM_NET_EV_TIMEOUT } cam_net_ev_t;

// What happened to the request since the last call: the list came (copied to *list), a
// status line (STATUS kind + secs; AWAY means a test is still going), or no answer in time.
static cam_net_ev_t cam_net_poll(cam_net_list_msg_t *list, char *status, size_t size, uint8_t *kind, uint8_t *secs)
{
    cam_net_ev_t ev = CAM_NET_EV_NONE;
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    if (s_cam_net_list_new) {
        *list = s_cam_net_list;
        s_cam_net_list_new = false;
        ev = CAM_NET_EV_LIST;
    } else if (s_cam_net_status_new) {
        strlcpy(status, s_cam_net_status, size);
        *kind = s_cam_net_status_kind;
        *secs = s_cam_net_status_secs;
        s_cam_net_status_new = false;
        ev = CAM_NET_EV_STATUS;
    } else if (s_cam_net_waiting) {
        uint32_t limit = s_cam_net_type == CAM_MSG_NET_TEST ? CAM_NET_TEST_TIMEOUT_MS : CAM_NET_TIMEOUT_MS;
        if ((xTaskGetTickCount() - s_cam_net_sent) >= pdMS_TO_TICKS(limit)) {
            s_cam_net_waiting = false;
            ev = CAM_NET_EV_TIMEOUT;
        }
    }
    xSemaphoreGive(s_cam_mutex);
    return ev;
}

static bool cam_net_busy(void)
{
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    bool busy = s_cam_net_waiting;
    xSemaphoreGive(s_cam_mutex);
    return busy;
}

// cam_handle_packet's part: a reply to the Camera Wi-Fi request. Caller holds s_cam_mutex.
static bool cam_net_handle_packet(const uint8_t *data, int len)
{
    const uint8_t type = data[0];
    if (!s_cam_net_waiting || data[1] != s_cam_net_id) return false;
    if (type == CAM_MSG_NET_LIST && len >= (int)CAM_NET_LIST_HEADER_SIZE) {
        const cam_net_list_msg_t *m = (const cam_net_list_msg_t *)data;
        int n = m->count <= CAM_NET_MAX ? m->count : CAM_NET_MAX;
        if ((size_t)len < CAM_NET_LIST_HEADER_SIZE + (size_t)n * sizeof(cam_net_info_t))
            n = (len - (int)CAM_NET_LIST_HEADER_SIZE) / (int)sizeof(cam_net_info_t);
        memset(&s_cam_net_list, 0, sizeof(s_cam_net_list));
        memcpy(&s_cam_net_list, data, CAM_NET_LIST_HEADER_SIZE + (size_t)n * sizeof(cam_net_info_t));
        s_cam_net_list.count = (uint8_t)n;
        for (int i = 0; i < n; i++) {
            cam_net_info_t *e = &s_cam_net_list.net[i];
            e->ssid[sizeof(e->ssid) - 1] = e->user[sizeof(e->user) - 1] = e->anon[sizeof(e->anon) - 1] = '\0';
        }
        s_cam_net_list_new = true;
        s_cam_net_waiting  = false;
        return true;
    }
    if (type == CAM_MSG_STATUS && len >= (int)CAM_STATUS_HEADER_SIZE && len <= (int)sizeof(cam_status_msg_t)) {
        const cam_status_msg_t *m = (const cam_status_msg_t *)data;
        int n = len - (int)CAM_STATUS_HEADER_SIZE;
        memcpy(s_cam_net_status, m->text, n);
        s_cam_net_status[n]   = '\0';
        s_cam_net_status_kind = m->kind;
        s_cam_net_status_secs = m->secs;
        s_cam_net_status_new  = true;
        if (m->kind != CAM_STATUS_AWAY) s_cam_net_waiting = false;   // the request is over
        return true;
    }
    return false;
}

// The newest status line, once. Returns false if none came since the last call.
static bool cam_take_status(char *out, size_t size, uint8_t *kind, uint8_t *secs)
{
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    bool have = s_cam_status_new;
    if (have) {
        strlcpy(out, s_cam_status, size);
        *kind = s_cam_status_kind;
        *secs = s_cam_status_secs;
        s_cam_status_new = false;
    }
    xSemaphoreGive(s_cam_mutex);
    return have;
}

// The eBay prices for the current request's boxes (cents of *currency, mid 0 = none).
// Returns how many, or -1 if none came.
static int cam_take_prices(cam_price_t out[CAM_MAX_BOXES], char currency[4])
{
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    int n = s_cam_have_prices ? s_cam_prices.count : -1;
    if (n > 0) memcpy(out, s_cam_prices.price, (size_t)n * sizeof(cam_price_t));
    if (n >= 0) memcpy(currency, s_cam_prices.currency, 4);
    xSemaphoreGive(s_cam_mutex);
    return n;
}

// The AI's names for the current request's boxes. Returns how many, or -1 if none came.
static int cam_take_labels(char out[CAM_MAX_BOXES][CAM_LABEL_LEN])
{
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    int n = s_cam_have_labels ? s_cam_labels.count : -1;
    if (n > 0) memcpy(out, s_cam_labels.label, (size_t)n * CAM_LABEL_LEN);
    xSemaphoreGive(s_cam_mutex);
    return n;
}

// Each of the current request's boxes' kind. Returns how many, or -1 if none came.
static int cam_take_kinds(char out[CAM_MAX_BOXES][CAM_KIND_LEN])
{
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    int n = s_cam_have_kinds ? s_cam_kinds.count : -1;
    if (n > 0) memcpy(out, s_cam_kinds.kind, (size_t)n * CAM_KIND_LEN);
    xSemaphoreGive(s_cam_mutex);
    return n;
}

// The AI's traits for the current request's boxes. Returns how many boxes, or -1 if none came.
static int cam_take_traits(cam_trait_t out[CAM_MAX_BOXES][CAM_TRAITS_PER])
{
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    int n = s_cam_have_traits ? s_cam_traits_n : -1;
    if (n > 0) memcpy(out, s_cam_traits, (size_t)n * CAM_TRAITS_ITEM_SIZE);
    xSemaphoreGive(s_cam_mutex);
    return n;
}

// True while a request is in flight and younger than timeout_ms.
static bool cam_busy(uint32_t timeout_ms)
{
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    bool busy = s_cam_active &&
                (xTaskGetTickCount() - s_cam_started) < pdMS_TO_TICKS(timeout_ms);
    xSemaphoreGive(s_cam_mutex);
    return busy;
}

// Live view, photo button pressed: no new previews are requested, and this
// tells when the frames already on their way have landed.
typedef enum {
    CAM_DRAIN_WAIT,     // a frame is still in flight, decoding, or decoded but not taken
    CAM_DRAIN_LATEST,   // the newest requested frame is on screen: the CAM holds exactly it
    CAM_DRAIN_LOST,     // nothing on its way, but the newest frame never arrived
} cam_drain_t;

static cam_drain_t cam_live_drain(uint32_t timeout_ms)
{
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    bool in_flight = s_cam_active &&
                     (xTaskGetTickCount() - s_cam_started) < pdMS_TO_TICKS(timeout_ms);
    cam_drain_t st = (in_flight || s_cam_rx_full || s_cam_decoding || s_cam_result_new) ? CAM_DRAIN_WAIT
                   : s_cam_have_image ? CAM_DRAIN_LATEST : CAM_DRAIN_LOST;
    xSemaphoreGive(s_cam_mutex);
    return st;
}

// Abandons whatever is in flight: later packets for it are dropped, frames
// still being received or decoded are thrown away, and a finished-but-untaken
// result is discarded.
static void cam_cancel(void)
{
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    s_cam_active     = false;
    s_cam_result_new = false;
    s_cam_gen++;
    xSemaphoreGive(s_cam_mutex);
}

// If a complete result (boxes + photo) has arrived since the last call,
// copies the boxes into *boxes_out and the 480x480 RGB565 photo into
// pixels_out (must hold 480*480 uint16_t; pass s_fb to show it directly),
// then returns true. Either pointer may be NULL to skip that part.
// Only boxes_out->count entries of boxes[] are valid.
// outline_out (CAM_OUTLINE_BYTES, may be NULL) gets the outline bitmap;
// *outline_ok says whether one came with this result.
bool cam_take_result(cam_boxes_msg_t *boxes_out, uint16_t *pixels_out, uint8_t *outline_out, bool *outline_ok)
{
    bool have = false;
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    if (s_cam_result_new) {
        if (boxes_out)  *boxes_out = s_cam_boxes;
        if (pixels_out) memcpy(pixels_out, s_cam_img, CAM_IMG_PIXELS * sizeof(uint16_t));
        bool ol = s_cam_need_boxes && s_cam_have_outline;   // a live-view frame never has one
        if (outline_ok) *outline_ok = ol;
        if (outline_out && ol) memcpy(outline_out, s_cam_outline, CAM_OUTLINE_BYTES);
        s_cam_result_new = false;
        have = true;
    }
    xSemaphoreGive(s_cam_mutex);
    return have;
}

// Decodes the reassembled JPEG (480x480 from an OV2640, else 640x480) and
// keeps its center 480x480 square. Runs on core 0 at low priority so audio (core 1) and
// the WiFi task are not starved by the decode.
// The decoder's own default (3100 bytes) only fits the OV2640's 4:2:2 frames; the
// photo button's 480x480 copy is re-encoded on the CAM at 4:2:0, which needs more.
static uint8_t s_cam_dec_work[8192];

static void cam_decode_task(void *arg)
{
    for (;;) {
        xSemaphoreTake(s_cam_decode_sem, portMAX_DELAY);

        // s_cam_dec_jpeg and s_cam_img_back belong to this task until it clears
        // s_cam_decoding; the receive side meanwhile fills s_cam_jpeg.
        esp_jpeg_image_cfg_t cfg = {
            .indata      = s_cam_dec_jpeg,
            .indata_size = s_cam_dec_len,
            .out_format  = JPEG_IMAGE_FORMAT_RGB565,
            .out_scale   = JPEG_IMAGE_SCALE_0,
            .advanced    = { .working_buffer = s_cam_dec_work, .working_buffer_size = sizeof(s_cam_dec_work) },
        };
        esp_jpeg_image_output_t info = {0};
        uint16_t *tmp = NULL;
        bool ok = false;
        int64_t t_start = esp_timer_get_time();   // microseconds, for the log below

        if (esp_jpeg_get_image_info(&cfg, &info) == ESP_OK &&
            info.width >= CAM_OUT_SIZE && info.height >= CAM_OUT_SIZE) {
            // Already 480x480 (the CAM windows its sensor): decode straight into
            // s_cam_img_back. Anything bigger goes through tmp and is cropped below.
            bool direct = (info.width == CAM_OUT_SIZE && info.height == CAM_OUT_SIZE);
            if (!direct) tmp = heap_caps_malloc(info.output_len, MALLOC_CAP_SPIRAM);
            if (direct || tmp) {
                esp_jpeg_image_cfg_t dcfg = cfg;   // fresh copy for the real decode
                dcfg.priv.read    = 0;
                dcfg.outbuf       = direct ? (uint8_t *)s_cam_img_back : (uint8_t *)tmp;
                dcfg.outbuf_size  = info.output_len;
                ok = (esp_jpeg_decode(&dcfg, &info) == ESP_OK);
            }
        }

        if (ok && tmp) {
            int cx = (info.width  - CAM_OUT_SIZE) / 2;   // 80 for a 640-wide photo
            int cy = (info.height - CAM_OUT_SIZE) / 2;   // 0 for a 480-tall photo
            for (int y = 0; y < CAM_OUT_SIZE; y++) {
                memcpy(&s_cam_img_back[y * CAM_OUT_SIZE],
                       &tmp[(y + cy) * info.width + cx],
                       CAM_OUT_SIZE * sizeof(uint16_t));
            }
        } else if (!ok) {
            ESP_LOGW(TAG, "cam: JPEG decode failed (or photo smaller than %d px)", CAM_OUT_SIZE);
        }
        if (tmp) heap_caps_free(tmp);

        xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
        if (ok && s_cam_dec_gen == s_cam_gen) {   // not cancelled while decoding
            uint16_t *t = s_cam_img;
            s_cam_img      = s_cam_img_back;
            s_cam_img_back = t;
            if (s_cam_dec_frame == s_cam_frame_id) {
                s_cam_have_image = true;
                if (s_cam_need_boxes) cam_check_complete();   // an appraisal: done once the boxes are in too
                else                  s_cam_result_new = true;
            } else {
                s_cam_result_new = true;   // an older live-view frame; the next one is already on its way
            }
            ESP_LOGI(TAG, "cam: photo %u decoded (%ux%u -> %dx%d crop) in %d ms",
                     (unsigned)s_cam_dec_frame, (unsigned)info.width, (unsigned)info.height,
                     CAM_OUT_SIZE, CAM_OUT_SIZE, (int)((esp_timer_get_time() - t_start) / 1000));
        } else if (!ok && s_cam_need_boxes && s_cam_dec_frame == s_cam_frame_id) {
            s_cam_active = false;   // this capture is dead; a new request is allowed
        }
        if (s_cam_rx_full) cam_start_decode();   // the next frame arrived meanwhile: straight on to it
        else               s_cam_decoding = false;
        xSemaphoreGive(s_cam_mutex);
    }
}

// Starts the decode task. Called once from espnow_begin(). The ~1.1 MB of
// PSRAM buffers are NOT allocated here: only while the camera is in use
// (cam_buffers_acquire() .. cam_buffers_release()). Until then they are NULL
// and cam_send_request() refuses to start.
static void cam_begin(void)
{
    s_cam_decode_sem = xSemaphoreCreateBinary();
    if (!s_cam_decode_sem) { ESP_LOGE(TAG, "cam: no semaphore — camera disabled"); return; }
    // Either core: Core 1 is the game's (same priority — pinned there they'd
    // take turns) and Core 0 has Wi-Fi and audio, so it
    // runs wherever there's room.
    xTaskCreatePinnedToCore(cam_decode_task, "cam_decode", 4096, NULL, 1, NULL, tskNO_AFFINITY);   // peak 1.8 KB seen (dev link "stacks", live view)
}

static bool s_cam_release_pending = false;   // released, waiting for the decoder to finish its last frame

// The receive/decode buffers, for the camera screens. Reopening the camera
// before an earlier release went through just keeps them.
static bool cam_buffers_acquire(void)
{
    s_cam_release_pending = false;
    if (s_cam_jpeg) return true;
    if (!s_cam_decode_sem) return false;
    uint16_t *img  = heap_caps_calloc(CAM_IMG_PIXELS, sizeof(uint16_t), MALLOC_CAP_SPIRAM);   // biggest first
    uint16_t *back = heap_caps_malloc(CAM_IMG_PIXELS * sizeof(uint16_t), MALLOC_CAP_SPIRAM);
    uint8_t  *jpeg = heap_caps_malloc(CAM_JPEG_MAX_BYTES, MALLOC_CAP_SPIRAM);
    uint8_t  *dec  = heap_caps_malloc(CAM_JPEG_MAX_BYTES, MALLOC_CAP_SPIRAM);
    uint8_t  *ol   = heap_caps_malloc(CAM_OUTLINE_BYTES, MALLOC_CAP_SPIRAM);
    if (!img || !back || !jpeg || !dec || !ol) {
        ESP_LOGE(TAG, "cam: not enough PSRAM for the photo buffers");
        heap_caps_free(img); heap_caps_free(back); heap_caps_free(jpeg); heap_caps_free(dec); heap_caps_free(ol);
        return false;
    }
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    s_cam_img = img; s_cam_img_back = back; s_cam_jpeg = jpeg; s_cam_dec_jpeg = dec; s_cam_outline = ol;
    s_cam_have_image = false;
    xSemaphoreGive(s_cam_mutex);
    return true;
}

// Frees them once nothing touches them: a request cancelled (so the receive
// side drops every packet) and the decoder idle. If it's still on a frame,
// cam_release_poll() finishes the job on a later frame.
static void cam_release_poll(void)
{
    if (!s_cam_release_pending) return;
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    if (s_cam_decoding) { xSemaphoreGive(s_cam_mutex); return; }   // owns s_cam_dec_jpeg / s_cam_img_back right now
    uint16_t *img = s_cam_img, *back = s_cam_img_back;
    uint8_t  *jpeg = s_cam_jpeg, *dec = s_cam_dec_jpeg, *ol = s_cam_outline;
    s_cam_img = s_cam_img_back = NULL;
    s_cam_jpeg = s_cam_dec_jpeg = s_cam_outline = NULL;
    s_cam_have_image = s_cam_result_new = s_cam_active = s_cam_rx_full = false;
    xSemaphoreGive(s_cam_mutex);
    heap_caps_free(img); heap_caps_free(back); heap_caps_free(jpeg); heap_caps_free(dec); heap_caps_free(ol);
    s_cam_release_pending = false;
}

static void cam_buffers_release(void)
{
    if (!s_cam_jpeg) return;
    cam_cancel();                              // late packets are dropped from now on
    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);
    s_cam_rx_full = false;                     // a queued frame would only be decoded to be thrown away
    xSemaphoreGive(s_cam_mutex);
    s_cam_release_pending = true;
    cam_release_poll();
}

// Runs in the WiFi task for every packet from CAM_MAC, so it only
// validates and stores. The heavy work happens in cam_decode_task.
static void cam_handle_packet(const uint8_t *data, int len)
{
    if (len < 2) return;
    const uint8_t type     = data[0];
    const uint8_t frame_id = data[1];

    xSemaphoreTake(s_cam_mutex, portMAX_DELAY);

    if (cam_net_handle_packet(data, len)) { xSemaphoreGive(s_cam_mutex); return; }

    if ((type == CAM_MSG_STATUS || type == CAM_MSG_LABELS || type == CAM_MSG_PRICES || type == CAM_MSG_TRAITS ||
         type == CAM_MSG_KINDS) && frame_id == s_cam_frame_id) {
        if (type == CAM_MSG_STATUS && len >= (int)CAM_STATUS_HEADER_SIZE && len <= (int)sizeof(cam_status_msg_t)) {
            const cam_status_msg_t *m = (const cam_status_msg_t *)data;
            int n = len - (int)CAM_STATUS_HEADER_SIZE;
            memcpy(s_cam_status, m->text, n);
            s_cam_status[n]   = '\0';
            s_cam_status_kind = m->kind;
            s_cam_status_secs = m->secs;
            s_cam_status_new  = true;
            if (m->kind == CAM_STATUS_ERROR) s_cam_active = false;   // the request is over
        } else if (type == CAM_MSG_LABELS && len >= (int)CAM_LABELS_HEADER_SIZE) {
            const cam_labels_msg_t *m = (const cam_labels_msg_t *)data;
            if (m->count <= CAM_MAX_BOXES && (size_t)len >= CAM_LABELS_HEADER_SIZE + (size_t)m->count * CAM_LABEL_LEN) {
                memcpy(&s_cam_labels, m, CAM_LABELS_HEADER_SIZE + (size_t)m->count * CAM_LABEL_LEN);
                for (int i = 0; i < m->count; i++) s_cam_labels.label[i][CAM_LABEL_LEN - 1] = '\0';
                s_cam_have_labels = true;
            }
        } else if (type == CAM_MSG_PRICES && len >= (int)CAM_PRICES_HEADER_SIZE) {
            const cam_prices_msg_t *m = (const cam_prices_msg_t *)data;
            if (m->count <= CAM_MAX_BOXES && (size_t)len >= CAM_PRICES_HEADER_SIZE + (size_t)m->count * sizeof(cam_price_t)) {
                memcpy(&s_cam_prices, m, CAM_PRICES_HEADER_SIZE + (size_t)m->count * sizeof(cam_price_t));
                s_cam_prices.currency[3] = '\0';
                s_cam_have_prices = true;
            }
        } else if (type == CAM_MSG_TRAITS && len >= (int)CAM_TRAITS_HEADER_SIZE) {
            const cam_traits_msg_t *m = (const cam_traits_msg_t *)data;   // one part: boxes first..first+count-1
            if (m->count <= CAM_TRAITS_BOXES && m->first + m->count <= CAM_MAX_BOXES &&
                (size_t)len >= CAM_TRAITS_HEADER_SIZE + (size_t)m->count * CAM_TRAITS_ITEM_SIZE) {
                if (!s_cam_have_traits) memset(s_cam_traits, 0, sizeof(s_cam_traits));
                memcpy(s_cam_traits[m->first], m->trait, (size_t)m->count * CAM_TRAITS_ITEM_SIZE);
                for (int i = m->first; i < m->first + m->count; i++)
                    for (int t = 0; t < CAM_TRAITS_PER; t++) s_cam_traits[i][t].text[CAM_TRAIT_LEN - 1] = '\0';
                if (m->first + m->count > s_cam_traits_n) s_cam_traits_n = m->first + m->count;
                s_cam_have_traits = true;
            }
        } else if (type == CAM_MSG_KINDS && len >= (int)CAM_KINDS_HEADER_SIZE) {
            const cam_kinds_msg_t *m = (const cam_kinds_msg_t *)data;
            if (m->count <= CAM_MAX_BOXES && (size_t)len >= CAM_KINDS_HEADER_SIZE + (size_t)m->count * CAM_KIND_LEN) {
                memcpy(&s_cam_kinds, m, CAM_KINDS_HEADER_SIZE + (size_t)m->count * CAM_KIND_LEN);
                for (int i = 0; i < m->count; i++) s_cam_kinds.kind[i][CAM_KIND_LEN - 1] = '\0';
                s_cam_have_kinds = true;
            }
        }
        xSemaphoreGive(s_cam_mutex);
        return;
    }
    if (!s_cam_active || frame_id != s_cam_frame_id) {   // stale or unexpected
        xSemaphoreGive(s_cam_mutex);
        return;
    }

    switch (type) {
    case CAM_MSG_BOXES: {
        const cam_boxes_msg_t *m = (const cam_boxes_msg_t *)data;
        if (len >= (int)CAM_BOXES_HEADER_SIZE && m->count <= CAM_MAX_BOXES &&
            (size_t)len >= CAM_BOXES_HEADER_SIZE + m->count * sizeof(cam_box_t)) {
            memcpy(&s_cam_boxes, m, CAM_BOXES_HEADER_SIZE + m->count * sizeof(cam_box_t));
            s_cam_have_boxes = true;
            cam_check_complete();
            ESP_LOGI(TAG, "cam: %u boxes for frame %u", (unsigned)m->count, (unsigned)frame_id);
        } else {
            ESP_LOGW(TAG, "cam: malformed boxes packet — dropping");
        }
        break;
    }
    case CAM_MSG_IMG_START: {
        const cam_img_start_msg_t *m = (const cam_img_start_msg_t *)data;
        if (len == (int)sizeof(*m) && !s_cam_rx_full &&
            m->jpeg_len > 0 && m->jpeg_len <= CAM_JPEG_MAX_BYTES &&
            m->chunk_count > 0 && m->chunk_count <= CAM_MAX_CHUNKS) {
            s_cam_jpeg_len     = m->jpeg_len;
            s_cam_rx_frame     = frame_id;
            s_cam_rx_gen       = s_cam_gen;
            s_cam_chunks_total = m->chunk_count;
            s_cam_chunks_got   = 0;
            memset(s_cam_chunk_seen, 0, sizeof(s_cam_chunk_seen));
        } else {
            ESP_LOGW(TAG, "cam: bad IMG_START — dropping");
        }
        break;
    }
    case CAM_MSG_IMG_CHUNK: {
        const cam_img_chunk_msg_t *m = (const cam_img_chunk_msg_t *)data;
        int      n   = len - (int)CAM_CHUNK_HEADER_SIZE;
        uint32_t off = (uint32_t)m->index * CAM_CHUNK_BYTES;
        if (n > 0 && !s_cam_rx_full && s_cam_chunks_total > 0 &&
            m->index < s_cam_chunks_total && !s_cam_chunk_seen[m->index] &&
            off + (uint32_t)n <= s_cam_jpeg_len) {
            memcpy(s_cam_jpeg + off, m->data, n);
            s_cam_chunk_seen[m->index] = 1;
            if (++s_cam_chunks_got == s_cam_chunks_total) {
                // Live view: the request is answered, so the next may go out now.
                if (!s_cam_need_boxes) s_cam_active = false;
                if (s_cam_decoding) s_cam_rx_full = true;   // decoder busy: it takes this one when done
                else                cam_start_decode();
            }
        }
        break;
    }
    case CAM_MSG_OUTLINE_START: {   // outline bitmap: sent before the boxes
        const cam_img_start_msg_t *m = (const cam_img_start_msg_t *)data;
        if (len == (int)sizeof(*m) && s_cam_need_boxes &&
            m->jpeg_len == CAM_OUTLINE_BYTES && m->chunk_count == CAM_OUTLINE_CHUNKS) {
            s_cam_ol_chunks_total = m->chunk_count;
            s_cam_ol_chunks_got   = 0;
            s_cam_have_outline    = false;
            memset(s_cam_ol_seen, 0, sizeof(s_cam_ol_seen));
        } else {
            ESP_LOGW(TAG, "cam: bad OUTLINE_START — dropping");
        }
        break;
    }
    case CAM_MSG_OUTLINE_CHUNK: {
        const cam_img_chunk_msg_t *m = (const cam_img_chunk_msg_t *)data;
        int      n   = len - (int)CAM_CHUNK_HEADER_SIZE;
        uint32_t off = (uint32_t)m->index * CAM_CHUNK_BYTES;
        if (n > 0 && s_cam_ol_chunks_total > 0 && m->index < s_cam_ol_chunks_total &&
            !s_cam_ol_seen[m->index] && off + (uint32_t)n <= CAM_OUTLINE_BYTES) {
            memcpy(s_cam_outline + off, m->data, n);
            s_cam_ol_seen[m->index] = 1;
            if (++s_cam_ol_chunks_got == s_cam_ol_chunks_total) s_cam_have_outline = true;
        }
        break;
    }
    }

    xSemaphoreGive(s_cam_mutex);
}
#endif // ESPNOW_CAMERA_ENABLED

// Fires from the WiFi task whenever an ESP-NOW packet arrives: packets from
// the ESP32-CAM go to the camera handler, anything else is ignored.
#if ESPNOW_CAMERA_ENABLED   // game_config.h: the radio is only started for the camera
static void espnow_recv_cb(const esp_now_recv_info_t *info, const uint8_t *data, int len)
{
    if (info && memcmp(info->src_addr, CAM_MAC, 6) == 0) cam_handle_packet(data, len);
}

// Brings up WiFi station mode (no AP connection — ESP-NOW only) and
// starts listening. Channel 1 must match the ESP32-CAM's, or no packets arrive.
void espnow_begin(void)
{
    s_cam_mutex = xSemaphoreCreateMutex();

    ESP_ERROR_CHECK(nvs_flash_init());
    ESP_ERROR_CHECK(esp_netif_init());
    ESP_ERROR_CHECK(esp_event_loop_create_default());

    wifi_init_config_t wifi_cfg = WIFI_INIT_CONFIG_DEFAULT();
    ESP_ERROR_CHECK(esp_wifi_init(&wifi_cfg));
    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_STA));
    ESP_ERROR_CHECK(esp_wifi_start());
    ESP_ERROR_CHECK(esp_wifi_set_channel(1, WIFI_SECOND_CHAN_NONE)); // must match the ESP32-CAM

    ESP_ERROR_CHECK(esp_now_init());
    ESP_ERROR_CHECK(esp_now_register_recv_cb(espnow_recv_cb));

    esp_now_peer_info_t cam_peer = {0};
    memcpy(cam_peer.peer_addr, CAM_MAC, 6);
    cam_peer.channel = 0;              // 0 = stay on the current channel (1)
    cam_peer.ifidx   = WIFI_IF_STA;
    cam_peer.encrypt = false;
    esp_err_t cam_err = esp_now_add_peer(&cam_peer);
    if (cam_err != ESP_OK) {
        ESP_LOGW(TAG, "cam: add_peer failed: %s (is CAM_MAC set?)", esp_err_to_name(cam_err));
    }

    cam_begin();
    ESP_LOGI(TAG, "ESP-NOW up on channel 1 (camera link)");
}
#endif // ESPNOW_CAMERA_ENABLED

// Turns a direction into a one-pixel step.
static void direction_to_delta(direction_t dir, int *dx, int *dy)
{
    switch (dir) {
        case DIR_UP:         *dx =  0; *dy = -1; break;
        case DIR_DOWN:       *dx =  0; *dy =  1; break;
        case DIR_LEFT:       *dx = -1; *dy =  0; break;
        case DIR_RIGHT:      *dx =  1; *dy =  0; break;
        case DIR_UP_LEFT:    *dx = -1; *dy = -1; break;
        case DIR_UP_RIGHT:   *dx =  1; *dy = -1; break;
        case DIR_DOWN_LEFT:  *dx = -1; *dy =  1; break;
        case DIR_DOWN_RIGHT: *dx =  1; *dy =  1; break;
        default:             *dx =  0; *dy =  0; break;
    }
}

// ============================================================
//  MAP LOADING — reads a map file (the same format the map editor's
//  Export button writes) into PSRAM, then reveals it on screen.
//  Caller passes the full path (e.g. map_path_for("meadows")) — no
//  directory is assumed. Fixed at exactly LCD_H_RES x LCD_V_RES for
//  now — no scrolling/camera system yet, per the project's current scope.
//
//  File layout (all multi-byte values little-endian):
//    "MAP2" or "MAP6"          4 bytes
//    width, height             2 x uint16
//    pixels                    width*height x uint16 RGB565, row-major
//    collision bitmask         1 bit/pixel, MSB-first, 1 = blocked
//    layer bitmask             1 bit/pixel, MSB-first, 1 = foreground
//    --- MAP6+ only, from here on ---
//    bundle_count              uint16       shared Frame Bundle table — see
//                                           frame_bundle.h. Used by BOTH the
//                                           animation instances below and the
//                                           breakable section that follows.
//    bundle_count x {
//        w, h                  2 x uint16   size of ONE frame
//        frame_count           uint16
//        interval_ms           uint16
//        loop_count            int16        -1 = forever, else passes to
//                                           play before holding (meaning
//                                           depends on the consumer — see
//                                           frame_bundle.h)
//        pixels                frame_count*w*h x uint16 RGB565, opaque
//    }
//    inst_count                uint16       ambient animation placements
//    inst_count x {
//        x, y                  2 x uint16   top-left corner on screen
//        bundle_index          uint16       which bundle above it plays
//    }
//  A MAP2 file (no bundle table, no animations) is still fully supported.
//  MAP6/MAP7 still load (legacy numeric drops/tools, see the breakable notes).
//  MAP3/MAP4/MAP5 (old formats) are not — re-export from the editor, which
//  writes MAP14 (magic "MAPE": MAP13 + breakable sounds — see the breakable
//  notes; MAP13 = magic "MAPD": MAP12 + breakable falls; MAP12 = magic "MAPC": MAP11 + the action triggers — see the
//  Action triggers notes; MAP11 = magic "MAPB": MAP10 + the tile types — see the
//  Tile types notes; MAP10 = magic "MAPA": breakables that can overlap, then
//  the teleporter section — see the breakable and Teleporters notes). MAP8
//  (breakable items keyed by id), MAP9 (MAP8 + teleporters), MAP10, MAP11,
//  MAP12 and MAP13 still load; maps before MAP11 have no tile types (read_tile() says
//  TILE_NONE), maps before MAP12 no objects with actions, maps before MAP14 no sounds.
// ============================================================

static uint16_t *s_map_pixels = NULL; // PSRAM, LCD_H_RES*LCD_V_RES RGB565 pixels of the currently loaded map
static uint8_t  *s_map_hitbox = NULL; // PSRAM, 1 bit per pixel, MSB-first — same layout the editor exports
static uint8_t  *s_map_fgmask = NULL; // PSRAM, 1 bit per pixel, MSB-first, same layout as s_map_hitbox.
                                       // Set = layer 1 ("foreground" — drawn in FRONT of the player, so
                                       // the player appears to go UNDER it). Any pixel that's NOT set is
                                       // layer -1 ("ground") by default — there's no separate ground
                                       // bitmask because that state is just "everything else".
static int       s_map_w = 0, s_map_h = 0;
static bool      s_map_loaded = false;
static char      s_map_path[MAP_PATH_MAX];  // full path of the loaded map ("/sdcard/CaptureIt/maps/meadows/meadows.map")
static char      s_current_map_name[32];    // its file name without folder or extension ("map") — see MAP NAME
static uint16_t  s_map_inst      = 0;       // the loaded map is the inside of placed building #s_map_inst (its own save); 0 = an ordinary map — see PLACEMENT
static uint16_t  s_load_inst_next = 0;      // load_map() makes the map it loads that building's inside (tp_travel(), a saved game), then clears it

// ============================================================
//  FRAME BUNDLES + MAP ANIMATIONS — the shared bundle table and ambient
//  animation instances loaded from a MAP6+ file (layout above).
//
//  How it fits together:
//   - s_map_pixels always holds the FIRST frame of every animation, so
//     the map looks right even before the animation player has run
//     (e.g. during the load fade-in) or if a file has no animations.
//   - Each animation instance owns a rectangle of the screen (its
//     "footprint"). Bundle frames are stored fully opaque with the
//     background already baked in by the editor, so playing one is just
//     copying the current frame into that rectangle — no transparency.
//   - Collision and layer are NOT stored per animation. The editor
//     merges every frame's collision/layer into the map's normal
//     s_map_hitbox / s_map_fgmask bitmasks, so map_pixel_blocked() and
//     map_pixel_layer() treat an animated object exactly like a static
//     one. The one extra job is at draw time: foreground pixels have to
//     be re-stamped from the animation's CURRENT frame, because
//     s_map_pixels still holds frame 1 — see anim_restamp_foreground(),
//     called by redraw_foreground_over_rect().
//   - Bundles are shared: identical animations (e.g. 20 stamped water
//     tiles, or the same hit-flash used by several breakables) point at
//     one frame_bundle_t in s_bundles. Their frames stream from the card
//     (SD STREAMING): PSRAM holds two frames per DISTINCT playing bundle,
//     however many places it's used or how many frames it has.
//   - Frame index/finished are computed from elapsed time via
//     frame_bundle.h's math helpers rather than stepped or unrolled —
//     see update_animations() in the ANIMATION PLAYBACK section.
// ============================================================
// ---- Map store ----------------------------------------------------------
//  Every breakable's collision and layer masks (1 bit per pixel — the only
//  part of the bundles/breakables sections kept in PSRAM; the art itself
//  streams from the card, see SD STREAMING) live in ONE PSRAM block per map
//  instead of two allocations per level. load_map() sizes it from the file
//  (masks can't be more than a quarter of those sections' bytes), then gives
//  the unused tail back.
typedef struct {
    uint8_t *base;
    size_t   size, used;
} map_store_t;

static map_store_t s_map_store = { 0 };   // the loaded map's

// `bytes` from the store, `align`-aligned, filled from the file. NULL = the
// store is full (a malformed file) or the read came up short.
static void *store_read(map_store_t *st, FILE *f, size_t bytes, size_t align)
{
    size_t at = (st->used + align - 1) & ~(align - 1);
    if (!st->base || at > st->size || bytes > st->size - at) return NULL;
    if (fread(st->base + at, 1, bytes, f) != bytes) return NULL;
    st->used = at + bytes;
    return st->base + at;
}

static void store_free(map_store_t *st)
{
    heap_caps_free(st->base);
    memset(st, 0, sizeof(*st));
}

#define BUNDLE_MAX_COUNT    256   // distinct frame bundles per map (shared with breakables)
#define ANIM_MAX_INSTANCES  1024  // ambient animation placements per map

// Playback of one bundle by the map's ambient animations. Every placement
// of a bundle starts together (anim_reset_timers()) and so shows the same
// frame, so the state — and the frames kept in PSRAM — are per bundle.
typedef struct {
    bool      used;              // an ambient animation plays it (only those get frames in PSRAM)
    bool      resident;          // 1-2 frames: all of them are kept, nothing to stream
    uint16_t *slots;             // PSRAM: every frame (resident), or two: the one on screen and the next
    uint16_t *shown;             // the frame on screen (a slot)
    int16_t   shown_frame;       // its index; -1 = not read yet
    uint16_t *next;              // streamed: the other slot — the streamer reads next_frame into it
    int16_t   next_frame;
    bool      pending;           // streamer is reading into `next` (atomic: game loop <-> streamer)
    bool      next_ready;        // `next` holds next_frame (atomic)
    bool      started, finished, changed;
    uint32_t  start_ms, next_ms; // playback clock
} bundle_play_t;

typedef struct {
    frame_bundle_t *items;    // .pixels is NULL: the frames stay in the .map (SD STREAMING)
    uint32_t       *px_off;   // where each bundle's pixels start in the .map file
    bundle_play_t  *play;     // PSRAM, one per bundle
    uint16_t       *play_buf; // PSRAM: every playing bundle's slots
    int             count;
} bundle_bank_t;

static bundle_bank_t s_bundles = { 0 }; // this map's shared Frame Bundle table

typedef struct {
    int16_t               x, y;        // top-left of the footprint on screen
    int16_t               w, h;        // footprint size (== the bundle's w/h)
    const frame_bundle_t *bundle;
    uint16_t              bi;          // its index in s_bundles — the frame on screen is s_bundles.play[bi]'s
} anim_instance_t;

typedef struct {
    anim_instance_t *inst;
    int              inst_count;
} anim_bank_t;

static anim_bank_t s_anim = { 0 }; // animation instances of the currently loaded map

// ============================================================
//  SD STREAMING — the map's Frame Bundle frames and its breakables' art
//  (idle, gone and hit frames) are not kept in PSRAM. The .map file stays
//  open while the map is loaded and they're read from it when needed:
//   - An ambient animation keeps two frames per bundle in PSRAM: the one on
//     screen and the next one, which a background task (the streamer)
//     reads while the current one plays. All placements of a bundle run in
//     step, so one pair serves all of them; a bundle of 1-2 frames keeps
//     them all. If the next frame isn't off the card in time, the current
//     one stays up a few ms longer — the game loop never waits for the card.
//   - A breakable reads its art into a small scratch buffer when it's drawn
//     (a hit frame, a level change, a new night stage) — one short read.
//  Everything read comes in darkened to the current night stage (the same
//  formula the editor's .n1-.n6 files use), so it matches the map.
//  Only the map's own pixels and collision/layer bits stay in PSRAM: every
//  step the player takes repaints from them.
// ============================================================
#define STREAM_RETRY_MS 8   // a frame not off the card yet: look again this much later

static FILE             *s_mapf        = NULL;   // the loaded .map (load_map() hands its FILE over)
static SemaphoreHandle_t s_mapf_mx     = NULL;   // one reader at a time: the game loop or the streamer
static bool              s_mapf_warned = false;
static QueueHandle_t     s_stream_q    = NULL;   // bundle indices whose next frame to read
static int               s_stream_outstanding = 0;   // requests queued or being read (atomic)

// Reads `px` pixels at byte offset `off` of the loaded .map into dst,
// darkened to the current night stage. false = card error.
static bool mapf_read_px(uint32_t off, uint16_t *dst, size_t px)
{
    if (!px) return true;
    if (!s_mapf) return false;
    xSemaphoreTake(s_mapf_mx, portMAX_DELAY);
    bool ok = fseek(s_mapf, (long)off, SEEK_SET) == 0 && fread(dst, sizeof(uint16_t), px, s_mapf) == px;
    xSemaphoreGive(s_mapf_mx);
    if (!ok) {
        if (!s_mapf_warned) ESP_LOGE(TAG, "stream: can't read the map from the SD card — animations and breakables keep their current look");
        s_mapf_warned = true;
        return false;
    }
    if (s_night_shown > 0) for (size_t i = 0; i < px; i++) dst[i] = night_px(&s_night_lut, dst[i]);
    return true;
}

static void stream_task(void *arg)
{
    for (;;) {
        uint16_t i;
        xQueueReceive(s_stream_q, &i, portMAX_DELAY);
        bundle_play_t        *p  = &s_bundles.play[i];
        const frame_bundle_t *bd = &s_bundles.items[i];
        size_t px = (size_t)bd->w * bd->h;
        bool ok = mapf_read_px(s_bundles.px_off[i] + (uint32_t)(p->next_frame * px * sizeof(uint16_t)), p->next, px);
        __atomic_store_n(&p->next_ready, ok, __ATOMIC_RELEASE);
        __atomic_store_n(&p->pending, false, __ATOMIC_RELEASE);
        __atomic_sub_fetch(&s_stream_outstanding, 1, __ATOMIC_ACQ_REL);
    }
}

// Asks the streamer for frame f of bundle i (into its `next` slot), unless it's busy with that bundle.
static void stream_request(int i, uint16_t f)
{
    bundle_play_t *p = &s_bundles.play[i];
    if (__atomic_load_n(&p->pending, __ATOMIC_ACQUIRE)) return;
    p->next_frame = (int16_t)f;
    p->next_ready = false;
    __atomic_store_n(&p->pending, true, __ATOMIC_RELEASE);
    __atomic_add_fetch(&s_stream_outstanding, 1, __ATOMIC_ACQ_REL);
    uint16_t idx = (uint16_t)i;
    if (xQueueSend(s_stream_q, &idx, 0) != pdTRUE) {   // can't happen (one request per bundle at most) — undo
        __atomic_store_n(&p->pending, false, __ATOMIC_RELEASE);
        __atomic_sub_fetch(&s_stream_outstanding, 1, __ATOMIC_ACQ_REL);
    }
}

// Waits until the streamer has nothing left to do. Only the game loop asks
// it for work, so it stays idle until the next stream_request().
static void stream_drain(void)
{
    while (__atomic_load_n(&s_stream_outstanding, __ATOMIC_ACQUIRE) > 0) vTaskDelay(1);
}

static void stream_init(void)
{
    if (s_stream_q) return;
    s_mapf_mx  = xSemaphoreCreateMutex();
    s_stream_q = xQueueCreate(BUNDLE_MAX_COUNT, sizeof(uint16_t));
    xTaskCreate(stream_task, "stream", 2048, NULL, 4, NULL);   // peak 0.7 KB seen (dev link "stacks")
}

// Puts frame f of bundle i on show (for anim_frame()). false = still on its
// way off the card: the current frame stays, ask again shortly.
static bool play_show(int i, uint16_t f)
{
    bundle_play_t *p = &s_bundles.play[i];
    if (p->shown_frame == (int16_t)f) return true;
    const frame_bundle_t *bd = &s_bundles.items[i];
    if (p->resident) {
        p->shown       = p->slots + (size_t)f * bd->w * bd->h;
        p->shown_frame = (int16_t)f;
        return true;
    }
    if (__atomic_load_n(&p->pending, __ATOMIC_ACQUIRE)) return false;
    if (p->next_ready && p->next_frame == (int16_t)f) {
        uint16_t *t = p->shown;
        p->shown       = p->next;
        p->next        = t;
        p->shown_frame = (int16_t)f;
        p->next_ready  = false;
        return true;
    }
    stream_request(i, f);
    return false;
}

// Starts reading the frame bundle i will show at its next frame change.
static void play_prefetch(int i)
{
    bundle_play_t *p = &s_bundles.play[i];
    if (p->resident || !p->started || p->finished) return;
    bool fin = false;
    uint16_t f = bundle_frame_by_loop_count(&s_bundles.items[i], p->next_ms - p->start_ms, &fin);
    if ((int16_t)f != p->shown_frame && !(p->next_ready && p->next_frame == (int16_t)f)) stream_request(i, f);
}

// The frame instance `a` shows now, or NULL (not read yet — the map buffer's
// baked-in first frame stays).
static inline const uint16_t *anim_frame(const anim_instance_t *a)
{
    const bundle_play_t *p = &s_bundles.play[a->bi];
    return p->shown_frame >= 0 ? p->shown : NULL;
}

// Gives every bundle an ambient animation plays its frame slots, in one
// PSRAM block. false = out of memory.
static bool anim_play_setup(bundle_bank_t *bk, const anim_bank_t *ab)
{
    if (bk->count == 0) return true;
    bk->play = heap_caps_calloc((size_t)bk->count, sizeof(bundle_play_t), MALLOC_CAP_SPIRAM);
    if (!bk->play) return false;
    for (int n = 0; n < ab->inst_count; n++) bk->play[ab->inst[n].bi].used = true;
    size_t total = 0;
    for (int i = 0; i < bk->count; i++) {
        bundle_play_t *p = &bk->play[i];
        p->shown_frame = -1;
        if (!p->used) continue;
        const frame_bundle_t *bd = &bk->items[i];
        p->resident = bd->frame_count <= 2;
        total += (size_t)bd->w * bd->h * (p->resident ? bd->frame_count : 2);
    }
    if (total == 0) return true;
    bk->play_buf = heap_caps_malloc(total * sizeof(uint16_t), MALLOC_CAP_SPIRAM);
    if (!bk->play_buf) return false;
    uint16_t *at = bk->play_buf;
    for (int i = 0; i < bk->count; i++) {
        bundle_play_t *p = &bk->play[i];
        if (!p->used) continue;
        const frame_bundle_t *bd = &bk->items[i];
        size_t px = (size_t)bd->w * bd->h;
        p->slots = p->shown = at;
        p->next  = at + px;          // unused by a resident bundle
        at += px * (p->resident ? bd->frame_count : 2);
    }
    return true;
}

// (Re)reads the frame every playing bundle shows off the card, in the
// current night tint (a new map, or a new night stage), and starts reading
// the next one.
static void anim_frames_reload(void)
{
    stream_drain();
    for (int i = 0; i < s_bundles.count; i++) {
        bundle_play_t *p = &s_bundles.play[i];
        if (!p->used) continue;
        const frame_bundle_t *bd = &s_bundles.items[i];
        size_t px = (size_t)bd->w * bd->h;
        int    f  = p->shown_frame < 0 ? 0 : p->shown_frame;
        p->next_ready = false;
        if (p->resident) {
            bool ok = mapf_read_px(s_bundles.px_off[i], p->slots, px * bd->frame_count);
            p->shown       = p->slots + (size_t)f * px;
            p->shown_frame = ok ? (int16_t)f : -1;
        } else {
            p->shown_frame = mapf_read_px(s_bundles.px_off[i] + (uint32_t)(f * px * sizeof(uint16_t)), p->shown, px) ? (int16_t)f : -1;
        }
        play_prefetch(i);
    }
}

// FNV-1a of the map's day pixels in night "block order" (see DAY / NIGHT),
// built while load_map() reads the file — the stage files carry the same.
static uint32_t s_load_hash;
static long     s_loading_file_len = 0;   // size of the map file load_map() is reading (LOADING SCREEN)
static void     loading_finish(void);     // LOADING SCREEN section
static uint32_t s_map_hash;   // s_load_hash of the map that's loaded (a failed load changes s_load_hash only) — MAP SAVES

static void loading_file_tick(FILE *f);   // LOADING SCREEN section: moves its bar along

// Reads past `px` pixels of the file (art that streams later), hashing them.
// Read in big pieces: every fread is at least one SD transaction, and a map's
// art is most of its file (16 KB at a time, in DMA-able RAM so the card driver
// reads straight into it; the small static one if there's no RAM for that).
#define SKIP_BIG_PX (8 * 1024)
static bool file_skip_px(FILE *f, size_t px)
{
    static uint16_t small[512];
    static uint8_t  tick;
    uint16_t *big = px > 512 ? heap_caps_malloc(SKIP_BIG_PX * sizeof(uint16_t), MALLOC_CAP_DMA | MALLOC_CAP_INTERNAL) : NULL;
    uint16_t *buf = big ? big : small;
    size_t    cap = big ? SKIP_BIG_PX : 512;
    bool      ok  = true;
    while (px) {
        size_t n = px < cap ? px : cap;
        if (fread(buf, sizeof(uint16_t), n, f) != n) { ok = false; break; }
        s_load_hash = night_fnv(s_load_hash, buf, (uint32_t)n);
        px -= n;
        tick += (uint8_t)(n / 512 ? n / 512 : 1);
        if (tick >= 32) { tick = 0; loading_file_tick(f); }
    }
    heap_caps_free(big);
    return ok;
}

static bool anim_read_u16(FILE *f, uint16_t *out)
{
    uint8_t b[2];
    if (fread(b, 1, 2, f) != 2) return false;
    *out = (uint16_t)(b[0] | (b[1] << 8));
    return true;
}

// Frees a bundle table and leaves it empty (safe on a zeroed table). Call
// only with the streamer idle (stream_drain()).
static void bundle_bank_free(bundle_bank_t *bk)
{
    free(bk->items);
    free(bk->px_off);
    heap_caps_free(bk->play);
    heap_caps_free(bk->play_buf);
    memset(bk, 0, sizeof(*bk));
}

// Reads the shared bundle table at the front of a MAP6+ file's Frame Bundle
// section. All-or-nothing: a bad entry frees everything read so far.
static bool bundle_bank_read(FILE *f, bundle_bank_t *out)
{
    memset(out, 0, sizeof(*out));
    uint16_t count = 0;
    if (!anim_read_u16(f, &count)) { ESP_LOGE(TAG, "bundle: file ends before the bundle header"); return false; }
    if (count > BUNDLE_MAX_COUNT) {
        ESP_LOGE(TAG, "bundle: %u bundles exceeds the limit (%d)", (unsigned)count, BUNDLE_MAX_COUNT);
        return false;
    }
    if (count == 0) return true;

    out->items  = calloc(count, sizeof(frame_bundle_t));
    out->px_off = calloc(count, sizeof(uint32_t));
    out->count  = count;   // set now so bundle_bank_free() cleans up a partial read
    if (!out->items || !out->px_off) { ESP_LOGE(TAG, "bundle: out of memory"); bundle_bank_free(out); return false; }

    for (int i = 0; i < count; i++) {
        frame_bundle_t *bd = &out->items[i];
        uint16_t w, h, frames, interval, loop_raw;
        if (!anim_read_u16(f, &w) || !anim_read_u16(f, &h) || !anim_read_u16(f, &frames) ||
            !anim_read_u16(f, &interval) || !anim_read_u16(f, &loop_raw)) {
            ESP_LOGE(TAG, "bundle: bundle %d header truncated", i);
            bundle_bank_free(out);
            return false;
        }
        if (w == 0 || h == 0 || frames == 0 || frames > BUNDLE_MAX_FRAMES) {
            ESP_LOGE(TAG, "bundle: bundle %d has an invalid size (%ux%u, %u frames)", i, w, h, frames);
            bundle_bank_free(out);
            return false;
        }
        bd->w = w; bd->h = h; bd->frame_count = frames;
        bd->interval_ms = interval ? interval : 100;   // 0 would spin every tick — fall back to something sane
        bd->loop_count  = (int16_t)loop_raw;            // two's complement: 0xFFFF -> -1 ("forever")

        out->px_off[i] = (uint32_t)ftell(f);
        if (!file_skip_px(f, (size_t)frames * w * h)) {   // the frames stream later (SD STREAMING)
            ESP_LOGE(TAG, "bundle: bundle %d pixel data truncated", i);
            bundle_bank_free(out);
            return false;
        }
    }
    return true;
}

// Frees everything a bank owns and leaves it empty (safe on a zeroed bank).
static void anim_bank_free(anim_bank_t *b)
{
    if (b->inst) free(b->inst);
    memset(b, 0, sizeof(*b));
}

// Ascending by footprint bottom edge (y + h) — see the sort call in
// anim_bank_read() below for why.
static int anim_instance_depth_cmp(const void *pa, const void *pb)
{
    const anim_instance_t *a = (const anim_instance_t *)pa;
    const anim_instance_t *b = (const anim_instance_t *)pb;
    int ay = a->y + a->h, by = b->y + b->h;
    return (ay > by) - (ay < by);
}

// Reads the ambient animation instances of a MAP6+ file (the table right
// after the shared bundle table `bundles` — layout above). On any
// failure it frees whatever it allocated and returns false, leaving
// *out empty — same "all or nothing" rule the rest of load_map() follows.
static bool anim_bank_read(FILE *f, int map_w, int map_h, const bundle_bank_t *bundles, anim_bank_t *out)
{
    memset(out, 0, sizeof(*out));

    uint16_t inst_count = 0;
    if (!anim_read_u16(f, &inst_count)) {
        ESP_LOGE(TAG, "anim: file ends before the animation instance header");
        return false;
    }
    if (inst_count > ANIM_MAX_INSTANCES) {
        ESP_LOGE(TAG, "anim: %u objects exceeds the limit (%d)", (unsigned)inst_count, ANIM_MAX_INSTANCES);
        return false;
    }
    if (inst_count == 0) return true;

    out->inst = calloc(inst_count, sizeof(anim_instance_t));
    if (!out->inst) { ESP_LOGE(TAG, "anim: out of memory for the animation table"); return false; }
    out->inst_count = inst_count;   // set before the reads so a failure below frees what's there

    for (int i = 0; i < inst_count; i++) {
        uint16_t x, y, bundle_index;
        if (!anim_read_u16(f, &x) || !anim_read_u16(f, &y) || !anim_read_u16(f, &bundle_index)) {
            ESP_LOGE(TAG, "anim: object %d truncated", i);
            anim_bank_free(out);
            return false;
        }
        if (bundle_index >= (uint16_t)bundles->count || x >= map_w || y >= map_h) {
            ESP_LOGE(TAG, "anim: object %d is invalid (bundle %u at %u,%u)",
                     i, (unsigned)bundle_index, (unsigned)x, (unsigned)y);
            anim_bank_free(out);
            return false;
        }
        anim_instance_t *a = &out->inst[i];
        a->bundle = &bundles->items[bundle_index];
        a->bi     = bundle_index;
        a->x      = (int16_t)x;
        a->y      = (int16_t)y;
        a->w      = (int16_t)a->bundle->w;
        a->h      = (int16_t)a->bundle->h;
    }

    // Depth-sort by bottom edge (ascending): both anim_restamp_foreground()
    // and update_animations()/anim_draw_all_current() below just walk this
    // array in order, and whichever instance they touch LAST at a shared
    // pixel wins visually. Left in file/export order, that "last" was
    // essentially random (whatever order the editor happened to write
    // instances in) — so two overlapping foreground-flagged animations
    // (e.g. a torch's flame overlapping a fence post) would inconsistently
    // show whichever one's frame data happened to be processed later,
    // instead of the one that should actually be in front. Sorting once
    // here means "further down the screen" (bigger y+h) always draws
    // later = on top, the same painter's-algorithm convention this
    // top-down map already uses for depth everywhere else.
    if (out->inst_count > 1) {
        qsort(out->inst, (size_t)out->inst_count, sizeof(anim_instance_t), anim_instance_depth_cmp);
    }
    return true;
}

// Replaces the live animations with *nb, taking ownership of its memory
// (nb is left empty). Frees the previous map's animations.
static void anim_bank_install(anim_bank_t *nb)
{
    anim_bank_free(&s_anim);
    s_anim = *nb;
    memset(nb, 0, sizeof(*nb));
}

// (Re)starts every animation's clock from "now", all on frame 1, so all
// objects that share a speed stay in step with each other. load_map()
// calls this AFTER the fade-in so the first frame is not eaten by it.
static void anim_reset_timers(void)
{
    uint32_t now = (uint32_t)(esp_timer_get_time() / 1000);
    for (int i = 0; i < s_bundles.count; i++) {
        bundle_play_t *p = &s_bundles.play[i];
        if (!p->used) continue;
        p->start_ms = now;
        p->next_ms  = bundle_next_boundary_ms(&s_bundles.items[i], now, 0);
        p->finished = false;
        p->started  = true;
        play_show(i, 0);
        play_prefetch(i);
    }
}

static void brk_restamp_over_anim(int x0, int y0, int x1, int y1, bool fg_only);   // BREAKABLE RUNTIME: breakables placed above animations

// Re-stamps the CURRENT animation frame onto every foreground-layer pixel
// inside the given rect. redraw_foreground_over_rect() calls this right
// after it re-stamps the map's own foreground pixels — the map buffer
// still holds each animation's first frame, so without this a foreground
// animation (a swaying tree top, say) would snap back to frame 1
// whenever the player walked behind it. Layer data is per-pixel and
// shared by all frames, exactly as painted in the editor.
static void anim_restamp_foreground(int x, int y, int w, int h)
{
    for (int n = 0; n < s_anim.inst_count; n++) {
        const anim_instance_t *a = &s_anim.inst[n];
        int x0 = a->x > x ? a->x : x;
        int y0 = a->y > y ? a->y : y;
        int x1 = (a->x + a->w < x + w) ? a->x + a->w : x + w;
        int y1 = (a->y + a->h < y + h) ? a->y + a->h : y + h;
        if (x0 < 0) x0 = 0;
        if (y0 < 0) y0 = 0;
        if (x1 > s_map_w) x1 = s_map_w;
        if (y1 > s_map_h) y1 = s_map_h;
        if (x0 >= x1 || y0 >= y1) continue;

        const uint16_t *frame = anim_frame(a);
        if (!frame) continue;
        for (int py = y0; py < y1; py++) {
            for (int px = x0; px < x1; px++) {
                int i = py * s_map_w + px;
                if ((s_map_fgmask[i / 8] >> (7 - (i % 8))) & 1) {
                    draw_pixel(px, py, frame[(py - a->y) * a->w + (px - a->x)]);
                }
            }
        }
        brk_restamp_over_anim(x0, y0, x1, y1, true);   // a breakable on top of it stays on top
    }
}

// Same, but every pixel of each animation inside the rect, not just its
// foreground ones: map_repaint_rect() restores the rect from the map buffer
// (each animation's FIRST frame), so without this whatever it repaints over
// animated water (a bobbing bobber, a shopper) snaps that patch back to frame
// 1 until the animation next changes frame — a flicker. Returns true if it
// drew anything; the caller then puts static foreground scenery back on top.
static bool anim_restamp_current(int x, int y, int w, int h)
{
    bool any = false;
    for (int n = 0; n < s_anim.inst_count; n++) {
        const anim_instance_t *a = &s_anim.inst[n];
        int x0 = a->x > x ? a->x : x;
        int y0 = a->y > y ? a->y : y;
        int x1 = (a->x + a->w < x + w) ? a->x + a->w : x + w;
        int y1 = (a->y + a->h < y + h) ? a->y + a->h : y + h;
        if (x0 < 0) x0 = 0;
        if (y0 < 0) y0 = 0;
        if (x1 > s_fb_w) x1 = s_fb_w;
        if (y1 > s_fb_h) y1 = s_fb_h;
        if (x0 >= x1 || y0 >= y1) continue;

        const uint16_t *frame = anim_frame(a);
        if (!frame) continue;
        for (int py = y0; py < y1; py++) {
            memcpy(&s_fb[py * s_fb_w + x0], &frame[(py - a->y) * a->w + (x0 - a->x)], (size_t)(x1 - x0) * sizeof(uint16_t));
        }
        brk_restamp_over_anim(x0, y0, x1, y1, false);
        any = true;
    }
    return any;
}

// ============================================================
//  ITEMS + INVENTORY + BREAKABLE OBJECT DATA (MAP8 section)
//  Items themselves are defined in items.h/items.c: every item is authored
//  in the Game Tools Item Editor and dropped in as a .c file under
//  assets/items/ — nothing item-related is hand-coded here anymore.
// ============================================================
#include "items.h"
#include "actions.h"   // ASSET ACTIONS: what a tapped object runs (main/actions.c)
// There is no separate "tool" type: a tool is just an item. A breakable
// level names the item (by id) the player must be holding to hit it.

// s_inv[0 .. HOTBAR_SLOTS-1] is the hotbar (always on screen, and the held
// item is one of these); the rest is the backpack, only seen in the
// inventory screen. inv_add() fills the hotbar first.
#define HOTBAR_SLOTS 8
#define INV_ROWS     3                                   // backpack rows above the hotbar row in the inventory screen
#define INV_SLOTS    (HOTBAR_SLOTS * (INV_ROWS + 1))
typedef struct { uint8_t item; uint8_t count; uint8_t quality; } inv_slot_t;   // count == 0 means "empty"; quality: item_quality_t
static inv_slot_t s_inv[INV_SLOTS];
static int        s_inv_held = 0;                              // which HOTBAR slot is in the player's hands

// ---- in-game hotbar geometry: centred, along the bottom or top edge ----
#define HOTBAR_SLOT_PX  26
#define HOTBAR_GAP      2
#define HOTBAR_PAD      4
#define HOTBAR_W        (HOTBAR_PAD * 2 + HOTBAR_SLOTS * HOTBAR_SLOT_PX + (HOTBAR_SLOTS - 1) * HOTBAR_GAP)
#define HOTBAR_H        (HOTBAR_PAD * 2 + HOTBAR_SLOT_PX)
#define HOTBAR_X        ((LCD_H_RES - HOTBAR_W) / 2)
#define HOTBAR_Y_BOTTOM (LCD_V_RES - HOTBAR_H - 6)
#define HOTBAR_Y_TOP    6

// The hotbar lives on its "home" edge (bottom, or top when the Settings
// flip is on) and hops to the other edge while the player is under it —
// see hotbar_follow_player().
static bool s_hotbar_invert = false;            // persisted setting: true = home is the top edge
static int  s_hotbar_y      = HOTBAR_Y_BOTTOM;  // where it is on screen right now
static bool s_hotbar_img_valid = false;         // false = the HUD re-renders the whole bar (what's behind it changed)

// ---- light-brown "leather satchel" theme: hotbar, inventory, touch button ----
#define INV_COL_PANEL    COLOR_RGB565(214, 180, 132)
#define INV_COL_EDGE     COLOR_RGB565( 92,  58,  30)
#define INV_COL_SHINE    COLOR_RGB565(242, 218, 178)
#define INV_COL_SLOT     COLOR_RGB565(150, 108,  66)
#define INV_COL_SLOT_DK  COLOR_RGB565(100,  66,  36)
#define INV_COL_SLOT_LT  COLOR_RGB565(198, 160, 112)
#define INV_COL_TEXT     COLOR_RGB565( 72,  42,  18)
#define INV_COL_TEXT_DIM COLOR_RGB565(128,  92,  56)
#define INV_COL_GOLD     COLOR_RGB565(255, 204,  48)
#define INV_PANEL_ALPHA  205    // how opaque the brown panels are over the game world (0..255)

// Which hotbar slot (x,y) is on, or -1. The whole bar counts, gaps included,
// so a slightly-off tap still lands on the nearest slot.
static int hotbar_slot_at(int x, int y)
{
    if (x < HOTBAR_X || x >= HOTBAR_X + HOTBAR_W || y < s_hotbar_y || y >= s_hotbar_y + HOTBAR_H) return -1;
    int i = (x - HOTBAR_X - HOTBAR_PAD) / (HOTBAR_SLOT_PX + HOTBAR_GAP);
    if (i < 0) i = 0;
    if (i >= HOTBAR_SLOTS) i = HOTBAR_SLOTS - 1;
    return i;
}

// Adds `count` of `item` at `quality` (item_quality_t): tops up existing
// stacks of the same item AND quality first, then uses empty slots.
// Returns how many did NOT fit (0 = everything was stored).
static int inv_add_q(uint8_t item, uint8_t quality, int count)
{
    if (item == ITEM_NONE || !item_get(item) || count <= 0) return count > 0 ? count : 0;
    int max = item_max_stack(item);
    for (int i = 0; i < INV_SLOTS && count > 0; i++) {
        if (s_inv[i].count > 0 && s_inv[i].item == item && s_inv[i].quality == quality) {
            int room = max - s_inv[i].count;
            int put  = count < room ? count : room;
            s_inv[i].count += put;
            count -= put;
        }
    }
    for (int i = 0; i < INV_SLOTS && count > 0; i++) {
        if (s_inv[i].count == 0) {
            int put = count < max ? count : max;
            s_inv[i].item    = item;
            s_inv[i].count   = put;
            s_inv[i].quality = quality;
            count -= put;
        }
    }
    return count;
}

// inv_add_q() at Standard quality.
static int inv_add(uint8_t item, int count) { return inv_add_q(item, QUALITY_STANDARD, count); }

// Removes up to `count` of `item`. Returns how many were actually removed.
static int inv_remove(uint8_t item, int count)
{
    int removed = 0;
    for (int i = 0; i < INV_SLOTS && removed < count; i++) {
        if (s_inv[i].count > 0 && s_inv[i].item == item) {
            int take = (count - removed) < s_inv[i].count ? (count - removed) : s_inv[i].count;
            s_inv[i].count -= take;
            removed += take;
            if (s_inv[i].count == 0) s_inv[i].item = ITEM_NONE;
        }
    }
    return removed;
}

// The item currently in the player's hands (ITEM_NONE = bare hands).
static uint8_t inv_held_item(void)
{
    return (s_inv[s_inv_held].count > 0) ? s_inv[s_inv_held].item : ITEM_NONE;
}

static void inv_set_held(int slot)
{
    if (slot >= 0 && slot < HOTBAR_SLOTS) s_inv_held = slot;
}

// ---- Money -------------------------------------------------------------
// The player's coins. Earned by selling items (the SELL button in the
// inventory screen, see inv_sell_carried()); money_add() / money_spend()
// are there for anything else that pays or charges (chests, shops, ...).
// Starts at 0 on every boot, like the inventory.
#define MONEY_MAX 999999   // fits the inventory header
#define MONEY_START 1000   // what a new game starts with (world_new())

static uint32_t s_money = 0;

uint32_t money_get(void)
{
    return s_money;
}

// Adds `amount` (a negative amount takes money, never below 0).
void money_add(int32_t amount)
{
    int64_t m = (int64_t)s_money + amount;
    s_money = (uint32_t)(m < 0 ? 0 : (m > MONEY_MAX ? MONEY_MAX : m));
}

// Takes `amount` if the player has that much. false = not enough, nothing taken.
bool money_spend(uint32_t amount)
{
    if (amount > s_money) return false;
    s_money -= amount;
    return true;
}

// ---- Photo traits -------------------------------------------------------
//  What the camera's appraisal (PHOTO APPRAISAL, in the camera section) can
//  find in a photographed object. A photo item carries the traits it has as
//  attributes — { id, pct } — next to its price ("sellable"). pct is what a
//  trait does to the price: 100 = nothing, 250 = x2.5, 50 = halved.
//  Any item can carry them (an Item Editor attribute named after one of these
//  ids shows up too): the inventory card under the panel and the "now
//  holding" message list every attribute of an item that's in this table,
//  in the item's own order (photo items: biggest effect on the price first).
typedef struct {
    const char *id, *label;
    int16_t     pct;
} trait_t;

static const trait_t k_traits[] = {
    // how sharp the object is (one of these, or none for an ordinary photo)
    { "razor_sharp",   "Razor sharp",    2000 },
    { "very_sharp",    "Very sharp",      800 },
    { "sharp",         "Sharp",           300 },
    { "soft",          "Soft focus",       80 },
    { "blurry",        "Blurry",           50 },
    { "motion_blur",   "Motion blur",      40 },
    // light
    { "overexposed",   "Overexposed",      60 },
    { "underexposed",  "Underexposed",     70 },
    { "dark",          "Dark",            140 },
    { "bright",        "Bright",          120 },
    { "high_contrast", "High contrast",   180 },
    { "low_contrast",  "Low contrast",    150 },
    // colour
    { "vivid",         "Vivid",           200 },
    { "colorful",      "Colorful",        140 },
    { "monotone",      "Monotone",        160 },
    { "grayscale",     "Grayscale",       130 },
    // size and framing
    { "tiny",          "Tiny",            150 },
    { "small",         "Small",           115 },
    { "large",         "Large",           110 },
    { "huge",          "Huge",            125 },
    { "centered",      "Centered",        120 },
    { "cut_off",       "Cut off",          70 },
    { "detailed",      "Detailed",        140 },
    // just descriptions: no effect on the price
    { "tall",          "Tall",            100 },
    { "wide",          "Wide",            100 },
    { "red",           "Red",             100 },
    { "orange",        "Orange",          100 },
    { "yellow",        "Yellow",          100 },
    { "green",         "Green",           100 },
    { "teal",          "Teal",            100 },
    { "blue",          "Blue",            100 },
    { "purple",        "Purple",          100 },
    { "pink",          "Pink",            100 },
};
#define TRAIT_COUNT ((int)(sizeof(k_traits) / sizeof(k_traits[0])))

static const trait_t *trait_find(const char *id)
{
    for (int i = 0; i < TRAIT_COUNT; i++)
        if (strcmp(k_traits[i].id, id) == 0) return &k_traits[i];
    return NULL;
}

// ---- Legendary traits ---------------------------------------------------
//  Rare, niche traits a new photo item can turn up with (LEGENDARY_PER_MILLE
//  of them get one, whatever the camera saw): each multiplies what the item
//  sells for by a lot — times that trait's DEMAND, which is 1 for every one
//  for now (legendary_demand(): the demand system plugs in there later).
//  The multiplier is applied when the item is priced (item_sell_price() asks
//  item_price_bonus_pct()), not baked into its "sellable", so when demand
//  moves, so do the prices of the ones already made.
//  An item carries one as an attribute { id, mult x 100 } — any item can
//  (an Item Editor attribute named after one works too).
//  "giant" also shows the item blown up to HELD_GIANT_MAX (48x48) when it's
//  held over the player's head.
typedef struct {
    const char *id, *label;
    int16_t     mult;   // x this (times its demand)
} legendary_t;

static const legendary_t k_legendary[] = {
    { "radioactive", "Radioactive",  60 },
    { "giant",       "Giant",        25 },
    { "ancient",     "Ancient",      40 },
    { "cursed",      "Cursed",       35 },
    { "golden",      "Golden",       80 },
    { "alien",       "Alien",       120 },
};
#define LEGENDARY_COUNT     ((int)(sizeof(k_legendary) / sizeof(k_legendary[0])))
#define LEGENDARY_PER_MILLE 30            // new photo items that get one (3%)
#define ITEM_ATTR_GIANT     "giant"

static const legendary_t *legendary_find(const char *id)
{
    for (int i = 0; i < LEGENDARY_COUNT; i++)
        if (strcmp(k_legendary[i].id, id) == 0) return &k_legendary[i];
    return NULL;
}

// How much the market wants trait l right now: 1.0 = its plain multiplier.
// Always 1 for now — a demand system goes here later.
static float legendary_demand(const legendary_t *l)
{
    (void)l;
    return 1.0f;
}

// item_sell_price()'s multiplier (items.h): every legendary trait the item has, times its demand.
int64_t item_price_bonus_pct(uint8_t item)
{
    const item_asset_t *a = item_get(item);
    double m = 1.0;
    for (uint8_t i = 0; a && i < a->attr_count; i++) {
        const legendary_t *l = legendary_find(a->attrs[i].name);
        if (l) m *= l->mult * legendary_demand(l);
    }
    m *= 100.0;
    return m > 1e12 ? (int64_t)1e12 : (int64_t)m;
}

// A new photo item's roll: maybe one legendary trait, put in at attrs[at]
// (the ones from there on move up one). *n grows by one if it got one.
static const legendary_t *legendary_roll(item_attr_t *attrs, int *n, int at, int max)
{
    if (*n >= max || (int)(esp_random() % 1000) >= LEGENDARY_PER_MILLE) return NULL;
    const legendary_t *l = &k_legendary[esp_random() % LEGENDARY_COUNT];
    memmove(&attrs[at + 1], &attrs[at], (size_t)(*n - at) * sizeof(attrs[0]));
    attrs[at] = (item_attr_t){ l->id, (int32_t)l->mult * 100 };
    (*n)++;
    return l;
}

// Trait combos: an item with several GOOD traits (pct >= TRAIT_GOOD_PCT) is
// worth more than their multipliers alone — each good trait past the first
// adds TRAIT_COMBO once more than the one before it, so the bonus grows faster
// with every one: 2 good traits x1.15, 3 x1.52, 4 x2.31, 5 x4.05 (on top of
// the traits' own multipliers). Used by both appraisals (online and photo).
#define TRAIT_GOOD_PCT 110
#define TRAIT_COMBO    1.15
static double trait_combo_mult(int good)
{
    return good > 1 ? pow(TRAIT_COMBO, good * (good - 1) / 2.0) : 1.0;
}

// The AI's traits (the camera's online appraisal) aren't in k_traits: a photo
// item carries each as an attribute named TRAIT_FREE + its text, valued its pct
// — e.g. { "~Crisp Shot", 130 }.
#define TRAIT_FREE '~'

// ---- BAIT: what's on each rod (FISHING; items.h ITEM_ATTR_BAIT*) ----------
//  Kept per rod KIND (compiled-in rod items), not per bag slot, so it goes
//  wherever the rod goes; two of the same rod share it. At most one full
//  stack of one bait. Saved with the bag in world.txt:
//      bait <rod id> <bait id> <count>
typedef struct { uint8_t item; uint8_t count; } rod_bait_t;
static rod_bait_t s_rod_bait[256];

static uint8_t rod_bait_item(uint8_t rod)  { return s_rod_bait[rod].count ? s_rod_bait[rod].item : ITEM_NONE; }
static int     rod_bait_count(uint8_t rod) { return s_rod_bait[rod].count; }

// A catch with `bait` on `rod`: one used up. Returns how many are left.
static int rod_bait_use(uint8_t rod, uint8_t bait)
{
    rod_bait_t *b = &s_rod_bait[rod];
    if (b->count == 0 || b->item != bait) return 0;
    if (--b->count == 0) b->item = ITEM_NONE;
    return b->count;
}

// The item's traits, in its attribute order (up to max). Returns how many it has in all.
static int item_traits(uint8_t item, trait_t *out, int max)
{
    const item_asset_t *a = item_get(item);
    int n = 0;
    for (uint8_t i = 0; a && i < a->attr_count; i++) {
        const char *name = a->attrs[i].name;
        trait_t t;
        const legendary_t *lg;
        if (name[0] == TRAIT_FREE) {
            t = (trait_t){ name, name + 1, (int16_t)a->attrs[i].value };
        } else if ((lg = legendary_find(name)) != NULL) {
            t = (trait_t){ lg->id, lg->label, (int16_t)(lg->mult * 100 > INT16_MAX ? INT16_MAX : lg->mult * 100) };
        } else {
            const trait_t *k = trait_find(name);
            if (!k) continue;
            t = *k;
        }
        if (n < max) out[n] = t;
        n++;
    }
    // A fishing rod's stats (FISHING), each one that isn't normal: green better, red worse.
    if (a && item_attr(item, ITEM_ATTR_ROD, 0) > 0) {
        static char lbl[5][16];
        struct { const char *attr, *name, *unit; int def; } k_rod[5] = {
            { ITEM_ATTR_ROD_BAR, "Bar ", "px", 64 }, { ITEM_ATTR_ROD_REEL, "Reel ", "%", 100 }, { ITEM_ATTR_ROD_BITE, "Bite ", "%", 100 },
            { ITEM_ATTR_ROD_LUCK, "Luck ", "", 0 }, { ITEM_ATTR_ROD_GRIP, "Grip ", "%", 100 },
        };
        for (int s = 0; s < 5; s++) {
            int v = (int)item_attr(item, k_rod[s].attr, k_rod[s].def);
            if (v == k_rod[s].def) continue;
            int diff = k_rod[s].def ? (s == 0 ? v - k_rod[s].def : v - 100) : v;   // bar: px more; luck: points; the rest: % over normal
            snprintf(lbl[s], sizeof(lbl[s]), "%s%+d%s", k_rod[s].name, diff, k_rod[s].unit);
            if (n < max) out[n] = (trait_t){ k_rod[s].attr, lbl[s], (int16_t)(diff > 0 ? 101 : 99) };
            n++;
        }
        // lava, needing bait, and the bait on it now (BAIT)
        static char bait_lbl[32];
        if (item_attr(item, ITEM_ATTR_ROD_LAVA, 0) > 0)        { if (n < max) out[n] = (trait_t){ ITEM_ATTR_ROD_LAVA, "Lava rod", 101 }; n++; }
        if (item_attr(item, ITEM_ATTR_ROD_NEEDS_BAIT, 0) > 0)  { if (n < max) out[n] = (trait_t){ ITEM_ATTR_ROD_NEEDS_BAIT, "Needs bait", 100 }; n++; }
        if (item < item_count && rod_bait_count(item)) {
            snprintf(bait_lbl, sizeof(bait_lbl), "Bait: %s x%d", item_name(rod_bait_item(item)), rod_bait_count(item));
            if (n < max) out[n] = (trait_t){ ITEM_ATTR_BAIT, bait_lbl, 100 };
            n++;
        }
    }
    // A bait's stats: green better, red worse
    if (a && item_attr(item, ITEM_ATTR_BAIT, 0) > 0) {
        static char blbl[8][16];
        struct { const char *attr, *name, *unit; int def; } k_bait[8] = {
            { ITEM_ATTR_BAIT_BITE, "Bite ", "%", 100 }, { ITEM_ATTR_BAIT_BAR, "Bar ", "px", 0 }, { ITEM_ATTR_BAIT_CONTROL, "Control ", "", 0 },
            { ITEM_ATTR_BAIT_CALM, "Calm ", "%", 0 }, { ITEM_ATTR_BAIT_REEL, "Reel ", "%", 100 }, { ITEM_ATTR_BAIT_GRIP, "Grip ", "%", 100 },
            { ITEM_ATTR_BAIT_LUCK, "Luck ", "", 0 }, { ITEM_ATTR_BAIT_MUT, "Mutation ", "%", 100 },
        };
        for (int s = 0; s < 8; s++) {
            int v = (int)item_attr(item, k_bait[s].attr, k_bait[s].def), diff = v - k_bait[s].def;
            if (!diff) continue;
            snprintf(blbl[s], sizeof(blbl[s]), "%s%+d%s", k_bait[s].name, diff, k_bait[s].unit);
            if (n < max) out[n] = (trait_t){ k_bait[s].attr, blbl[s], (int16_t)(diff > 0 ? 101 : 99) };
            n++;
        }
        int tier = (int)item_attr(item, ITEM_ATTR_BAIT_TIER, 1);
        static char tlbl[24];
        if (tier >= 2 && tier <= 6) {
            static const char *const k_t[5] = { "Uncommon", "Rare", "Epic", "Legendary", "Mythic" };
            snprintf(tlbl, sizeof(tlbl), "%s+ only", k_t[tier - 2]);
            if (n < max) out[n] = (trait_t){ ITEM_ATTR_BAIT_TIER, tlbl, 101 };
            n++;
        }
    }
    // A lava fish / a fish that only bites on bait
    if (a && item_attr(item, ITEM_ATTR_FISH, 0) > 0) {
        if (item_attr(item, ITEM_ATTR_FISH_LAVA, 0) > 0) { if (n < max) out[n] = (trait_t){ ITEM_ATTR_FISH_LAVA, "Lives in lava", 100 }; n++; }
        if (item_attr(item, ITEM_ATTR_FISH_BAIT, 0) > 0) { if (n < max) out[n] = (trait_t){ ITEM_ATTR_FISH_BAIT, "Bites on bait", 100 }; n++; }
    }
    return n;
}

// "Sunflower - Razor sharp, Vivid, Tiny..." — the name and up to `shown`
// traits, "..." when it has more. Just the name when it has none.
static void item_summary(uint8_t item, int shown, char *out, size_t n)
{
    trait_t t[4];
    if (shown > 4) shown = 4;
    int total = item_traits(item, t, shown);
    int len = snprintf(out, n, "%s", item_name(item));
    for (int i = 0; i < total && i < shown && len > 0 && (size_t)len < n; i++)
        len += snprintf(out + len, n - len, "%s%s", i ? ", " : " - ", t[i].label);
    if (total > shown && len > 0 && (size_t)len < n) snprintf(out + len, n - len, "...");
}

// ---- Breakable objects ------------------------------------------------
//  MAP8 = everything above (pixels/collision/layer + the shared Frame
//  Bundle table + animation instances), then this section:
//
//    item_ref_count              uint8        item-id table: every item any level
//    item_ref_count x {                        below needs or drops, by STRING id
//        len                     uint8        1..BRK_ITEM_ID_MAX
//        chars                   len bytes    e.g. "wood" (no NUL) — resolved
//    }                                         with item_find() at load; an id
//                                              this build doesn't have is logged
//                                              and that drop is skipped / that
//                                              level can't be hit (the map still
//                                              loads)
//    brk_count                   uint16
//    brk_count x {               one per placed breakable (never shared —
//                                each one has its own background baked in)
//        x, y, w, h              4 x uint16   FIXED footprint on screen —
//                                              never changes per level; this
//                                              is what reach/overlap/off-map
//                                              checks use.
//        level_count             uint8        1..BRK_MAX_LEVELS (tree -> log = 2)
//        flags                   uint8        bit 0 = placed ABOVE the animations it overlaps: the
//                                              animations' frames don't hold it, the device draws its
//                                              current look over them (brk_restamp_over_anim()).
//                                              Other bits 0. (Was reserved, 0 in older files.)
//        level_count x {         level 0 = the object as placed (always
//                                ox=oy=0, w/h == the footprint's own w/h);
//                                level 1+ = what it leaves behind, and CAN
//                                have its own smaller ox,oy,w,h sub-rect
//                                inside the footprint — a real shrink, not
//                                just a transparency illusion.
//            hits                uint8        hits to break this level (1..BRK_MAX_HITS)
//            need_ref            uint8        0 = anything (bare hands too), else the
//                                              player must hold item-id-table entry need_ref-1
//            drop_count          uint8        0..BRK_MAX_DROPS entries in the drop list below
//            flags               uint8        bit 0 = this level has a "fall" (final_index); other bits 0
//            final_index         uint16       Frame Bundle the level's LAST hit plays as a fall
//                                              (see MAP13 below); 0 when flag bit 0 is clear.
//                                              (Was reserved: older firmware just ignores it.)
//            bundle_index        uint16       shared "hit" Frame Bundle — frame size MUST
//                                              equal THIS LEVEL's own w x h (not necessarily
//                                              the footprint's). Replayed once, start to end,
//                                              on every hit; held on its last frame as the
//                                              "damaged" look until the next hit, no matter
//                                              how many hits this level takes.
//            ox, oy, w, h        4 x uint16   this level's own sub-rect inside the
//                                              instance's x,y,w,h footprint
//                                              (0<=ox, ox+w<=footprint w, same for oy/h)
//            fall_x, fall_y      2 x int16    MAP13, only when flag bit 0 is set: the fall
//                                              bundle's top-left, relative to the footprint's
//                                              top-left — may be negative / reach past the
//                                              footprint (a tree falls outside its own box)
//            drop_count x {      paid out when this level's last hit lands (with a fall:
//                                when its last frame comes up — the tree settling)
//                item_ref        uint8        index into the item-id table above
//                min, max        2 x uint8    random count, inclusive (min <= max)
//                chance          uint8        0..100 % — rolled per entry
//            }
//            idle_pixels         w*h x uint16 RGB565, opaque — THIS LEVEL's own w*h
//            solid mask          ceil(w*h/8) bytes, MSB-first, 1 = blocked — this level's w*h
//            layer mask          ceil(w*h/8) bytes, MSB-first, 1 = foreground — this level's w*h
//        }
//        gone pixels             w*h x uint16 RGB565   footprint with nothing left
//                                              (always the INSTANCE's full w*h)
//        gone solid mask         ceil(w*h/8) bytes
//        gone layer mask         ceil(w*h/8) bytes
//    }
//  Masks REPLACE the map's collision/layer bits inside whatever rect is
//  drawn, so the editor bakes them as "the whole map's collision in that
//  rectangle with the object in that state" (underlying walls included).
//
//  MAP10 (magic "MAPA") = MAP9 (teleporter section always present, count
//  may be 0) with breakables that can overlap each other:
//   - every level has one more mask after its layer mask:
//            alpha mask          ceil(w*h/8) bytes, MSB-first, 1 = this level's art covers the
//                                              pixel (its own pixels plus any non-breakable scenery
//                                              stacked above it); 0 = see-through
//   - gone pixels/masks are the footprint with NO breakable in it at all
//     (not just this one), so they never bring back a neighbour's old look;
//   - breakables are in draw order, bottom first.
//  The device rebuilds a footprint from those (brk_compose()) instead of
//  copying one object's baked look over it — see BREAKABLE RUNTIME.
//
//  MAP13 (magic "MAPD") = MAP12 plus fall_x/fall_y above. A level with a
//  fall: its last hit swaps straight to the next level (or gone) and plays
//  the fall bundle ONCE as an overlay at fall_x/fall_y — any size, drawn in
//  front of everything (the player too), never blocking; 0x0000 =
//  see-through. Its drops pay out when the last frame comes up. A MAP12
//  file with flag bit 0 has no fall_x/fall_y: the fall sits on the level's
//  own ox/oy.
//
//  MAP14 (magic "MAPE") = MAP13, then — after the action triggers, at the
//  very end of the file — the breakables' SOUND EFFECTS:
//    name_count                  uint8        sound-name table
//    name_count x {
//        len                     uint8        1..SFX_NAME_MAX
//        chars                   len bytes    a file in GAME_DIR/sounds/sound effects/, without ".wav"
//    }
//    for every breakable above, in the same order, for each of its levels {
//        hit_count               uint8        0..SFX_SEQ_MAX
//        hit_count x uint8                    name-table indices: played in order on every hit
//        break_count             uint8        0..SFX_SEQ_MAX
//        break_count x uint8                  ...played instead on the hit that breaks the level
//    }                                         (none = the hit sounds play then too)
//  The editor expands a sound bundle into its list of names here. Older
//  maps have no sounds.
//
//  Older files still load. MAP7 is identical except need_ref is instead a
//  numeric tool kind (0 = anything, 1 = "axe", 2 = "pickaxe" — see
//  k_brk_legacy_tool_ids). MAP6 also has no item-id table, and each level
//  header is hits, tool_kind, drop_item, drop_min, drop_max, reserved —
//  drop_item being a number from the editor's old hardcoded list, mapped
//  through k_brk_legacy_drop_ids.
#define BRK_MAX_INSTANCES 64
#define BRK_MAX_LEVELS    4
#define BRK_MAX_HITS      16
#define BRK_MAX_DROPS     4    // drop-list entries per level (the editor enforces the same cap)
#define BRK_ITEM_ID_MAX   63   // longest item id in the item-id table
#define BRK_REACH         6    // px past the player's feet, in the facing direction, that a hit can reach

typedef struct {
    uint8_t item;              // resolved s_items index; ITEM_NONE = unknown id in this build, skipped
    uint8_t min, max;          // count, inclusive
    uint8_t chance;            // 0..100 %
} brk_drop_t;

typedef struct {
    uint8_t   hits, drop_count;
    uint8_t   need_item;               // item the player must hold; ITEM_NONE = anything
    bool      need_missing;            // needs an item this build doesn't have: can't be hit
    brk_drop_t drops[BRK_MAX_DROPS];
    bool      solid_any;               // false = walkable object (bush): whole sub-rect counts as hittable
    const frame_bundle_t *hit_bundle;   // shared hit-flash effect; played once per hit (see format notes above)
    const frame_bundle_t *fall_bundle;  // the last hit's fall overlay (any size); NULL = an ordinary last hit
    int16_t   fall_x, fall_y;           // its top-left relative to the footprint's (may be negative)
    int16_t   ox, oy;                   // this level's offset inside the instance's fixed footprint
    int16_t   w, h;                     // this level's OWN size (<= the footprint's w/h; level 0 == footprint)
    uint32_t  idle_off;                 // where its idle look (w*h pixels) is in the .map — streamed (brk_art_idle())
    uint32_t  hit_off;                  // where hit_bundle's frames are in the .map
    uint32_t  fall_off;                 // where fall_bundle's frames are in the .map
    uint8_t  *solid;                    // map store: 1 bit per pixel, this level's own w*h
    uint8_t  *layer;                    // map store: 1 bit per pixel, this level's own w*h
    uint8_t  *alpha;                    // map store, MAP10 only (else NULL): 1 = its art covers the pixel
    uint8_t   sfx_hit_n, sfx_break_n;   // MAP14 sounds (brk_play_sfx()): indices into the bank's sfx_names
    uint8_t   sfx_hit[SFX_SEQ_MAX], sfx_break[SFX_SEQ_MAX];
} brk_level_t;

typedef struct {
    int16_t      x, y, w, h;   // fixed footprint — set once at placement, never changes
    uint8_t      level_count;
    bool         above_anims;  // placed above the animations it overlaps: drawn over their frames (brk_restamp_over_anim())
    brk_level_t *levels;
    uint32_t     gone_off;     // where the "gone" look (the full footprint's w*h pixels) is in the .map — streamed
    uint8_t     *gone_solid, *gone_layer;   // map store
    // ---- live state (reset every time the map loads) ----
    uint8_t      level;        // current level; == level_count once fully gone
    uint8_t      hits_done;    // hits landed on the current level
    bool         playing;      // a hit's bundle is playing (extra presses are ignored)
    uint16_t     frame;        // hit-bundle frame on screen while playing (brk_compose() redraws it)
    uint32_t     start_ms;     // esp_timer ms the running hit's bundle started
    uint32_t     next_ms;      // early-out cache: next time the on-screen frame could change
    // a fall overlay playing (BREAKABLE RUNTIME, "falls") — the object is already on its next level
    bool         falling;
    bool         fall_paid;    // its drops are paid (its last frame has come up)
    uint8_t      fall_level;   // the level that fell: its fall bundle and drops
    int16_t      fall_frame;   // frame in fall_px; -1 = none read yet
    uint32_t     fall_start_ms, fall_next_ms;
    uint16_t    *fall_px;      // PSRAM, one frame of the fall bundle (NULL = no memory: the fall isn't drawn)
} brk_inst_t;

typedef struct {
    brk_inst_t *inst;
    int         count;
    uint16_t   *scratch;   // PSRAM, 2 x the biggest footprint: art read off the card to draw (brk_art_*())
    bool        composed;  // MAP10: footprints are rebuilt with brk_compose(), overlaps and all
    char      (*sfx_names)[SFX_NAME_MAX + 1];   // PSRAM, MAP14's sound-name table (NULL = none); "" = a bad name, never played
    int         sfx_name_count;
} brk_bank_t;

static brk_bank_t s_brk = { 0 };   // breakables of the currently loaded map

static void brk_on_action(void);   // defined in the BREAKABLE RUNTIME section; update_player() calls it
static void brk_fall_restamp(int x, int y, int w, int h);   // ...puts falling breakables back on top (redraw_foreground_over_rect())
static void farm_on_action(void);              // FARMING section: plant / harvest on the faced tile (update_player())
static bool trig_on_action(int tx, int ty);    // ASSET ACTIONS section: run the faced object's actions (update_player())
static bool farm_covers_tile(int tx, int ty);  // ...a crop grows in or over tile (tx,ty) (dropped stacks keep off it)
static void farm_clear(void);                  // ...a new map: the old one's crops go

// Masks are in the map store, freed with it; the art is on the card.
static void brk_inst_free(brk_inst_t *b)
{
    free(b->levels);
    heap_caps_free(b->fall_px);
    memset(b, 0, sizeof(*b));
}

static void brk_bank_free(brk_bank_t *bk)
{
    if (bk->inst) {
        for (int i = 0; i < bk->count; i++) brk_inst_free(&bk->inst[i]);
        free(bk->inst);
    }
    heap_caps_free(bk->scratch);
    heap_caps_free(bk->sfx_names);
    memset(bk, 0, sizeof(*bk));
}

// MAP6 files store a drop as a number from the editor's old hardcoded item
// list, and MAP6/MAP7 files a numeric tool kind; these are those lists
// (index = the old number), so they still resolve to item ids.
static const char *const k_brk_legacy_drop_ids[] = { NULL, "axe", "pickaxe", "wood", "stone" };
static const char *const k_brk_legacy_tool_ids[] = { NULL, "axe", "pickaxe" };

// Item id string -> this build's s_items index. An id with no matching
// assets/items/<id>.c is logged and comes back as ITEM_NONE, which
// brk_finish_level() skips — the map still loads.
static uint8_t brk_resolve_item_id(const char *id)
{
    uint8_t item = item_find(id);
    if (item == ITEM_NONE)
        ESP_LOGW(TAG, "brk: map uses item \"%s\" but assets/items/%s.c isn't in this build — "
                      "drops of it are skipped, levels needing it can't be hit", id, id);
    return item;
}

// Reads a MAP7 drop item-id table into refs[] as resolved s_items indices.
static bool brk_read_item_refs(FILE *f, uint8_t refs[256], int *ref_count)
{
    uint8_t n;
    if (fread(&n, 1, 1, f) != 1) return false;
    for (int i = 0; i < n; i++) {
        uint8_t len;
        char    id[BRK_ITEM_ID_MAX + 1];
        if (fread(&len, 1, 1, f) != 1 || len == 0 || len > BRK_ITEM_ID_MAX ||
            fread(id, 1, len, f) != len) return false;
        id[len] = '\0';
        refs[i] = brk_resolve_item_id(id);
    }
    *ref_count = n;
    return true;
}

// Reads the breakable section (after the animation instances of a MAP8, or
// legacy MAP6/MAP7, file — `version` is 6..13). All-or-nothing, same rule as
// anim_bank_read(). `bundles` is the map's already-parsed shared Frame
// Bundle table — every level's bundle_index is validated against it here.
static bool brk_bank_read(FILE *f, int map_w, int map_h, const bundle_bank_t *bundles,
                          int version, map_store_t *store, brk_bank_t *out)
{
    memset(out, 0, sizeof(*out));
    bool legacy_map6 = (version == 6);          // numeric drop, no item-id table
    bool legacy_tool = (version <= 7);          // numeric tool kind instead of need_ref

    static uint8_t item_refs[256];   // static: load_map() runs on the 3.5 KB main task stack
    int     item_ref_count = 0;
    if (!legacy_map6 && !brk_read_item_refs(f, item_refs, &item_ref_count)) {
        ESP_LOGE(TAG, "brk: item-id table is invalid or truncated");
        return false;
    }

    uint16_t count = 0;
    if (!anim_read_u16(f, &count)) {
        ESP_LOGE(TAG, "brk: file ends before the breakable header");
        return false;
    }
    if (count > BRK_MAX_INSTANCES) {
        ESP_LOGE(TAG, "brk: %u breakables exceeds the limit (%d)", (unsigned)count, BRK_MAX_INSTANCES);
        return false;
    }
    if (count == 0) return true;

    out->inst = calloc(count, sizeof(brk_inst_t));
    if (!out->inst) { ESP_LOGE(TAG, "brk: out of memory"); return false; }
    out->count    = count;                    // set now so brk_bank_free() cleans up a partial read
    out->composed = (version >= 10);

    int cur = 0;
    for (cur = 0; cur < count; cur++) {
        brk_inst_t *b = &out->inst[cur];
        uint16_t x, y, w, h;
        uint8_t  hdr[2];
        if (!anim_read_u16(f, &x) || !anim_read_u16(f, &y) ||
            !anim_read_u16(f, &w) || !anim_read_u16(f, &h) || fread(hdr, 1, 2, f) != 2) goto fail;

        uint8_t level_count = hdr[0];         // hdr[1]: flags, bit 0 = above the animations it overlaps
        b->above_anims = (hdr[1] & 1) != 0;
        if (w == 0 || h == 0 || x + w > map_w || y + h > map_h ||
            level_count == 0 || level_count > BRK_MAX_LEVELS) goto fail;

        size_t footprint_px = (size_t)w * h, footprint_mask_bytes = (footprint_px + 7) / 8;

        b->levels = calloc(level_count, sizeof(brk_level_t));
        if (!b->levels) goto fail;
        b->level_count = level_count;         // set now so brk_inst_free() frees the levels read so far
        b->x = (int16_t)x;  b->y = (int16_t)y;
        b->w = (int16_t)w;  b->h = (int16_t)h;

        for (int l = 0; l < level_count; l++) {
            brk_level_t *L = &b->levels[l];
            uint8_t lh[6];
            uint16_t bundle_index, lox, loy, lw, lh_;
            if (fread(lh, 1, 6, f) != 6 || !anim_read_u16(f, &bundle_index) ||
                !anim_read_u16(f, &lox) || !anim_read_u16(f, &loy) ||
                !anim_read_u16(f, &lw) || !anim_read_u16(f, &lh_)) goto fail;
            L->hits = lh[0];
            // lh[1]: what the player must hold. ITEM_NONE from a resolve means
            // the needed item isn't in this build (logged) — never breakable.
            if (legacy_tool) {
                if (lh[1] >= sizeof(k_brk_legacy_tool_ids) / sizeof(k_brk_legacy_tool_ids[0])) goto fail;
                const char *id = k_brk_legacy_tool_ids[lh[1]];
                L->need_item    = id ? brk_resolve_item_id(id) : ITEM_NONE;
                L->need_missing = id && L->need_item == ITEM_NONE;
            } else if (lh[1] != 0) {
                if (lh[1] > item_ref_count) goto fail;
                L->need_item    = item_refs[lh[1] - 1];
                L->need_missing = (L->need_item == ITEM_NONE);
            }
            if (legacy_map6) {
                // lh[2..4] = drop_item, drop_min, drop_max; lh[5] reserved
                if (lh[3] > lh[4]) goto fail;
                if (lh[2] != 0) {
                    const char *id = lh[2] < sizeof(k_brk_legacy_drop_ids) / sizeof(k_brk_legacy_drop_ids[0])
                                     ? k_brk_legacy_drop_ids[lh[2]] : NULL;
                    if (!id) ESP_LOGW(TAG, "brk: legacy drop item number %u is unknown — skipped", lh[2]);
                    L->drops[0] = (brk_drop_t){ .item = id ? brk_resolve_item_id(id) : ITEM_NONE,
                                                .min = lh[3], .max = lh[4], .chance = 100 };
                    L->drop_count = 1;
                }
            } else {
                L->drop_count = lh[2];
                if (L->drop_count > BRK_MAX_DROPS) goto fail;
                if (lh[3] & 1) {              // lh[4..5] = the last hit's fall bundle (any size)
                    uint16_t fi = (uint16_t)(lh[4] | (lh[5] << 8));
                    uint16_t fx = lox, fy = loy;   // MAP12: on the level's own spot
                    if (fi >= (uint16_t)bundles->count) goto fail;
                    if (version >= 13 && (!anim_read_u16(f, &fx) || !anim_read_u16(f, &fy))) goto fail;
                    L->fall_bundle = &bundles->items[fi];
                    L->fall_off    = bundles->px_off[fi];
                    L->fall_x      = (int16_t)fx;
                    L->fall_y      = (int16_t)fy;
                }
            }
            if (L->hits == 0 || L->hits > BRK_MAX_HITS || bundle_index >= (uint16_t)bundles->count) goto fail;
            if (lw == 0 || lh_ == 0 || lox + lw > w || loy + lh_ > h) goto fail;  // must fit inside the footprint

            for (int d = 0; !legacy_map6 && d < L->drop_count; d++) {
                uint8_t e[4];                 // item_ref, min, max, chance
                if (fread(e, 1, 4, f) != 4 || e[0] >= item_ref_count || e[1] > e[2] || e[3] > 100) goto fail;
                L->drops[d] = (brk_drop_t){ .item = item_refs[e[0]], .min = e[1], .max = e[2], .chance = e[3] };
            }

            const frame_bundle_t *bundle = &bundles->items[bundle_index];
            if (bundle->w != lw || bundle->h != lh_) goto fail;   // hit bundle must match THIS LEVEL's own size
            L->hit_bundle = bundle;
            L->hit_off    = bundles->px_off[bundle_index];
            L->ox = (int16_t)lox; L->oy = (int16_t)loy;
            L->w  = (int16_t)lw;  L->h  = (int16_t)lh_;

            size_t level_px = (size_t)lw * lh_, level_mask_bytes = (level_px + 7) / 8;
            L->idle_off    = (uint32_t)ftell(f);
            if (!file_skip_px(f, level_px)) goto fail;   // streams later (SD STREAMING)
            L->solid       = store_read(store, f, level_mask_bytes, 1);
            L->layer       = store_read(store, f, level_mask_bytes, 1);
            if (!L->solid || !L->layer) goto fail;
            if (out->composed && !(L->alpha = store_read(store, f, level_mask_bytes, 1))) goto fail;
            for (size_t k = 0; k < level_mask_bytes; k++) {
                if (L->solid[k]) { L->solid_any = true; break; }
            }
        }

        b->gone_off    = (uint32_t)ftell(f);
        if (!file_skip_px(f, footprint_px)) goto fail;
        b->gone_solid  = store_read(store, f, footprint_mask_bytes, 1);
        b->gone_layer  = store_read(store, f, footprint_mask_bytes, 1);
        if (!b->gone_solid || !b->gone_layer) goto fail;
    }
    return true;

fail:
    ESP_LOGE(TAG, "brk: breakable %d is invalid, truncated, or out of memory", cur);
    brk_bank_free(out);
    return false;
}

// Reads MAP14's sound section (see the format notes) into the already-read
// breakables of *bk. false = cut off / malformed (fails the load). A name
// that could reach outside the sound folder is blanked (logged), not fatal.
static bool brk_sfx_read(FILE *f, brk_bank_t *bk)
{
    uint8_t count;
    if (fread(&count, 1, 1, f) != 1) { ESP_LOGE(TAG, "sfx: file ends before the sound-name table"); return false; }
    if (count) {
        bk->sfx_names = heap_caps_calloc(count, SFX_NAME_MAX + 1, MALLOC_CAP_SPIRAM);
        if (!bk->sfx_names) { ESP_LOGE(TAG, "sfx: out of memory"); return false; }
        bk->sfx_name_count = count;
    }
    for (int i = 0; i < count; i++) {
        char   *name = bk->sfx_names[i];
        uint8_t len;
        if (fread(&len, 1, 1, f) != 1 || len == 0 || len > SFX_NAME_MAX || fread(name, 1, len, f) != len) {
            ESP_LOGE(TAG, "sfx: sound name %d is cut off or malformed", i);
            return false;
        }
        name[len] = '\0';
        bool ok = name[0] != '.';
        for (int k = 0; k < len && ok; k++) ok = name[k] >= 0x20 && name[k] < 0x7F && !strchr("/\\:", name[k]);
        if (!ok) { ESP_LOGW(TAG, "sfx: sound name \"%s\" isn't allowed — never played", name); name[0] = '\0'; }
    }
    for (int n = 0; n < bk->count; n++) {
        for (int l = 0; l < bk->inst[n].level_count; l++) {
            brk_level_t *L = &bk->inst[n].levels[l];
            uint8_t *lists[2] = { L->sfx_hit, L->sfx_break }, *counts[2] = { &L->sfx_hit_n, &L->sfx_break_n };
            for (int k = 0; k < 2; k++) {
                if (fread(counts[k], 1, 1, f) != 1 || *counts[k] > SFX_SEQ_MAX ||
                    fread(lists[k], 1, *counts[k], f) != *counts[k]) goto bad;
                for (int i = 0; i < *counts[k]; i++) if (lists[k][i] >= count) goto bad;
            }
        }
    }
    return true;
bad:
    ESP_LOGE(TAG, "sfx: a breakable's sound list is cut off or points past the name table");
    return false;
}

// The scratch buffer the breakables' streamed art is read into: 2 x the
// biggest footprint (a hit frame plus the gone art behind it). false = no PSRAM.
static bool brk_scratch_setup(brk_bank_t *bk)
{
    size_t most = 0;
    for (int i = 0; i < bk->count; i++) {
        size_t px = (size_t)bk->inst[i].w * bk->inst[i].h;
        if (px > most) most = px;
    }
    if (most == 0) return true;
    bk->scratch = heap_caps_malloc(2 * most * sizeof(uint16_t), MALLOC_CAP_SPIRAM);
    return bk->scratch != NULL;
}

// The map store moved (load_map() shrank it): move the mask pointers along.
static void brk_bank_rebase(brk_bank_t *bk, uintptr_t from, uint8_t *to)
{
#define BRK_REBASE(ptr) ((ptr) = to + ((uintptr_t)(ptr) - from))
    for (int i = 0; i < bk->count; i++) {
        brk_inst_t *b = &bk->inst[i];
        for (int l = 0; l < b->level_count; l++) {
            BRK_REBASE(b->levels[l].solid);
            BRK_REBASE(b->levels[l].layer);
            if (b->levels[l].alpha) BRK_REBASE(b->levels[l].alpha);
        }
        BRK_REBASE(b->gone_solid);
        BRK_REBASE(b->gone_layer);
    }
#undef BRK_REBASE
}

// Replaces the live breakables with *nb (taking ownership), freeing the old map's.
static void brk_bank_install(brk_bank_t *nb)
{
    brk_bank_free(&s_brk);
    s_brk = *nb;
    memset(nb, 0, sizeof(*nb));
}

// Tap-to-walk (TAP-TO-WALK section, after the breakable runtime).
// ---- Teleporters (MAP9 section) -----------------------------------------
//  MAP9 = MAP8, then:
//    tp_count                  uint8        0..TP_MAX
//    tp_count x {
//        tx, ty, tw, th        4 x uint8    trigger area in tiles (TILE_SIZE px): walking
//                                            onto any of these tiles fires it
//        dest_tx, dest_ty      2 x uint8    tile the player arrives standing on
//        face                  uint8        0 = keep facing, 1 = up, 2 = down, 3 = left, 4 = right
//        name_len              uint8        0..TP_NAME_MAX; 0 = somewhere on THIS map
//        name                  name_len bytes  map to load, by name:
//                                            "cave" or "cave.map" -> MAPS_DIR/cave/cave.map
//    }
//  Teleporters are invisible (nothing is drawn) and don't collide: the
//  tiles under one must be walkable for the player to reach it (the editor
//  warns). What happens on a step is in the TELEPORTERS runtime section.
//  The name TP_RETURN ("@return", the editor's "Building exit") is the way
//  out of a building's inside: back to the door of the building it belongs
//  to (PLACEMENT). A placed building's own door is a teleporter too, added
//  while the map loads (not in the file), with `inst` set.
#define TP_MAX      40               // the file's own (TP_FILE_MAX) + placed buildings' doors
#define TP_FILE_MAX 32
#define TP_NAME_MAX 31
#define TP_RETURN   "@return"

typedef struct {
    uint8_t  tx, ty, tw, th;         // trigger area, in tiles
    uint8_t  dest_tx, dest_ty;       // arrival tile
    uint8_t  face;                   // 0 = keep, 1 up, 2 down, 3 left, 4 right
    char     map[TP_NAME_MAX + 1];   // map to load; "" = this map
    uint16_t inst;                   // a placed building's door: which building (its inside's own save); 0 = an ordinary teleporter
} tp_t;

typedef struct {
    tp_t items[TP_MAX];
    int  count;
} tp_bank_t;

static tp_bank_t s_tp;       // teleporters of the loaded map
static tp_bank_t s_tp_new;   // load_map() parses into this, then copies it over s_tp (too big for the main task's stack)

// A map name may use letters, digits, _ - . and / (a subfolder) — or be TP_RETURN.
static bool tp_name_ok(const char *s)
{
    if (strcmp(s, TP_RETURN) == 0) return true;
    for (; *s; s++) {
        char c = *s;
        bool ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
                  c == '_' || c == '-' || c == '.' || c == '/';
        if (!ok) return false;
    }
    return true;
}

// Reads the MAP9 teleporter section. false = cut off / malformed, which
// fails the whole load like every other section; a teleporter that points
// off the map or has a bad name is only skipped (logged).
static bool tp_bank_read(FILE *f, tp_bank_t *out)
{
    out->count = 0;
    uint8_t count;
    if (fread(&count, 1, 1, f) != 1) { ESP_LOGE(TAG, "tp: file ends before the teleporter count"); return false; }
    if (count > TP_FILE_MAX) { ESP_LOGE(TAG, "tp: %u teleporters exceeds the limit (%d)", count, TP_FILE_MAX); return false; }
    for (int i = 0; i < count; i++) {
        uint8_t h[8];
        if (fread(h, 1, sizeof(h), f) != sizeof(h)) { ESP_LOGE(TAG, "tp: teleporter %d is cut off", i); return false; }
        tp_t *t = &out->items[out->count];
        *t = (tp_t){ .tx = h[0], .ty = h[1], .tw = h[2], .th = h[3], .dest_tx = h[4], .dest_ty = h[5], .face = h[6] };
        if (h[7] > TP_NAME_MAX) { ESP_LOGE(TAG, "tp: teleporter %d's map name is too long", i); return false; }
        if (h[7] && fread(t->map, 1, h[7], f) != h[7]) { ESP_LOGE(TAG, "tp: teleporter %d's map name is cut off", i); return false; }
        t->map[h[7]] = '\0';
        bool ok = t->tw && t->th && t->tx + t->tw <= TILE_COLS && t->ty + t->th <= TILE_ROWS &&
                  t->dest_tx < TILE_COLS && t->dest_ty < TILE_ROWS && t->face <= 4 && tp_name_ok(t->map);
        if (!ok) { ESP_LOGW(TAG, "tp: teleporter %d (to \"%s\") is invalid — skipped", i, t->map); continue; }
        out->count++;
    }
    return true;
}

// ---- Tile types (MAP11 section) ------------------------------------------
//  What every TILE_SIZE tile of the map IS — "grass", "dirt_path", "water" —
//  so game code can ask instead of guessing from pixels. MAP11 = MAP10, then:
//    type_count                uint8        0..TILE_TYPE_MAX
//    type_count x {
//        flags                 uint8        TILE_FLAG_TILLABLE = the editor's "Tillable"
//        name_len              uint8        1..TILE_NAME_MAX
//        name                  name_len bytes  the library asset's name, lowercase,
//                                            anything else turned into '_' ("Dirt Path" -> "dirt_path")
//    }
//    cells                     TILE_ROWS*TILE_COLS x uint8, row by row from the top left:
//                                           bits 0-6 = type (1 = the first one above, 0 = no tile),
//                                           TILE_CELL_COVERED = something sits on it
//  The editor gives a tile the type of the 16x16 library asset placed
//  exactly on it — the topmost one with no see-through pixels (a ground tile
//  laid with Stamp or Spread). "Covered" means something was put on that
//  ground afterwards: a decoration with see-through bits (flowers), part of a
//  bigger object or a breakable, or pixels painted over it by hand. A tile
//  with no such ground tile under it (painted by hand, under a house) is
//  TILE_NONE.
//
//  Ask with (tile coordinates: pixel / TILE_SIZE):
//    read_tile(tx, ty)          what's there now: TILE_FARMLAND(_WATERED) once
//                               the hoe tilled it (FARMING), else the map's tile
//    read_map_tile(tx, ty)      the tile the map was exported with (under any farmland)
//    read_tile_name(tx, ty)     read_tile() as a name: "grass", "farmland", "" for none
//    tile_is(tx, ty, "water")   read_tile_name() == "water"
//    tile_tillable(tx, ty)      ground ticked Tillable in the editor, with nothing on it
//  Type numbers are per map (the order the editor met them), so compare
//  names, not numbers, across maps.
#define TILE_TYPE_MAX          127
#define TILE_NAME_MAX          31
#define TILE_FLAG_TILLABLE     0x01
#define TILE_FLAG_BUILDABLE    0x02  // the editor's "Buildable": buildings may stand on it (PLACEMENT)
#define TILE_FLAG_FISHABLE     0x04  // the editor's "Fishable": water a fishing rod casts into (FISHING)
#define TILE_FLAG_LAVA         0x08  // the editor's "Lava": fished only with a lava rod, its own fish (FISHING)
#define TILE_CELL_COVERED      0x80
#define TILE_NONE              0     // no tile type here (see above), off the map, or a map from before MAP11
#define TILE_FARMLAND          254   // tilled with a hoe (FARMING) — the same on every map
#define TILE_FARMLAND_WATERED  255   // ...and watered

typedef struct {
    char    name[TILE_NAME_MAX + 1];
    uint8_t flags;
} tile_type_t;

typedef struct {
    tile_type_t types[TILE_TYPE_MAX + 1];      // [0] = TILE_NONE ("")
    int         type_count;                    // not counting [0]
    uint8_t     cells[TILE_ROWS][TILE_COLS];
} tile_bank_t;

static tile_bank_t *s_tiles     = NULL;   // PSRAM: the loaded map's
static tile_bank_t *s_tiles_new = NULL;   // PSRAM: load_map() parses into this, then swaps the two

// Farmland on the loaded map, per tile (SOIL_* — FARMING owns it; read_tile() reports it).
enum { SOIL_NONE = 0, SOIL_DRY, SOIL_WATERED };
static uint8_t s_soil[TILE_ROWS][TILE_COLS];

// Both banks, taken the first time a map loads. false = no PSRAM.
static bool tile_banks_ok(void)
{
    if (!s_tiles)     s_tiles     = heap_caps_calloc(1, sizeof(tile_bank_t), MALLOC_CAP_SPIRAM);
    if (!s_tiles_new) s_tiles_new = heap_caps_calloc(1, sizeof(tile_bank_t), MALLOC_CAP_SPIRAM);
    return s_tiles && s_tiles_new;
}

// Reads the MAP11 tile section. false = cut off / malformed (fails the
// load, like the other sections); a cell naming a type that isn't in the
// table is only reset to TILE_NONE.
static bool tile_bank_read(FILE *f, tile_bank_t *out)
{
    memset(out, 0, sizeof(*out));
    uint8_t count;
    if (fread(&count, 1, 1, f) != 1) { ESP_LOGE(TAG, "tiles: file ends before the tile type count"); return false; }
    if (count > TILE_TYPE_MAX) { ESP_LOGE(TAG, "tiles: %u tile types exceeds the limit (%d)", count, TILE_TYPE_MAX); return false; }
    for (int i = 1; i <= count; i++) {
        uint8_t h[2];
        tile_type_t *t = &out->types[i];
        if (fread(h, 1, 2, f) != 2) { ESP_LOGE(TAG, "tiles: tile type %d is cut off", i); return false; }
        if (h[1] == 0 || h[1] > TILE_NAME_MAX) { ESP_LOGE(TAG, "tiles: tile type %d's name is %u long", i, h[1]); return false; }
        if (fread(t->name, 1, h[1], f) != h[1]) { ESP_LOGE(TAG, "tiles: tile type %d's name is cut off", i); return false; }
        t->name[h[1]] = '\0';
        t->flags = h[0];
    }
    out->type_count = count;
    if (fread(out->cells, 1, sizeof(out->cells), f) != sizeof(out->cells)) { ESP_LOGE(TAG, "tiles: the tile grid is cut off"); return false; }
    int bad = 0;
    for (int ty = 0; ty < TILE_ROWS; ty++)
        for (int tx = 0; tx < TILE_COLS; tx++)
            if ((out->cells[ty][tx] & ~TILE_CELL_COVERED) > count) { out->cells[ty][tx] = TILE_NONE; bad++; }
    if (bad) ESP_LOGW(TAG, "tiles: %d tile%s named a type that isn't in the table — read as no tile", bad, bad == 1 ? "" : "s");
    return true;
}

static bool tile_on_map(int tx, int ty) { return tx >= 0 && ty >= 0 && tx < TILE_COLS && ty < TILE_ROWS; }

uint8_t read_map_tile(int tx, int ty)
{
    if (!s_map_loaded || !s_tiles || !tile_on_map(tx, ty)) return TILE_NONE;
    return s_tiles->cells[ty][tx] & ~TILE_CELL_COVERED;
}

uint8_t read_tile(int tx, int ty)
{
    if (s_map_loaded && tile_on_map(tx, ty) && s_soil[ty][tx] != SOIL_NONE)
        return s_soil[ty][tx] == SOIL_WATERED ? TILE_FARMLAND_WATERED : TILE_FARMLAND;
    return read_map_tile(tx, ty);
}

const char *read_tile_name(int tx, int ty)
{
    uint8_t t = read_tile(tx, ty);
    if (t == TILE_FARMLAND)         return "farmland";
    if (t == TILE_FARMLAND_WATERED) return "farmland_watered";
    return (t != TILE_NONE && s_tiles) ? s_tiles->types[t].name : "";
}

bool tile_is(int tx, int ty, const char *name)
{
    return name && name[0] && strcmp(read_tile_name(tx, ty), name) == 0;
}

// Something was put on this tile's ground in the editor (see above).
static bool tile_covered(int tx, int ty)
{
    return s_map_loaded && s_tiles && tile_on_map(tx, ty) && (s_tiles->cells[ty][tx] & TILE_CELL_COVERED);
}

bool tile_tillable(int tx, int ty)
{
    uint8_t t = read_map_tile(tx, ty);
    return t != TILE_NONE && (s_tiles->types[t].flags & TILE_FLAG_TILLABLE) && !tile_covered(tx, ty);
}

// Ground ticked "Buildable" in the editor, with nothing on it: a building may stand here.
bool tile_buildable(int tx, int ty)
{
    uint8_t t = read_map_tile(tx, ty);
    return t != TILE_NONE && (s_tiles->types[t].flags & TILE_FLAG_BUILDABLE) && !tile_covered(tx, ty);
}

// Water ticked "Fishable" (or ground ticked "Lava") in the editor (something on it, like a lily pad, doesn't matter).
bool tile_fishable(int tx, int ty)
{
    uint8_t t = read_map_tile(tx, ty);
    return t != TILE_NONE && (s_tiles->types[t].flags & (TILE_FLAG_FISHABLE | TILE_FLAG_LAVA));
}

// Ground ticked "Lava": fished like water, but only with a lava rod (FISHING).
bool tile_lava(int tx, int ty)
{
    uint8_t t = read_map_tile(tx, ty);
    return t != TILE_NONE && (s_tiles->types[t].flags & TILE_FLAG_LAVA);
}

// ---- Action triggers (MAP12 section) ---------------------------------------
//  Objects that run ASSET ACTIONS (actions.h) when tapped — every placed copy
//  of a library asset that has actions ticked in the editor. MAP12 = MAP11, then:
//    trig_count                uint8        0..TRIG_MAX
//    trig_count x {
//        x, y, w, h            4 x uint16   the placed object's footprint, in pixels
//        action_count          uint8        1..TRIG_ACTIONS_MAX
//        action_count x {
//            id_len            uint8        1..ACTION_ID_MAX
//            id                id_len bytes  an ASSET_ACTION id in main/actions.c ("seed_shop")
//        }
//    }
//  An id this build doesn't have is logged and skipped (the map still
//  loads). What a tap does is in the ASSET ACTIONS runtime section.
#define TRIG_MAX          64
#define TRIG_ACTIONS_MAX  4

typedef struct {
    int16_t x, y, w, h;                   // footprint, in pixels
    uint8_t action_count;
    uint8_t actions[TRIG_ACTIONS_MAX];    // k_asset_actions[] indices, run in this order
} trig_t;

typedef struct {
    trig_t items[TRIG_MAX];
    int    count;
} trig_bank_t;

static trig_bank_t s_trig;       // the loaded map's
static trig_bank_t s_trig_new;   // load_map() parses into this, then copies it over s_trig

// Reads the MAP12 trigger section. false = cut off / malformed (fails the load).
static bool trig_bank_read(FILE *f, trig_bank_t *out)
{
    out->count = 0;
    uint8_t count;
    if (fread(&count, 1, 1, f) != 1) { ESP_LOGE(TAG, "trig: file ends before the trigger count"); return false; }
    if (count > TRIG_MAX) { ESP_LOGE(TAG, "trig: %u triggers exceeds the limit (%d)", count, TRIG_MAX); return false; }
    for (int i = 0; i < count; i++) {
        uint8_t h[9];
        if (fread(h, 1, sizeof(h), f) != sizeof(h)) { ESP_LOGE(TAG, "trig: trigger %d is cut off", i); return false; }
        if (h[8] == 0 || h[8] > TRIG_ACTIONS_MAX) { ESP_LOGE(TAG, "trig: trigger %d has %u actions", i, h[8]); return false; }
        trig_t t = { .x = (int16_t)(h[0] | h[1] << 8), .y = (int16_t)(h[2] | h[3] << 8),
                     .w = (int16_t)(h[4] | h[5] << 8), .h = (int16_t)(h[6] | h[7] << 8) };
        for (int a = 0; a < h[8]; a++) {
            uint8_t len;
            char    id[ACTION_ID_MAX + 1];
            if (fread(&len, 1, 1, f) != 1 || len == 0 || len > ACTION_ID_MAX || fread(id, 1, len, f) != len) {
                ESP_LOGE(TAG, "trig: trigger %d's action %d is cut off or malformed", i, a);
                return false;
            }
            id[len] = '\0';
            int k = asset_action_find(id);
            if (k < 0) ESP_LOGW(TAG, "trig: action \"%s\" (trigger %d) isn't in main/actions.c of this build — skipped", id, i);
            else       t.actions[t.action_count++] = (uint8_t)k;
        }
        bool ok = t.w > 0 && t.h > 0 && t.x >= 0 && t.y >= 0 && t.x + t.w <= LCD_H_RES && t.y + t.h <= LCD_V_RES;
        if (!ok)                 ESP_LOGW(TAG, "trig: trigger %d is off the map — skipped", i);
        else if (t.action_count) out->items[out->count++] = t;
    }
    return true;
}

static void nav_reset(void);
static void ground_clear(void);   // GROUND ITEMS section: dropped stacks belong to the old map
static void place_clear(void);           // PLACEMENT section: the old map's props and buildings (they're in its save)
