static void nav_trail_paint_rect(int x, int y, int w, int h);   // TAP-TO-WALK: a drawn path's dots, drawn by map_repaint_rect()
static direction_t nav_delta_to_dir(int dx, int dy);
static void brk_reach_box(int px, int py, direction_t facing, int *rx0, int *ry0, int *rx1, int *ry1);

// Reads the MAP2/MAP6/MAP7/MAP8/MAP9/MAP10 file at `path` (full path, e.g. from map_path_for()),
// and on success: fades the screen to black, swaps in the new map's
// pixel + collision + layer buffers (and, for a MAP6+ file, its shared
// Frame Bundles, animations, and breakables), then fades the new map in
// from black to full brightness and starts the animations. On any
// read/parse failure, nothing is touched — the screen is never darkened
// and whatever map was loaded before (if any) stays loaded and on screen.
//
// The file stays open afterwards: animation frames and breakable art are
// read from it as they're shown (SD STREAMING), so leave the card in.
//
// Blocking — takes as long as the fade (~1.8s total) plus however long
// the SD read takes. Call from a task that's fine pausing for that (a
// map-transition trigger, not your per-frame render loop) — teleporters
// go through tp_travel(). current_map_name() follows the new map.
static uint32_t s_load_read_ms = 0, s_load_ms = 0;   // the last load_map(): reading + setting up, and in all (dev link "state")

bool load_map(const char *path)
{
    int64_t t_load = esp_timer_get_time();
    mapsave_flush();              // the loaded map's last changes, before it can go away (MAP SAVES)
    uint16_t inst = s_load_inst_next;   // a building's inside (PLACEMENT): only for this one load
    s_load_inst_next = 0;
    FILE *f = fopen(path, "rb");
    if (!f) {
        ESP_LOGE(TAG, "load_map: %s not found", path);
        return false;
    }

    uint8_t header[8];
    if (fread(header, 1, 8, f) != 8) header[0] = 0;
    // 6 = legacy numeric drop/tool, 7 = legacy numeric tool, 8 = current
    // (items by id — see the BREAKABLE format notes); 0 = MAP2 or not a map
    int brk_version = (memcmp(header, "MAP6", 4) == 0) ? 6 :
                      (memcmp(header, "MAP7", 4) == 0) ? 7 :
                      (memcmp(header, "MAP8", 4) == 0) ? 8 :
                      (memcmp(header, "MAP9", 4) == 0) ? 9 :      // 9 = 8 + teleporters
                      (memcmp(header, "MAPA", 4) == 0) ? 10 :     // 10 = 9 + overlapping breakables
                      (memcmp(header, "MAPB", 4) == 0) ? 11 :     // 11 = 10 + tile types
                      (memcmp(header, "MAPC", 4) == 0) ? 12 :     // 12 = 11 + action triggers
                      (memcmp(header, "MAPD", 4) == 0) ? 13 :     // 13 = 12 + breakable falls
                      (memcmp(header, "MAPE", 4) == 0) ? 14 : 0;  // 14 = 13 + breakable sounds
    if (brk_version == 0 && memcmp(header, "MAP2", 4) != 0) {
        if (memcmp(header, "MAP5", 4) == 0)
            ESP_LOGE(TAG, "load_map: %s is MAP5 (old editor export) — re-export it from the map editor", path);
        else
            ESP_LOGE(TAG, "load_map: %s is not a valid MAP2/MAP6/MAP7/MAP8/MAP9/MAP10/MAP11/MAP12/MAP13/MAP14 file", path);
        fclose(f);
        return false;
    }
    bool has_bundles = (brk_version != 0);   // MAP6+ = MAP2 + bundles/animations/breakables
    // Width/height are little-endian in the file; the ESP32-S3 is itself
    // little-endian, but this reads the two bytes explicitly rather than
    // casting the buffer, so it doesn't depend on that assumption.
    int w = header[4] | (header[5] << 8);
    int h = header[6] | (header[7] << 8);
    if (w != LCD_H_RES || h != LCD_V_RES) {
        ESP_LOGE(TAG, "load_map: %s is %dx%d, expected %dx%d", path, w, h, LCD_H_RES, LCD_V_RES);
        fclose(f);
        return false;
    }

    size_t pixel_count  = (size_t)w * h;
    size_t hitbox_bytes = (pixel_count + 7) / 8; // also the size of the foreground mask — same layout
    size_t pixel_bytes  = pixel_count * sizeof(uint16_t);
    size_t base_end     = 8 + pixel_bytes + 2 * hitbox_bytes;   // the MAP6+ sections start here

    // PSRAM: the map is always exactly one screen, so the live pixel,
    // collision and layer buffers are allocated once (first map) and every
    // later load copies into them — the old map and a whole second copy of
    // it never sit in PSRAM together, and the ~500 KB blocks never move.
    // Until the swap, the new pixels wait in the hold buffer (which UI
    // screens and the night stages need at this size anyway). Animation
    // frames and breakable art aren't loaded at all: they stream from this
    // file, which stays open (SD STREAMING).
    long file_len = (fseek(f, 0, SEEK_END) == 0) ? ftell(f) : -1;
    if (file_len < (long)base_end) {
        ESP_LOGE(TAG, "load_map: %s truncated or short read", path);
        fclose(f);
        return false;
    }
    s_loading_file_len = file_len;   // a loading screen's bar goes by how far into the file the read is
    stream_init();

    night_before_map_swap();      // the background night loader must be off the hold buffer
    uint16_t *st_px = NULL;
    void     *own_px = NULL;
    uint8_t  *st_masks = heap_caps_malloc(2 * hitbox_bytes, MALLOC_CAP_SPIRAM);   // collision, then layer
    if (!ui_screen_open() && hold_buffer_fit(pixel_count)) st_px = s_hold_buf;
    if (!st_px) st_px = own_px = heap_caps_malloc(pixel_bytes, MALLOC_CAP_SPIRAM);
    if (!s_map_pixels) s_map_pixels = heap_caps_malloc(pixel_bytes, MALLOC_CAP_SPIRAM);
    if (!s_map_hitbox) s_map_hitbox = heap_caps_malloc(hitbox_bytes, MALLOC_CAP_SPIRAM);
    if (!s_map_fgmask) s_map_fgmask = heap_caps_malloc(hitbox_bytes, MALLOC_CAP_SPIRAM);
    bool mem_ok = st_px && st_masks && s_map_pixels && s_map_hitbox && s_map_fgmask;

    // File stores each pixel as a little-endian uint16 RGB565 value — the
    // ESP32-S3 is itself little-endian, so a raw fread straight into the
    // uint16_t buffer needs no byte-swapping. Layout is: pixels, then the
    // collision bitmask, then the foreground-layer bitmask — same order
    // the map editor's Export writes them in.
    bool read_ok = mem_ok && fseek(f, 8, SEEK_SET) == 0 &&
                   fread(st_px, 1, pixel_bytes, f) == pixel_bytes &&
                   fread(st_masks, 1, 2 * hitbox_bytes, f) == 2 * hitbox_bytes;
    if (!read_ok) {
        if (!mem_ok) ESP_LOGE(TAG, "load_map: PSRAM allocation failed for %s (%u KB of map pixels + %u KB of masks)",
                              path, (unsigned)(pixel_bytes / 1024), (unsigned)(2 * hitbox_bytes / 1024));
        else         ESP_LOGE(TAG, "load_map: %s truncated or short read", path);
        heap_caps_free(own_px);
        heap_caps_free(st_masks);
        fclose(f);
        return false;
    }
    s_load_hash = night_fnv(2166136261u, st_px, (uint32_t)pixel_count);
    loading_file_tick(f);

    // MAP6+: the shared Frame Bundle table comes first, then the animation
    // instances, then the breakables — both of the latter reference
    // bundles by index, so the table has to be parsed (and validated)
    // before either. All parsed into temporaries, so a bad section fails
    // the whole load BEFORE anything on screen or in the live buffers is
    // touched. The art is skipped over (and hashed for the night stages);
    // only breakable masks are kept, in the map store.
    bundle_bank_t new_bundles = { 0 };
    anim_bank_t   new_anims   = { 0 };
    brk_bank_t    new_brk     = { 0 };
    map_store_t   new_store   = { 0 };
    s_tp_new.count   = 0;
    s_trig_new.count = 0;                                                  // before MAP12: no triggers
    if (tile_banks_ok()) memset(s_tiles_new, 0, sizeof(*s_tiles_new));   // before MAP11: no tile types
    bool parsed = true, mem_left = true;
    if (has_bundles) {
        size_t store_bytes = ((size_t)file_len - base_end) / 4 + 16;
        new_store.base = heap_caps_malloc(store_bytes, MALLOC_CAP_SPIRAM);
        new_store.size = new_store.base ? store_bytes : 0;
        parsed = new_store.base &&
                 bundle_bank_read(f, &new_bundles) &&
                 anim_bank_read(f, w, h, &new_bundles, &new_anims) &&
                 brk_bank_read(f, w, h, &new_bundles, brk_version, &new_store, &new_brk) &&
                 (brk_version < 9 || tp_bank_read(f, &s_tp_new)) &&
                 tile_banks_ok() && (brk_version < 11 || tile_bank_read(f, s_tiles_new)) &&
                 (brk_version < 12 || trig_bank_read(f, &s_trig_new)) &&
                 (brk_version < 14 || brk_sfx_read(f, &new_brk));
        if (parsed && new_store.used < new_store.size) {   // give back what the masks didn't use
            uint8_t *moved = heap_caps_realloc(new_store.base, new_store.used ? new_store.used : 1, MALLOC_CAP_SPIRAM);
            if (moved) {
                if (moved != new_store.base) brk_bank_rebase(&new_brk, (uintptr_t)new_store.base, moved);
                new_store.base = moved;
                new_store.size = new_store.used;
            }
        }
        mem_left = parsed && anim_play_setup(&new_bundles, &new_anims) && brk_scratch_setup(&new_brk);
    }
    if (!parsed || !mem_left) {
        // whichever of these got as far as parsing has real allocations to free
        if (!parsed) ESP_LOGE(TAG, "load_map: %s has a bad bundle/animation/breakable/teleporter/tile/trigger section (or no PSRAM for its masks or tile types)", path);
        else         ESP_LOGE(TAG, "load_map: no PSRAM for %s's animation frames / breakable scratch", path);
        bundle_bank_free(&new_bundles);
        anim_bank_free(&new_anims);
        brk_bank_free(&new_brk);
        store_free(&new_store);
        heap_caps_free(own_px);
        heap_caps_free(st_masks);
        fclose(f);
        return false;
    }

    // Every pixel a night stage file holds, in its block order: the map,
    // every bundle frame, every breakable look (see DAY / NIGHT).
    uint32_t night_px = (uint32_t)pixel_count;
    for (int i = 0; i < new_bundles.count; i++)
        night_px += (uint32_t)new_bundles.items[i].frame_count * new_bundles.items[i].w * new_bundles.items[i].h;
    for (int i = 0; i < new_brk.count; i++) {
        const brk_inst_t *b = &new_brk.inst[i];
        for (int l = 0; l < b->level_count; l++) night_px += (uint32_t)b->levels[l].w * b->levels[l].h;
        night_px += (uint32_t)b->w * b->h;
    }

    // File is fully parsed and valid — only now do we touch the screen or
    // the live buffers, so a bad file never interrupts what's on screen.
    // Un-XOR any highlight first — the fade is about to repaint the whole
    // screen, so its old XOR state would otherwise go stale and leave a
    // stray box (or fail to clear one) once a new highlight is drawn.
    loading_finish();             // a loading screen (if one is up) shows a full bar, then fades out with the rest
    player_reset_selected_tile();
    nav_reset();                  // a walk (and its marker) belongs to the old map
    place_holo_reset();           // and so does a prop's hologram
    fish_reset();                 // and a fishing line that was out
    s_load_read_ms = (uint32_t)((esp_timer_get_time() - t_load) / 1000);
    screen_fade_to_black();

    memcpy(s_map_pixels, st_px, pixel_bytes);
    memcpy(s_map_hitbox, st_masks, hitbox_bytes);
    memcpy(s_map_fgmask, st_masks + hitbox_bytes, hitbox_bytes);
    heap_caps_free(own_px);
    heap_caps_free(st_masks);

    // The streamer finishes with the old map, then streams from this file.
    stream_drain();
    xSemaphoreTake(s_mapf_mx, portMAX_DELAY);
    if (s_mapf) fclose(s_mapf);
    s_mapf        = f;
    s_mapf_warned = false;
    xSemaphoreGive(s_mapf_mx);
    s_map_w = w;
    s_map_h = h;
    s_map_loaded = true;
    snprintf(s_map_path, sizeof(s_map_path), "%s", path);
    const char *base = strrchr(path, '/');
    base = base ? base + 1 : path;
    snprintf(s_current_map_name, sizeof(s_current_map_name), "%.*s", (int)strcspn(base, "."), base);
    s_map_inst = inst;
    memcpy(&s_tp, &s_tp_new, sizeof(s_tp));
    s_trig.count = s_trig_new.count;
    memcpy(s_trig.items, s_trig_new.items, (size_t)s_trig_new.count * sizeof(trig_t));
    if (s_tiles_new) {            // the new map's tile types; the old bank is the next load's scratch
        tile_bank_t *old = s_tiles;
        s_tiles     = s_tiles_new;
        s_tiles_new = old;
    }
    s_hotbar_img_valid = false;   // the hotbar's translucent background comes from the map
    // Order matters: breakables and animation instances hold pointers INTO
    // the bundle table, so free/replace the old bundles only after they
    // no longer have anything referencing them, and install the new
    // bundles before anything that points into them gets used.
    brk_bank_free(&s_brk);
    anim_bank_free(&s_anim);
    bundle_bank_free(&s_bundles);
    store_free(&s_map_store);     // the old map's frames/breakable pixels, now unreferenced
    s_map_store = new_store;
    s_bundles = new_bundles;
    memset(&new_bundles, 0, sizeof(new_bundles));
    brk_bank_install(&new_brk);
    anim_bank_install(&new_anims);
    ground_clear();
    farm_clear();                 // the old map's crops and farmland (they're in its save)
    ranch_clear();                // its animals and grass (ANIMALS — in its save too)
    place_clear();                // and its props and buildings
    npc_clear();                  // and its shoppers' bodies (MARKET — they're still out shopping)
    market_map_loaded();
    s_map_hash = s_load_hash;
    place_buildings_apply();      // buildings placed here (buildings.txt) — before the save, whose lines are checked against them
    mapsave_load();               // broken breakables + dropped stacks from /sdcard/saves (the .map is never written)
    // The fade repainted the whole screen, so the player sprite that was
    // on it is gone and the cached "pixels under the player" belong to the
    // OLD map — forget them, or the next move would paste them back.
    player_invalidate_bg();
    msg_invalidate();             // same for an on-screen message (its panel is blended over the map, too)
    clock_invalidate();           // and the clock
    night_map_loaded(path, night_px, s_load_hash);   // at night, fades in already dark (and reads the animations' first frames)
    if (s_night_shown == 0) anim_frames_reload();       // in daylight: read them here
    mapsave_show();                                     // the restored changes, in that tint

    fade_in_from_black(s_map_pixels, pixel_count); // shows frame 1 of every animation
    anim_reset_timers();                            // animations start moving now
    s_load_ms = (uint32_t)((esp_timer_get_time() - t_load) / 1000);

    ESP_LOGI(TAG, "load_map: %s loaded (%dx%d, %d animated objects, %d shared frame bundles, %d teleporters, %d tile types, %d action triggers; "
                  "%u KB breakable masks in PSRAM, art streamed; PSRAM free %u KB, largest block %u KB)",
             path, w, h, s_anim.inst_count, s_bundles.count, s_tp.count, s_tiles ? s_tiles->type_count : 0, s_trig.count,
             (unsigned)(s_map_store.used / 1024),   // masks only now
             (unsigned)(heap_caps_get_free_size(MALLOC_CAP_SPIRAM) / 1024),
             (unsigned)(heap_caps_get_largest_free_block(MALLOC_CAP_SPIRAM) / 1024));
    return true;
}

// True if the pixel at (x, y) is marked blocked in the currently loaded
// map's collision bitmask. Returns false (walkable) if no map is
// loaded yet, and true (blocked) for any coordinate outside the map —
// so unloaded/out-of-bounds space can't accidentally be walked into.
// This is a per-pixel check (the bitmask is 1 bit per pixel, not per
// tile) — a starting point to build tile-based movement collision on
bool map_pixel_blocked(int x, int y)
{
    if (!s_map_loaded) return false;
    if (x < 0 || y < 0 || x >= s_map_w || y >= s_map_h) return true;
    int i = y * s_map_w + x;
    return (s_map_hitbox[i / 8] >> (7 - (i % 8))) & 1;
}

// Returns 1 if (x,y) is on layer 1 ("foreground" — drawn in front of the
// player, so the player appears to go under it), or 0 for layer -1
// ("ground" — the default). Out-of-bounds or no map loaded -> 0 (ground),
// same "default" behavior as the ground layer itself.
int map_pixel_layer(int x, int y)
{
    if (!s_map_loaded) return 0;
    if (x < 0 || y < 0 || x >= s_map_w || y >= s_map_h) return 0;
    int i = y * s_map_w + x;
    return ((s_map_fgmask[i / 8] >> (7 - (i % 8))) & 1) ? 1 : 0;
}

// Restores a rect to the loaded map's real pixel colors — used to erase
// the player's previous position without wiping out whatever ground or
// foreground art is actually there. Falls back to a black fill if no map
// is loaded yet (same placeholder behavior update_player() used before).
// Bounded to the given rect only — cheap regardless of map size.
static void restore_map_rect(int x, int y, int w, int h)
{
    if (!s_map_loaded) { fill_rect(x, y, w, h, COLOR_BLACK); return; }
    int x0 = x < 0 ? 0 : x;
    int y0 = y < 0 ? 0 : y;
    int x1 = (x + w > s_map_w) ? s_map_w : x + w;
    int y1 = (y + h > s_map_h) ? s_map_h : y + h;
    if (x0 >= x1 || y0 >= y1) return;
    // load_map() only ever accepts a map sized exactly LCD_H_RES x LCD_V_RES
    // (see the check in load_map()), so a row clipped to [x0,x1) x s_map_w
    // is already within s_fb's own bounds — one memcpy per row instead of
    // a per-pixel draw_pixel() call (each of which redid the same 4 bounds
    // checks s_map_w/h clipping above already guarantees are unnecessary here).
    size_t row_bytes = (size_t)(x1 - x0) * sizeof(uint16_t);
    for (int py = y0; py < y1; py++) {
        memcpy(&s_fb[py * LCD_H_RES + x0], &s_map_pixels[py * s_map_w + x0], row_bytes);
    }
}

// Re-stamps any layer-1 ("foreground") map pixels that fall inside the
// given rect, straight from the loaded map's pixel data — and, for
// animated objects, from their CURRENT frame (see anim_restamp_foreground).
// Call this right after drawing the player sprite so foreground objects
// (trees, bridges, etc.) that overlap the player visually cover it again —
// this is what makes the player appear to go UNDER them. No-op if no map
// is loaded. Bounded to the given rect only — cheap regardless of map size.
static void redraw_foreground_over_rect(int x, int y, int w, int h)
{
    if (!s_map_loaded) return;
    int x0 = x < 0 ? 0 : x;
    int y0 = y < 0 ? 0 : y;
    int x1 = (x + w > s_map_w) ? s_map_w : x + w;
    int y1 = (y + h > s_map_h) ? s_map_h : y + h;
    // Same layer-1 pixels get restamped as before (still one fgmask bit
    // test per pixel), but consecutive layer-1 pixels in a row are now
    // flushed as a single memcpy run instead of one draw_pixel() call
    // each — foreground art is usually drawn in solid runs (tree trunks,
    // bridge rails, ...), so this is normally far fewer memory ops for
    // the exact same set of pixels ending up restamped.
    for (int py = y0; py < y1; py++) {
        int row_base = py * s_map_w;
        int run_start = -1;
        for (int px = x0; px <= x1; px++) {
            bool set = (px < x1) && ((s_map_fgmask[(row_base + px) / 8] >> (7 - ((row_base + px) % 8))) & 1);
            if (set) {
                if (run_start < 0) run_start = px;
            } else if (run_start >= 0) {
                memcpy(&s_fb[py * LCD_H_RES + run_start], &s_map_pixels[row_base + run_start],
                       (size_t)(px - run_start) * sizeof(uint16_t));
                run_start = -1;
            }
        }
    }
    // s_map_pixels holds frame 1 of each animation; overwrite those spots
    // with whatever frame is on screen right now.
    anim_restamp_foreground(x0, y0, x1 - x0, y1 - y0);
    // A falling breakable is in front of everything, the player included.
    brk_fall_restamp(x0, y0, x1 - x0, y1 - y0);
}

// ============================================================
//  MAP NAME — which map is loaded, as its file name without the folder
//  or ".map" (".../maps/cave/cave.map" -> "cave"), so registry entries below can
//  say "only on this map". load_map() keeps it up to date — teleporting to
//  another map changes it too.
// ============================================================
const char *current_map_name(void)
{
    return s_current_map_name;
}

// Coordinates of the tile the highlight XOR box is currently drawn on;
// -1,-1 = "no highlight drawn yet". Declared here (rather than down in
// the PLAYER section where it's mostly read/written) so the highlight
// helpers right below, and player_reset_selected_tile() further down,
// all see it already declared.
static int s_selected_tile_x = -1;
static int s_selected_tile_y = -1;

// ============================================================
//  SELECTED AREA REGISTRY — data-driven, same pattern as the menu
//  registry further down. Each entry is "map name + tile_x + tile_y ->
//  function". check_selected_area() compares the CURRENT selected
//  tile + current map against every entry; on a match it calls that
//  entry's function, otherwise nothing happens. Add new interactions
//  by adding rows — nothing else needs to change.
// ============================================================
typedef void (*selected_area_fn)(void);

typedef struct {
    const char *map;         // must equal current_map_name(), e.g. "map" for map.map
    int tile_x, tile_y;      // must equal the current selected tile
    selected_area_fn on_match;
} 
selected_area_t;

// Placeholder actions — replace with real game logic, and add more
// functions + registry rows below as you add interactions.
static void action_open_chest(void)
{
    ESP_LOGI(TAG, "selected area: opened the chest!");
    // TODO: give the player an item, mark chest opened, etc.
}

static void action_talk_to_npc(void)
{
    ESP_LOGI(TAG, "selected area: talked to the NPC");
}

static const selected_area_t s_selected_area_registry[] = {
    { .map = "map", .tile_x = 10, .tile_y = 12, .on_match = action_open_chest },
    { .map = "map", .tile_x = 15, .tile_y = 15, .on_match = action_talk_to_npc },
    // add more rows here: { .map = "...", .tile_x = ..., .tile_y = ..., .on_match = ... },
};
#define SELECTED_AREA_COUNT (sizeof(s_selected_area_registry) / sizeof(s_selected_area_registry[0]))

// Walks the registry; if the given map+tile_x+tile_y matches a row,
// calls that row's function. Does nothing on no match. Only the first
// match fires — remove the early return if you want to allow stacking
// multiple entries on the same tile.
static void check_selected_area(const char *map, int tile_x, int tile_y)
{
    for (size_t i = 0; i < SELECTED_AREA_COUNT; i++) {
        const selected_area_t *a = &s_selected_area_registry[i];
        if (strcmp(a->map, map) == 0 && a->tile_x == tile_x && a->tile_y == tile_y) {
            if (a->on_match) a->on_match();
            return;
        }
    }
}

// XORs one pixel's color. Used only to visualize the selected tile —
// XOR-ing the same pixels twice restores their exact original color,
// so the highlight box needs no separate background buffer to erase
// itself against, unlike the player sprite's erase-with-black-fill
// further down.
//
// Pixels under the hotbar / touch button (ui_overlay_covers) are never
// XOR'd: those overlays get redrawn opaque at any time, which would
// silently drop XOR bits living on them and leave stray boxes behind later.
static bool ui_overlay_covers(int px, int py);   // defined with the touch button, in the INPUT section
static bool player_area_covers(int px, int py);  // defined with the player background cache, further down —
                                                  // true over the player's current on-screen footprint, so
                                                  // the player always draws OVER the highlight, never under it

static inline void draw_pixel_xor(int x, int y)
{
    if (x < 0 || y < 0 || x >= LCD_H_RES || y >= LCD_V_RES) return;
    if (ui_overlay_covers(x, y)) return;
    if (player_area_covers(x, y)) return;
    s_fb[y * LCD_H_RES + x] ^= 0xFFFF;
}

// Draws (or, called a second time at the same tile, erases) a 1px
// border around the given tile — this is what makes the selected area
// visible on screen.
static void draw_tile_highlight_xor(int tile_x, int tile_y)
{
    int x = tile_x * TILE_SIZE;
    int y = tile_y * TILE_SIZE;
    for (int i = 0; i < TILE_SIZE; i++) {
        draw_pixel_xor(x + i, y);                  // top edge
        draw_pixel_xor(x + i, y + TILE_SIZE - 1);   // bottom edge
        draw_pixel_xor(x, y + i);                   // left edge
        draw_pixel_xor(x + TILE_SIZE - 1, y + i);   // right edge
    }
}

// True if (px,py) is one of the border pixels draw_tile_highlight_xor()
// currently has XOR'd for the selected tile (corners excluded — they get
// flipped twice by that function, i.e. net unchanged). Same test as
// anim_highlight_covers() further down (that one is scoped to the
// animation/breakable repaint code; this copy exists so the PLAYER
// section below — which runs earlier in the file — can use it too).
static bool tile_highlight_covers(int px, int py)
{
    if (s_selected_tile_x < 0 || s_selected_tile_y < 0) return false;
    if (ui_overlay_covers(px, py)) return false;   // draw_pixel_xor() skips these too
    if (player_area_covers(px, py)) return false;  // ditto — the player draws over the highlight, not under it
    int x0 = s_selected_tile_x * TILE_SIZE, y0 = s_selected_tile_y * TILE_SIZE;
    int x1 = x0 + TILE_SIZE - 1,            y1 = y0 + TILE_SIZE - 1;
    if (px < x0 || px > x1 || py < y0 || py > y1) return false;
    bool on_x_edge = (px == x0 || px == x1);
    bool on_y_edge = (py == y0 || py == y1);
    if (on_x_edge && on_y_edge) return false;   // corner: flipped twice
    return on_x_edge || on_y_edge;
}

// Re-flips the highlight XOR back on over any pixel of [x,y,w,h) that
// tile_highlight_covers() says belongs to the selected tile's outline.
// Call this immediately after ANY raw (non-XOR) draw that might have
// painted over the highlighted tile — a moving player sprite is the
// main case. Skipping this is exactly what caused the highlight to
// "not erase right": draw_image() has no idea an XOR box lives on some
// of the pixels it's about to overwrite, so it just paints raw sprite
// color over them. The highlight's *state* (s_selected_tile_x/y) stays
// "on" for that tile, but the framebuffer no longer reflects it — so
// the NEXT time the highlight moves off that tile and the code tries to
// un-XOR it, it flips whatever raw color is sitting there now instead
// of the true ground color, leaving a stray inverted box burned into
// the screen. Restamping right after every raw overwrite keeps the
// framebuffer and the "is it highlighted" state in agreement, so the
// later un-XOR always flips exactly what it XOR'd in. No-op when
// nothing is currently selected or the rect doesn't touch it.
static void restamp_tile_highlight(int x, int y, int w, int h)
{
    if (s_selected_tile_x < 0 || s_selected_tile_y < 0) return;
    int tx = s_selected_tile_x * TILE_SIZE, ty = s_selected_tile_y * TILE_SIZE;   // only that tile's box can hold it
    int x0 = x > tx ? x : tx, x1 = x + w < tx + TILE_SIZE ? x + w : tx + TILE_SIZE;
    int y0 = y > ty ? y : ty, y1 = y + h < ty + TILE_SIZE ? y + h : ty + TILE_SIZE;
    for (int py = y0; py < y1; py++) {
        for (int px = x0; px < x1; px++) {
            if (tile_highlight_covers(px, py)) draw_pixel_xor(px, py);
        }
    }
}

// ============================================================
//  TOUCH PANEL — GT911 capacitive touch controller, over I2C.
//  Pins/rotation ported from the old Arduino prototype (TAMC_GT911 +
//  ts.setRotation(ROTATION_INVERTED)):
//    SDA=17, SCL=18, RST=38, INT not wired, panel 480x480.
//  No INT pin means we can't get an interrupt when a touch arrives —
//  touch_read() just polls the GT911's status register instead.
//
//  Bus speed is 100 kHz like the Arduino prototype's Wire default: the
//  ESP32's internal pull-ups are too weak for 400 kHz if the board has no
//  external ones, and the GT911 then never answers.
// ============================================================
#define TOUCH_I2C_SDA 17
#define TOUCH_I2C_SCL 18
#define TOUCH_RST_PIN 38
#define TOUCH_I2C_HZ  400000   // GT911 fast mode: polled every frame (no INT pin), so a quicker bus is time back each frame
#define TOUCH_I2C_TIMEOUT_MS 50   // i2c_master_* timeouts are plain milliseconds, not ticks
#define GT911_ADDR_1  0x5D   // the two addresses GT911 boards ship with;
#define GT911_ADDR_2  0x14   // we probe both since INT isn't wired to pick one
#define TOUCH_RETRY_MS    1000   // not found at boot: probe again this often...
#define TOUCH_RETRY_COUNT 5      // ...this many times (a slow-booting GT911), then give up
#define TOUCH_FLIP_X 0   // 1 = mirror touches left<->right (if taps land on the wrong side)
#define TOUCH_FLIP_Y 0   // 1 = mirror touches top<->bottom

static i2c_master_bus_handle_t s_touch_bus;
static i2c_master_dev_handle_t s_touch_dev;
static bool                    s_touch_ok = false; // false until a GT911 answers
static int                     s_touch_max_x = LCD_H_RES, s_touch_max_y = LCD_V_RES; // GT911's own resolution
static uint32_t                s_touch_taps = 0;   // touch-downs seen since boot (shown in Settings)
static char                    s_touch_status[48] = "Touch: starting"; // Settings row label (see touch_update_status)

static esp_err_t gt911_read_reg(uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t reg_buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    return i2c_master_transmit_receive(s_touch_dev, reg_buf, sizeof(reg_buf), buf, len, TOUCH_I2C_TIMEOUT_MS);
}

static esp_err_t gt911_write_reg(uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    return i2c_master_transmit(s_touch_dev, buf, sizeof(buf), TOUCH_I2C_TIMEOUT_MS);
}

// Tries to talk to a GT911 at `addr` by reading its product-ID register
// (should read back ASCII "911"). On success leaves s_touch_dev attached.
static bool gt911_probe_addr(uint8_t addr)
{
    i2c_device_config_t dev_cfg = {
        .dev_addr_length = I2C_ADDR_BIT_LEN_7,
        .device_address  = addr,
        .scl_speed_hz    = TOUCH_I2C_HZ,
    };
    i2c_master_dev_handle_t dev;
    if (i2c_master_bus_add_device(s_touch_bus, &dev_cfg, &dev) != ESP_OK) return false;

    uint8_t pid[4] = {0};
    uint8_t reg_buf[2] = {0x81, 0x40}; // GT911 product ID register
    esp_err_t err = i2c_master_transmit_receive(dev, reg_buf, sizeof(reg_buf), pid, sizeof(pid), TOUCH_I2C_TIMEOUT_MS);
    if (err == ESP_OK && pid[0] == '9') {
        s_touch_dev = dev;
        ESP_LOGI(TAG, "touch: GT911 found at 0x%02X (id \"%c%c%c\")", addr, pid[0], pid[1], pid[2]);
        return true;
    }
    ESP_LOGW(TAG, "touch: nothing GT911-like at 0x%02X (%s)", addr, esp_err_to_name(err));
    i2c_master_bus_rm_device(dev);
    return false;
}

// Rewrites the Settings row that shows what the touch panel is doing.
static void touch_update_status(void)
{
    if (s_touch_ok) snprintf(s_touch_status, sizeof(s_touch_status), "Touch: OK, %lu taps", (unsigned long)s_touch_taps);
}

// Pulses the GT911's reset line and probes both addresses. On failure with
// `scan`, it scans the whole bus and puts the first address that answered
// on screen: a different touch chip (FT6336 = 0x38, CST816 = 0x15, ...)
// shows up there. (Scanning can take seconds on a stuck bus, so the
// automatic retries in touch_read() skip it.)
static bool touch_probe(bool scan)
{
    gpio_set_level(TOUCH_RST_PIN, 0);
    vTaskDelay(pdMS_TO_TICKS(20));
    gpio_set_level(TOUCH_RST_PIN, 1);
    vTaskDelay(pdMS_TO_TICKS(100)); // GT911 needs >50 ms after reset before it answers (TAMC waits ~110)

    s_touch_ok = gt911_probe_addr(GT911_ADDR_1) || gt911_probe_addr(GT911_ADDR_2);
    if (s_touch_ok) {
        // The GT911 reports in its OWN configured resolution (config
        // registers 0x8048..0x804B); scale from that instead of assuming 480.
        uint8_t res[4];
        if (gt911_read_reg(0x8048, res, sizeof(res)) == ESP_OK) {
            int mx = res[0] | (res[1] << 8), my = res[2] | (res[3] << 8);
            if (mx > 0 && mx <= 4096 && my > 0 && my <= 4096) { s_touch_max_x = mx; s_touch_max_y = my; }
        }
        ESP_LOGI(TAG, "touch: panel reports %dx%d", s_touch_max_x, s_touch_max_y);
        touch_update_status();
        return true;
    }

    if (!scan) {
        snprintf(s_touch_status, sizeof(s_touch_status), "Touch: GT911 not answering");
        return false;
    }
    int found = -1;
    for (int a = 0x08; a < 0x78; a++) {
        if (i2c_master_probe(s_touch_bus, a, 10) == ESP_OK) {
            ESP_LOGW(TAG, "touch: I2C device answers at 0x%02X", a);
            if (found < 0) found = a;
        }
    }
    if (found >= 0) snprintf(s_touch_status, sizeof(s_touch_status), "Touch: no GT911 (chip at 0x%02X)", found);
    else            snprintf(s_touch_status, sizeof(s_touch_status), "Touch: nothing on SDA17/SCL18");
    ESP_LOGE(TAG, "touch: no GT911 on 0x%02X or 0x%02X — %s", GT911_ADDR_1, GT911_ADDR_2,
             found >= 0 ? "another chip is on the bus (see above)" : "nothing answers: check wiring/pins");
    return false;
}

// Brings up the I2C bus and finds the GT911. Call once at boot. If it
// isn't found, touch_read() probes again a few times (TOUCH_RETRY_*), and
// the Settings "Touch:" row retries on click (menu_action_touch_retry).
static bool touch_begin(void)
{
    gpio_config_t rst_cfg = {
        .pin_bit_mask = 1ULL << TOUCH_RST_PIN,
        .mode         = GPIO_MODE_OUTPUT,
    };
    gpio_config(&rst_cfg);

    i2c_master_bus_config_t bus_cfg = {
        .i2c_port   = I2C_NUM_0,
        .sda_io_num = TOUCH_I2C_SDA,
        .scl_io_num = TOUCH_I2C_SCL,
        .clk_source = I2C_CLK_SRC_DEFAULT,
        .glitch_ignore_cnt = 7,
        .flags.enable_internal_pullup = true,
    };
    if (i2c_new_master_bus(&bus_cfg, &s_touch_bus) != ESP_OK) {
        ESP_LOGE(TAG, "touch: I2C bus init failed");
        snprintf(s_touch_status, sizeof(s_touch_status), "Touch: I2C bus init failed");
        s_touch_bus = NULL;
        return false;
    }
    return touch_probe(true);
}

// If the GT911 reports nothing new for this long while we think a finger
// is down, treat it as released, so a missed "0 points" report can't leave
// the touch stuck on.
#define TOUCH_STALE_MS 150

// Polls the GT911 for a touch. x/y are scaled from the panel's own
// resolution, clamped to the screen, and mirrored per TOUCH_FLIP_X/Y (the
// old prototype's 180° ROTATION_INVERTED turned out backwards on this
// panel — the player walked the wrong way).
//
// The GT911 only raises "new data ready" at its own report rate, so plenty
// of polls land between two reports. Those polls must repeat the LAST known
// state, not report "released". Otherwise a held finger flickers
// down/up/down, every flicker counts as a fresh tap, and the corner button
// toggles the menu over and over.
static void touch_read(bool *touched, int *x, int *y)
{
    static bool     s_down = false;
    static int      s_x = 0, s_y = 0;
    static uint32_t s_last_report_ms = 0;
    static uint32_t s_next_retry_ms = TOUCH_RETRY_MS;
    static int      s_retries_left = TOUCH_RETRY_COUNT;

    *touched = false;
    *x = s_x;
    *y = s_y;
    uint32_t now = (uint32_t)(esp_timer_get_time() / 1000);
#if DEV_LINK_ENABLED
    if (dev_touch(touched, x, y)) return;   // a tap sent over USB (DEV LINK) stands in for a finger
#endif
    if (!s_touch_ok) {
        if (s_touch_bus && s_retries_left > 0 && (int32_t)(now - s_next_retry_ms) >= 0) {
            s_retries_left--;
            ESP_LOGI(TAG, "touch: retrying (%d left)", s_retries_left);
            touch_probe(false);
            s_next_retry_ms = (uint32_t)(esp_timer_get_time() / 1000) + TOUCH_RETRY_MS;
        }
        return;
    }

    uint8_t status = 0;
    if (gt911_read_reg(0x814E, &status, 1) == ESP_OK && (status & 0x80)) { // top bit = "new data ready"
        uint8_t n_points = status & 0x0F;
        if (n_points > 0 && n_points <= 5) {
            // Point 1 starts at 0x814F: [track id][x lo][x hi][y lo][y hi][size lo][size hi]
            uint8_t pt[7];
            if (gt911_read_reg(0x814F, pt, sizeof(pt)) == ESP_OK) {
                int raw_x = (pt[1] | (pt[2] << 8)) * LCD_H_RES / s_touch_max_x;
                int raw_y = (pt[3] | (pt[4] << 8)) * LCD_V_RES / s_touch_max_y;
                s_x = TOUCH_FLIP_X ? (LCD_H_RES - 1) - raw_x : raw_x;
                s_y = TOUCH_FLIP_Y ? (LCD_V_RES - 1) - raw_y : raw_y;
                if (s_x < 0) s_x = 0; else if (s_x >= LCD_H_RES) s_x = LCD_H_RES - 1;
                if (s_y < 0) s_y = 0; else if (s_y >= LCD_V_RES) s_y = LCD_V_RES - 1;
                if (!s_down) {
                    s_touch_taps++;
                    touch_update_status();
                    ESP_LOGD(TAG, "touch: down at %d,%d", s_x, s_y);
                }
                s_down = true;
            }
        } else {
            s_down = false;   // a fresh report with 0 points = finger lifted
        }
        s_last_report_ms = now;
        gt911_write_reg(0x814E, 0x00); // must clear this so the next poll gets fresh data
    } else if (s_down && (uint32_t)(now - s_last_report_ms) > TOUCH_STALE_MS) {
        s_down = false;
    }

    *touched = s_down;
    *x = s_x;
    *y = s_y;
}

// ============================================================
//  INPUT SYSTEM — one place (input_poll) that reads the touch panel every
//  frame into a per-frame struct. In the game a tap walks the player to
//  the tapped spot (touch_tap -> TAP-TO-WALK) and a held finger keeps
//  steering (touch_hold); menus hit-test the touch fields. Add future
//  input sources here, not in the callers.
//
//  input_poll() must be called exactly ONCE per frame: touch_read()
//  clears the GT911's "new data" flag as it reads, so a second call in
//  the same frame would just see "nothing new" and look untouched.
// ============================================================
#define TOUCH_BTN_SIZE    40                       // corner button = inventory open/close
#define TOUCH_BTN_X       (LCD_H_RES - TOUCH_BTN_SIZE - 4)
#define TOUCH_BTN_Y       4

typedef struct {
    bool touch_active;
    bool touch_pressed_edge;     // true only on the first frame of a new touch-down
    bool touch_menu_btn;         // this frame's fresh touch-down was on the corner button
    bool touch_tap;              // this frame's fresh touch-down was on the game (walk there)
    bool touch_hold;             // a finger that went down on the game is still down (the walk follows it)
    int  touch_x, touch_y;
    int  hotbar_slot;            // hotbar slot under a finger that went down on the hotbar, or -1
                                 // (tap or drag along the bar)
} input_frame_t;

// Call once per frame from update_input(). See the header comment above
// for why this must not be called more than once per frame.
static input_frame_t input_poll(void)
{
#if DEV_LINK_ENABLED
    dev_main_poll();   // commands sent over USB that touch the game run here, between frames (DEV LINK)
#endif
    input_frame_t f = {0};
    f.hotbar_slot = -1;

    static bool s_touch_prev      = false;
    static bool s_touch_on_hotbar = false;   // this touch went down on the hotbar
    static bool s_touch_on_btn    = false;   // this touch went down on the corner button
    bool touched = false;
    int  tx = 0, ty = 0;
    touch_read(&touched, &tx, &ty);

    f.touch_active       = touched;
    f.touch_pressed_edge = touched && !s_touch_prev;
    f.touch_x = tx;
    f.touch_y = ty;

    if (touched) {
        int hotbar_slot = hotbar_slot_at(tx, ty);
        if (f.touch_pressed_edge) {
            s_touch_on_hotbar = (hotbar_slot >= 0);
            s_touch_on_btn    = (tx >= TOUCH_BTN_X && tx < TOUCH_BTN_X + TOUCH_BTN_SIZE &&
                                 ty >= TOUCH_BTN_Y && ty < TOUCH_BTN_Y + TOUCH_BTN_SIZE);
        }
        if (s_touch_on_btn) {
            f.touch_menu_btn = f.touch_pressed_edge; // one-shot, like a fresh button press
        } else if (s_touch_on_hotbar) {
            // A touch that starts on the hotbar picks slots instead of walking —
            // tap one, or slide along the bar to scroll. Sliding off the bar
            // just does nothing.
            f.hotbar_slot = hotbar_slot;
        } else {
            f.touch_tap  = f.touch_pressed_edge;     // tap on the game: walk there (see TAP-TO-WALK)
            f.touch_hold = !f.touch_pressed_edge;    // ...and keep following the finger while it's held
        }
    }
    s_touch_prev = touched;
    return f;
}


// Draws the "open inventory" tap target (top-right corner): a small
// satchel-brown button with a 2x2 slot grid on it. Always on screen — touch
// works at all times. Opaque, so redrawing it is always safe — ui_overlays_redraw_if_overlap()
// puts it back whenever the player or an animation paints over it.
#define TOUCH_BTN_RADIUS 7
static void draw_touch_menu_button_at(int bx, int by)
{
    fill_round_rect(bx, by, TOUCH_BTN_SIZE, TOUCH_BTN_SIZE, TOUCH_BTN_RADIUS, INV_COL_PANEL, 255);
    draw_round_rect(bx, by, TOUCH_BTN_SIZE, TOUCH_BTN_SIZE, TOUCH_BTN_RADIUS, 2, INV_COL_EDGE);
    const int cell = 9, gap = 3, off = (TOUCH_BTN_SIZE - (2 * cell + gap)) / 2;
    for (int r = 0; r < 2; r++) {
        for (int c = 0; c < 2; c++) {
            int x = bx + off + c * (cell + gap), y = by + off + r * (cell + gap);
            fill_rect(x, y, cell, cell, INV_COL_SLOT);
            draw_rect(x, y, cell, cell, INV_COL_EDGE);
        }
    }
}

static void draw_touch_menu_button(void)
{
    draw_touch_menu_button_at(TOUCH_BTN_X, TOUCH_BTN_Y);
}

// The button back inside `clip` after a repaint under it: copied from an
// image of it drawn once (it never changes) instead of drawn again.
static uint16_t *s_btn_img = NULL;
static uint8_t   s_btn_row_inset[TOUCH_BTN_SIZE];
static void draw_touch_menu_button_in(rect_t clip)
{
    if (!s_btn_img) {
        s_btn_img = heap_caps_malloc((size_t)TOUCH_BTN_SIZE * TOUCH_BTN_SIZE * sizeof(uint16_t), MALLOC_CAP_SPIRAM);
        if (!s_btn_img) { draw_touch_menu_button(); return; }
        uint16_t *prev_fb = s_fb;
        int       prev_w  = s_fb_w, prev_h = s_fb_h;
        s_fb = s_btn_img; s_fb_w = TOUCH_BTN_SIZE; s_fb_h = TOUCH_BTN_SIZE;
        draw_touch_menu_button_at(0, 0);
        s_fb = prev_fb; s_fb_w = prev_w; s_fb_h = prev_h;
        for (int y = 0; y < TOUCH_BTN_SIZE; y++) {
            int in = 0;
            while (in < TOUCH_BTN_SIZE / 2 && !in_round_rect(in, y, 0, 0, TOUCH_BTN_SIZE, TOUCH_BTN_SIZE, TOUCH_BTN_RADIUS)) in++;
            s_btn_row_inset[y] = (uint8_t)in;
        }
    }
    overlay_blit(s_btn_img, TOUCH_BTN_X, TOUCH_BTN_Y, TOUCH_BTN_SIZE, TOUCH_BTN_SIZE, s_btn_row_inset, clip);
}

// The message toast (MESSAGES section further down) is the third overlay:
// while it's on the game screen it sits at s_msg_rect.
static bool   s_msg_on_screen = false;
static rect_t s_msg_rect;

// The time-of-day panel (CLOCK section further down) is the fourth: fixed in
// the top-left corner, just left of where a top-edge hotbar sits.
#define CLOCK_X 4
#define CLOCK_Y 4
#define CLOCK_W 108   // ends at x = 112 = HOTBAR_X
#define CLOCK_H 50
static bool s_clock_on_screen = false;

static bool ui_overlay_covers(int px, int py)
{
    if (px >= HOTBAR_X && px < HOTBAR_X + HOTBAR_W && py >= s_hotbar_y && py < s_hotbar_y + HOTBAR_H) return true;
    if (s_msg_on_screen && px >= s_msg_rect.x && px < s_msg_rect.x + s_msg_rect.w &&
        py >= s_msg_rect.y && py < s_msg_rect.y + s_msg_rect.h) return true;
    if (s_clock_on_screen && px >= CLOCK_X && px < CLOCK_X + CLOCK_W && py >= CLOCK_Y && py < CLOCK_Y + CLOCK_H) return true;
    return px >= TOUCH_BTN_X && px < TOUCH_BTN_X + TOUCH_BTN_SIZE &&
           py >= TOUCH_BTN_Y && py < TOUCH_BTN_Y + TOUCH_BTN_SIZE;
}

static void hud_draw_overlay(void);   // the hotbar — defined in the HUD section further down

// The hotbar, the touch button and a message sit on top of the game world.
// Anything that paints the world (player, animations, breakables) calls this
// with the rect it just painted, so the overlays never get a sprite-shaped
// hole in them.
// Each is put back only inside that rect (the rest of it is still on
// screen), unless its image had to be made again — then all of it.
static void hud_draw_overlay_in(rect_t clip);     // HUD section
static void clock_draw_overlay_in(rect_t clip);   // CLOCK section
static void msg_draw_overlay_in(rect_t clip);     // MESSAGES section
static void ui_overlays_redraw_if_overlap(int x, int y, int w, int h)
{
    rect_t clip = { x, y, w, h };
    if (x < HOTBAR_X + HOTBAR_W && HOTBAR_X < x + w && y < s_hotbar_y + HOTBAR_H && s_hotbar_y < y + h) {
        PROF(PROF_HOTBAR, hud_draw_overlay_in(clip));
    }
    if (x < TOUCH_BTN_X + TOUCH_BTN_SIZE && TOUCH_BTN_X < x + w &&
        y < TOUCH_BTN_Y + TOUCH_BTN_SIZE && TOUCH_BTN_Y < y + h) {
        PROF(PROF_BTN, draw_touch_menu_button_in(clip));
    }
    if (s_clock_on_screen && x < CLOCK_X + CLOCK_W && CLOCK_X < x + w && y < CLOCK_Y + CLOCK_H && CLOCK_Y < y + h) {
        PROF(PROF_CLOCK, clock_draw_overlay_in(clip));
    }
    if (s_msg_on_screen && x < s_msg_rect.x + s_msg_rect.w && s_msg_rect.x < x + w &&
        y < s_msg_rect.y + s_msg_rect.h && s_msg_rect.y < y + h) {
        PROF(PROF_MSG, msg_draw_overlay_in(clip));
    }
}

// ============================================================
//  PLAYER — walked by tap-to-walk (TAP-TO-WALK section).
// ============================================================
#define PLAYER_W       16   // matches TILE_SIZE, so no side-to-side tile overlap
#define PLAYER_H       32   // 2 tiles tall (torso/head overhang above the feet tile)
#define PLAYER_MIN_Y   (TILE_SIZE - PLAYER_H)   // feet on the top tile row: the head goes off the top of the screen
#define PLAYER_SPEED_Q 12   // speed in QUARTER pixels/tick (12 = 3 px, about 125 px/s) — positions are
                             // whole pixels, so a speed that isn't a multiple of 4 alternates step sizes.
                             // Keep it >= 4: a tick with no step would flash the idle pose.
// Walking goes by the clock, not by frames: a busy frame (rain, lots of
// shoppers) moves things further, so the speed on screen stays the same.
// Each game frame, game_ticks_update() counts how many GAME_TICK_US went by
// (0 on a quick frame, more on a slow one) into s_game_ticks; the player and
// the shoppers move that many steps. GAME_TICK_US is a normal frame's length
// (dev link "state" shows frame_us, the average), so the speeds above are as before.
#define GAME_TICK_US       24000
#define GAME_TICKS_MAX     4        // at most this many in one frame (a hitch isn't a teleport)
static int     s_game_ticks    = 1;
static int32_t s_frame_us_avg  = GAME_TICK_US;

static void game_ticks_update(void)
{
    static int64_t last = 0, acc = 0;
    int64_t now = esp_timer_get_time();
    int64_t dt  = last ? now - last : GAME_TICK_US;
    last = now;
    if (dt > 150000) dt = GAME_TICK_US;   // back from a menu or a map load: one ordinary frame
    s_frame_us_avg += (int32_t)((dt - s_frame_us_avg) / 16);
    acc += dt;
    int t = (int)(acc / GAME_TICK_US);
    acc -= (int64_t)t * GAME_TICK_US;
    if (t > GAME_TICKS_MAX) { t = GAME_TICKS_MAX; acc = 0; }
    s_game_ticks = t;
}

#define PLAYER_FEET_H  6    // only this many px at the bottom of the sprite collide,
                             // so the taller sprite can visually overlap obstacles
                             // above it (trees, walls) while still blocking at the feet

// Animation timing: advance one frame every PLAYER_ANIM_TICKS calls to
// update_player() *while actually moving* — stands still on frame 0 when not.
#define PLAYER_ANIM_FRAMES 4
#define PLAYER_ANIM_TICKS  7    // ~21 px of walking per frame; scale with PLAYER_SPEED_Q so the feet don't slide

typedef enum { PDIR_DOWN = 0, PDIR_UP, PDIR_LEFT, PDIR_RIGHT, PDIR_COUNT } player_dir_t;

static int  s_player_x = LCD_H_RES / 2;
static int  s_player_y = LCD_V_RES / 2;
static direction_t s_player_facing = DIR_DOWN; // last direction walked (or turned to face what was tapped)
static int  s_player_anim_frame   = 0;
static int  s_player_anim_counter = 0;

// SPRITE REGISTRY — [direction][frame] -> PLAYER_W*PLAYER_H RGB565 pixels,
// row-major (same layout draw_image() expects), pointing straight at the
// converted sprites in flash. Direction order must match player_dir_t
// above: 0=down, 1=up, 2=left, 3=right. Filled by build_player_frames().
static const uint16_t  s_player_placeholder[PLAYER_W * PLAYER_H] =           // a near-black box until art exists
    { [0 ... PLAYER_W * PLAYER_H - 1] = 0x0841 };                            // (not 0x0000, which is transparent)
static const uint16_t *s_player_frames[PDIR_COUNT][PLAYER_ANIM_FRAMES];       // empty-handed
static const uint16_t *s_player_held_frames[PDIR_COUNT][PLAYER_ANIM_FRAMES];  // holding an item

// Maps a direction (including diagonals) to one of the 4
// animation rows above — diagonals just pick their vertical component.
static player_dir_t player_dir_from_facing(direction_t dir)
{
    switch (dir) {
        case DIR_UP: case DIR_UP_LEFT: case DIR_UP_RIGHT:     return PDIR_UP;
        case DIR_LEFT:                                        return PDIR_LEFT;
        case DIR_RIGHT:                                       return PDIR_RIGHT;
        case DIR_DOWN: case DIR_DOWN_LEFT: case DIR_DOWN_RIGHT:
        default:                                              return PDIR_DOWN;
    }
}

// A converted sprite by PNG file name (see tools/png_to_rgb565.py), or NULL.
static const sprite_asset_t *sprite_asset_find(const char *name)
{
    for (const sprite_asset_t *s = k_sprite_assets; s->name; s++) {
        if (strcmp(s->name, name) == 0) return s;
    }
    return NULL;
}

// ---- Characters -----------------------------------------------------------
//  Every folder in assets/characters/ is one playable character, named
//  after the folder, holding its 16x32 PNGs:
//    char_<dir>_<frame>.png        e.g. char_up_1.png       (empty-handed)
//    char_held_<dir>_<frame>.png   e.g. char_held_up_1.png  (holding an item)
//  with <dir> = down/up/left/right and <frame> = 1..4 (1 = idle pose).
//  Add a folder and rebuild — it shows up in the title screen's Customize,
//  where the player picks one (kept in NVS, see character_load_choice()).
//  A missing empty-handed frame is a black box; a missing held frame falls
//  back to the matching empty-handed one. Pure black (0x0000) and
//  transparent PNG pixels are both see-through.
static int s_character = 0;   // k_character_assets index being played

static int character_count(void)
{
    int n = 0;
    while (k_character_assets[n].name) n++;
    return n;
}

static const char *character_name(int ci)
{
    return (ci >= 0 && ci < character_count()) ? k_character_assets[ci].name : "none";
}

// Character ci's frame by PNG name, if it's PLAYER_W x PLAYER_H; else a
// top-level assets/ sprite of that name (older projects kept them there).
static const uint16_t *character_sprite(int ci, const char *name)
{
    const sprite_asset_t *s = NULL;
    if (ci >= 0 && ci < character_count())
        for (const sprite_asset_t *c = k_character_assets[ci].frames; c->name && !s; c++)
            if (strcmp(c->name, name) == 0) s = c;
    if (!s) s = sprite_asset_find(name);
    if (!s) return NULL;
    if (s->w != PLAYER_W || s->h != PLAYER_H) {
        ESP_LOGE(TAG, "character %s: %s is %dx%d, must be %dx%d - ignored", character_name(ci), name,
                 (int)s->w, (int)s->h, PLAYER_W, PLAYER_H);
        return NULL;
    }
    return s->pixels;
}

// One walking (held = false) or holding frame of character ci, never NULL.
static const uint16_t *character_frame(int ci, bool held, player_dir_t d, int f)
{
    static const char *const dir_names[PDIR_COUNT] = { "down", "up", "left", "right" };
    char name[32];
    const uint16_t *px = NULL;
    if (held) {
        snprintf(name, sizeof(name), "char_held_%s_%d", dir_names[d], f + 1);
        px = character_sprite(ci, name);
    }
    if (!px) {
        snprintf(name, sizeof(name), "char_%s_%d", dir_names[d], f + 1);
        px = character_sprite(ci, name);
    }
    return px ? px : s_player_placeholder;
}

// Hooks the player's animation up to character s_character's frames.
static void build_player_frames(void)
{
    for (int d = 0; d < PDIR_COUNT; d++) {
        for (int f = 0; f < PLAYER_ANIM_FRAMES; f++) {
            s_player_frames[d][f]      = character_frame(s_character, false, (player_dir_t)d, f);
            s_player_held_frames[d][f] = character_frame(s_character, true, (player_dir_t)d, f);
        }
    }
}

// ============================================================
//  PLAYER ANIMATION OVERRIDE — player_play_anim("char_wave", 120, 1)
//  shows char_wave_1.png, char_wave_2.png, ... (as many as exist, up to
//  PLAYER_ANIM_OVERRIDE_FRAMES) INSTEAD of the normal walk/idle frames
//  and the held item. The player can still move while it plays.
//   - Frames all share one size, each side 16 or 32 px: 16x16, 16x32,
//     32x16 or 32x32. Drawn centred on the player and standing on the
//     same feet line; 0x0000 / transparent pixels are see-through.
//   - interval_ms: how long each frame stays up.
//   - plays: times to run through the frames before the normal animation
//     comes back; 0 = loop until player_stop_anim().
//  Starting one while another plays replaces it. Returns false (and
//  changes nothing) if the frames are missing or the wrong size.
// ============================================================
#define PLAYER_ANIM_MAX             32   // largest override frame side, px (sides must be multiples of 16)
#define PLAYER_ANIM_OVERRIDE_FRAMES 16

static const uint16_t *s_pa_frames[PLAYER_ANIM_OVERRIDE_FRAMES];
static frame_bundle_t  s_pa;          // size + timing (pixels unused: the frames are separate PNGs)
static uint32_t        s_pa_plays;    // 0 = loop until stopped
static uint32_t        s_pa_start;
static bool            s_pa_on = false;

static bool player_anim_side_ok(int v) { return v > 0 && v <= PLAYER_ANIM_MAX && v % 16 == 0; }

bool player_play_anim(const char *name, int interval_ms, int plays)
{
    const uint16_t *frames[PLAYER_ANIM_OVERRIDE_FRAMES];
    char frame_name[48];
    int  n = 0, w = 0, h = 0;
    while (n < PLAYER_ANIM_OVERRIDE_FRAMES) {
        snprintf(frame_name, sizeof(frame_name), "%s_%d", name, n + 1);
        const sprite_asset_t *s = sprite_asset_find(frame_name);
        if (!s) break;
        if (n == 0) { w = s->w; h = s->h; }
        if (s->w != w || s->h != h || !player_anim_side_ok(w) || !player_anim_side_ok(h)) {
            ESP_LOGE(TAG, "player anim: %s is %dx%d - frames must all match, each side 16 or 32", frame_name, (int)s->w, (int)s->h);
            return false;
        }
        frames[n++] = s->pixels;
    }
    if (n == 0) {
        ESP_LOGE(TAG, "player anim: no %s_1.png", name);
        return false;
    }
    memcpy(s_pa_frames, frames, (size_t)n * sizeof(frames[0]));
    s_pa = (frame_bundle_t){ .w = w, .h = h, .frame_count = n, .interval_ms = interval_ms > 0 ? interval_ms : 1 };
    s_pa_plays = plays > 0 ? (uint32_t)plays : 0;
    s_pa_start = (uint32_t)(esp_timer_get_time() / 1000);
    s_pa_on    = true;
    return true;
}

// Back to the normal animation now (the next update_player() redraws).
void player_stop_anim(void)
{
    s_pa_on = false;
}

bool player_anim_playing(void)
{
    return s_pa_on;
}

// The override frame to show at `now`, or NULL for the normal animation
// (none playing, or it just ran out of plays).
static const uint16_t *player_anim_frame_now(uint32_t now)
{
    if (!s_pa_on) return NULL;
    uint32_t elapsed = now - s_pa_start;
    if (s_pa_plays == 0) return s_pa_frames[bundle_frame_looping(&s_pa, elapsed)];
    bool finished;
    uint16_t f = bundle_frame_passes(&s_pa, elapsed, s_pa_plays, &finished);
    if (finished) {
        s_pa_on = false;
        return NULL;
    }
    return s_pa_frames[f];
}

// ============================================================
//  MUTATIONS — anything the player gets (caught, harvested, a breakable's
//  drop) can come out mutated (items.h MUT_*; odds and prices in items.c):
//  mut_roll() picks one as it's got, and it rides in the high bits of the
//  stack's quality byte from then on. It changes the look: mut_px()
//  recolours the item's art — the same in the bag, on the catch card and in
//  the player's hands, where it's animated through the held-item look
//  (player_look_t.mfx, mut_frame(): a new frame = a redraw, just like the
//  item's own passive frames): Shiny and Golden glints run across it,
//  Radioactive pulses green, Electric crackles, Ghostly flickers, Rainbow
//  scrolls, Celestial twinkles. Two change how it's held: Heavy squashes
//  the player (MUT_SQUASH_PX), Floaty bobs over their head (MUT_FLOAT_*).
// ============================================================
#define MUT_SQUASH_PX  4      // Heavy: the most the player is pressed down (and widened by)
#define MUT_FLOAT_LIFT 6      // Floaty: how much higher than normal it's held...
#define MUT_FLOAT_BOB  3      // ...how far it drifts up and down from there...
#define MUT_FLOAT_MS   1800   // ...and how long one drift up and down takes
#define MUT_STILL      0xFF   // mut_px() frame for a picture that doesn't move (the bag)

// Each mutation's colour: its badge on a slot, its chip and its name.
static const uint16_t k_mut_col[MUT_COUNT] = {
    [MUT_SHINY]       = COLOR_RGB565(255, 250, 190),
    [MUT_FLOATY]      = COLOR_RGB565(200, 236, 255),
    [MUT_ALBINO]      = COLOR_RGB565(255, 214, 226),
    [MUT_HEAVY]       = COLOR_RGB565(140, 146, 160),
    [MUT_GOLDEN]      = COLOR_RGB565(255, 196,  40),
    [MUT_RADIOACTIVE] = COLOR_RGB565(120, 255,  60),
    [MUT_ELECTRIC]    = COLOR_RGB565(255, 236,  70),
    [MUT_GHOSTLY]     = COLOR_RGB565(150, 236, 255),
    [MUT_RAINBOW]     = COLOR_RGB565(255, 110, 200),
    [MUT_CELESTIAL]   = COLOR_RGB565(170, 120, 255),
};

// RGB 0..255 to RGB565, clamped (COLOR_RGB565 is for constants: it doesn't clamp).
static uint16_t rgb565_clamp(int r, int g, int b)
{
    r = r < 0 ? 0 : r > 255 ? 255 : r;
    g = g < 0 ? 0 : g > 255 ? 255 : g;
    b = b < 0 ? 0 : b > 255 ? 255 : b;
    return (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

// A mutation for `item`, just got (MUT_NONE most of the time). `boost`
// (1 = normal) multiplies the item's "mut" — fishing's bonuses. Each one is
// tried rarest first, at its base odds x mult^(1 + 0.06 a step rarer), so a
// big multiplier helps the rare ones most.
static uint8_t mut_roll(uint8_t item, float boost)
{
    if (item == ITEM_NONE || !item_get(item)) return MUT_NONE;
    float m = (float)item_attr(item, ITEM_ATTR_MUT, 100) / 100.0f * boost;
    if (m <= 0.0f) return MUT_NONE;
    if (m > 50.0f) m = 50.0f;
    for (int k = MUT_COUNT - 1; k > MUT_NONE; k--) {
        float p = powf(m, 1.0f + 0.06f * (k - 1)) / item_mutation_one_in((uint8_t)k);
        if (p > 0.9f) p = 0.9f;
        if ((float)(esp_random() & 0xFFFFFF) / 16777216.0f < p) return (uint8_t)k;
    }
    return MUT_NONE;
}

// A held mutated item's animation frame `ms` after it was taken in hand (0 = one that doesn't move).
static uint8_t mut_frame(uint8_t mut, uint32_t ms)
{
    switch (mut) {
    case MUT_SHINY:       return (uint8_t)((ms / 90) % 28);    // a glint across, then a rest
    case MUT_GOLDEN:      return (uint8_t)((ms / 110) % 30);
    case MUT_RADIOACTIVE: return (uint8_t)((ms / 140) % 8);    // a pulse
    case MUT_ELECTRIC:    return (uint8_t)((ms / 70) % 16);    // sparks
    case MUT_GHOSTLY:     return (uint8_t)((ms / 280) % 2);    // flicker
    case MUT_RAINBOW:     return (uint8_t)((ms / 140) % 6);    // the stripes scroll
    case MUT_CELESTIAL:   return (uint8_t)((ms / 240) % 4);    // twinkle
    default:              return 0;
    }
}

// Art pixel (x,y) of a w x h frame, as mutation `mut` shows it at animation
// frame f (MUT_STILL: a still picture). FB_TRANSPARENT_COLOR = leave it out.
static uint16_t mut_px(uint8_t mut, const uint16_t *px, int w, int h, int x, int y, uint8_t f)
{
    uint16_t c = px[y * w + x];
    if (c == FB_TRANSPARENT_COLOR || !mut || mut >= MUT_COUNT) return c;
    const uint16_t T = FB_TRANSPARENT_COLOR;
    bool edge = x == 0 || y == 0 || x == w - 1 || y == h - 1 ||   // next to see-through: the outline
                px[y * w + x - 1] == T || px[y * w + x + 1] == T || px[(y - 1) * w + x] == T || px[(y + 1) * w + x] == T;
    int r = ((c >> 11) & 0x1F) * 255 / 31, g = ((c >> 5) & 0x3F) * 255 / 63, b = (c & 0x1F) * 255 / 31;
    int l = (r * 77 + g * 151 + b * 28) >> 8;   // brightness
    bool glint = f != MUT_STILL && (x + y) / 2 == f;
    switch (mut) {
    case MUT_SHINY:   // brighter, a few sparkles, a glint running across
        if (glint || (((x * 7 + y * 13) % 29) == 0 && l > 60)) return COLOR_WHITE;
        return rgb565_clamp(r + 40, g + 40, b + 30);
    case MUT_FLOATY:   // pale and airy
        return rgb565_clamp(r / 2 + 118, g / 2 + 126, b / 2 + 132);
    case MUT_ALBINO:   // almost white, a little pink; the darkest bits (eyes, outline) go red
        if (l < 50) return rgb565_clamp(120 + l, 40 + l / 2, 60 + l / 2);
        return rgb565_clamp(190 + l / 4, 172 + l / 4, 176 + l / 4);
    case MUT_HEAVY:   // dark iron, a darker outline
        if (edge) return rgb565_clamp(22 + l / 8, 22 + l / 8, 28 + l / 8);
        return rgb565_clamp(l * 45 / 100 + 30, l * 45 / 100 + 32, l / 2 + 40);
    case MUT_GOLDEN:
        if (glint) return COLOR_RGB565(255, 250, 210);
        return rgb565_clamp(110 + l * 3 / 4, 40 + l * 3 / 4, l / 4);
    case MUT_RADIOACTIVE: {   // green, glowing in pulses — the outline brightest
        int p = f == MUT_STILL ? 3 : f < 4 ? f + 1 : 8 - f;   // 1..4..1
        if (edge && p >= 3) return rgb565_clamp(150 + p * 20, 255, 70 + p * 10);
        return rgb565_clamp(l / 5 + p * 6, l * 3 / 4 + 40 + p * 14, l / 6 + p * 4);
    }
    case MUT_ELECTRIC: {   // blue, with yellow sparks jumping about and flashes along the outline
        uint32_t s = ((uint32_t)x * 73856093u ^ (uint32_t)y * 19349663u ^ (uint32_t)f * 83492791u) % 17u;
        if (s == 0) return COLOR_RGB565(255, 240, 80);
        if (edge && f != MUT_STILL && (f & 3) == 0) return COLOR_WHITE;
        return rgb565_clamp(l / 3 + 30, l / 2 + 70, 200 + l / 5);
    }
    case MUT_GHOSTLY:   // see-through blue: every other pixel inside is gone, and which ones flickers
        if (!edge && ((x + y + (f == MUT_STILL ? 0 : f)) & 1)) return T;
        return rgb565_clamp(l / 2 + 70, l * 3 / 4 + 80, 255);
    case MUT_RAINBOW: {   // stripes of colour, scrolling
        static const uint8_t k_hue[6][3] = { { 255, 60, 60 }, { 255, 170, 40 }, { 250, 240, 70 }, { 70, 220, 90 }, { 60, 150, 255 }, { 180, 90, 255 } };
        const uint8_t *hu = k_hue[((x + y) / 3 + 6 - (f == MUT_STILL ? 0 : f % 6)) % 6];
        return rgb565_clamp(hu[0] * (l + 60) / 255, hu[1] * (l + 60) / 255, hu[2] * (l + 60) / 255);
    }
    case MUT_CELESTIAL:   // the night sky, with stars that twinkle
        if (((x * 31 + y * 17) % 19) == 0) return ((x + y + (f == MUT_STILL ? 0 : f)) % 4 == 0) ? COLOR_WHITE : COLOR_RGB565(200, 180, 255);
        return rgb565_clamp(30 + l / 3, 16 + l / 5, 80 + l * 2 / 3);
    default:
        return c;
    }
}

// A fish's tier (items.h "fish_tier"; FISHING): its name and colour — on the
// catch card, the bite "!", the fish in the minigame, the bag's card.
enum { FISH_TIER_COMMON, FISH_TIER_UNCOMMON, FISH_TIER_RARE, FISH_TIER_EPIC, FISH_TIER_LEGENDARY, FISH_TIER_MYTHIC, FISH_TIER_COUNT };
static const struct { const char *name; uint16_t col; } k_fish_tier[FISH_TIER_COUNT] = {
    { "Common",    COLOR_RGB565(230, 230, 220) },
    { "Uncommon",  COLOR_RGB565(110, 220,  90) },
    { "Rare",      COLOR_RGB565( 80, 160, 255) },
    { "Epic",      COLOR_RGB565(190,  90, 255) },
    { "Legendary", COLOR_RGB565(255, 196,  40) },
    { "Mythic",    COLOR_RGB565(255,  70,  90) },
};
static int fish_tier_of(uint8_t item)
{
    int t = (int)item_attr(item, ITEM_ATTR_FISH_TIER, 1) - 1;
    return t < 0 ? 0 : t >= FISH_TIER_COUNT ? FISH_TIER_COUNT - 1 : t;
}

// ---- WET ITEMS — anything got while it rains (rain_now(): out in it, not
// indoors) comes with QUALITY_WET: a breakable's drop, a harvest, a catch, a
// pickup off the ground, a purchase. It only looks different: a little darker
// and bluer with a sheen (item_px(), everywhere it's drawn), a drop badge on
// its slot, and while held, water dripping off it (player_look_t.drip, the
// held-item animation like a mutation's). The price never changes.
#define WET_DRIP_PX     12   // how far a drop falls below the held item before it's gone
#define WET_DRIP_MS     70   // one frame of the drip animation...
#define WET_DRIP_FRAMES 24   // ...and a drop's whole life: it swells, hangs, falls, then a pause

static uint8_t wet_if_raining(uint8_t quality) { return rain_now() ? (uint8_t)(quality | QUALITY_WET) : quality; }

// mut_px(), then wet: art pixel (x,y) as a stack with this quality byte shows it.
static uint16_t item_px(uint8_t quality, const uint16_t *px, int w, int h, int x, int y, uint8_t f)
{
    uint16_t c = mut_px(QUALITY_MUT(quality), px, w, h, x, y, f);
    if (c == FB_TRANSPARENT_COLOR || !QUALITY_IS_WET(quality)) return c;
    int r = ((c >> 11) & 0x1F) * 255 / 31, g = ((c >> 5) & 0x3F) * 255 / 63, b = (c & 0x1F) * 255 / 31;
    int l = (r * 77 + g * 151 + b * 28) >> 8;
    if (l > 110 && ((x - y + 64) % 6) == 0) return rgb565_clamp(r / 2 + 120, g / 2 + 128, b / 2 + 128);   // a wet sheen
    return rgb565_clamp(r * 78 / 100, g * 84 / 100, b * 90 / 100 + 26);                              // soaked: darker, bluer
}

// "Wet Radioactive " (with the space), "Wet ", "Golden " or "" — what goes before the item's name.
static const char *quality_prefix(uint8_t quality, char *buf, size_t n)
{
    uint8_t m = QUALITY_MUT(quality);
    snprintf(buf, n, "%s%s%s", QUALITY_IS_WET(quality) ? "Wet " : "", m && m < MUT_COUNT ? item_mutation_name(m) : "", m && m < MUT_COUNT ? " " : "");
    return buf;
}

// "Wet Golden Silver", "Golden", "Silver" or "" — a stack's wetness, mutation and grade, for messages.
static const char *quality_label(uint8_t quality, char *buf, size_t n)
{
    uint8_t g = QUALITY_GRADE(quality);
    const char *gn = g != QUALITY_STANDARD && g < QUALITY_COUNT ? item_quality_name(g) : "";
    char pre[24];
    quality_prefix(quality, pre, sizeof(pre));
    if (!*gn && *pre) pre[strlen(pre) - 1] = '\0';   // no grade after it: drop the trailing space
    snprintf(buf, n, "%s%s", pre, gn);
    return buf;
}

// ============================================================
//  HELD ITEM — the item in the player's hands floats just above their
//  head and moves with them. It has no collision (only the feet collide),
//  but it's layered like the player: foreground scenery and the hotbar
//  still cover it. Sprite + held item are drawn, cached and erased as one
//  unit (a "look"), so the item never leaves a trail.
// ============================================================
#define HELD_ITEM_MAX  32  // held-item art is shrunk to fit this...
#define HELD_GIANT_MAX 48  // ...or blown up to this for a "giant" item (LEGENDARY TRAITS) — these bound the background cache below
#define HELD_ITEM_GAP  1   // px between the top of the head and the item...
#define HELD_ITEM_DROP 4   // ...then moved this many px down (so it overlaps the head a little)

typedef struct {
    int             x, y;         // player top-left (the normal PLAYER_W x PLAYER_H box)
    const uint16_t *sprite;
    int             sw, sh;       // sprite size: PLAYER_W x PLAYER_H, or an override animation's frame size
    uint8_t         item;         // ITEM_NONE = empty-handed (or hidden by an override animation)
    uint16_t        item_frame;   // frame of the item's passive (held) animation
    uint8_t         item_q;       // the held stack's quality byte — its mutation (MUTATIONS) recolours it
    uint8_t         mfx;          // the mutation's animation frame (mut_frame())
    uint8_t         squash;       // Heavy: px the player is pressed down (and widened by)
    int8_t          lift;         // Floaty: px the item floats higher than normal
    uint8_t         drip;         // wet (QUALITY_WET): the dripping's frame (WET ITEMS)
    uint8_t         night;        // night stage it's darkened to (0 = day)
} player_look_t;

// Where a look's sprite goes: centred on the player, bottom on the feet
// line — the same spot as the normal sprite when it's PLAYER_W x PLAYER_H.
// Squashed (a Heavy item), it's that much shorter and wider.
static rect_t player_sprite_rect(const player_look_t *l)
{
    int w = l->sw + l->squash, h = l->sh - l->squash;
    return (rect_t){ l->x + (PLAYER_W - w) / 2, l->y + PLAYER_H - h, w, h };
}

static uint8_t  s_held_anim_item  = ITEM_NONE;   // the held animation restarts whenever this changes...
static uint8_t  s_held_anim_q     = 0;           // ...or this (another stack of it, mutated differently)
static uint32_t s_held_anim_start = 0;

// A "giant" item (LEGENDARY TRAITS) is held blown up: the visible part of its
// art (frame 0's non-transparent pixels — art often has empty margins) scaled
// to fill HELD_GIANT_MAX. That part, or w == 0 if the item isn't giant.
// Worked out once per item art (the last one asked about is kept).
static rect_t held_giant_box(uint8_t item)
{
    static const uint16_t *s_px = NULL;
    static rect_t          s_box;
    const item_asset_t *a = item_get(item);
    if (!a || !a->passive.frame_count || !a->passive.pixels || item_attr(item, ITEM_ATTR_GIANT, 0) <= 0) return (rect_t){ 0, 0, 0, 0 };
    if (a->passive.pixels == s_px) return s_box;
    int pw = a->passive.w, ph = a->passive.h, x0 = pw, y0 = ph, x1 = -1, y1 = -1;
    for (int y = 0; y < ph; y++)
        for (int x = 0; x < pw; x++)
            if (a->passive.pixels[y * pw + x] != FB_TRANSPARENT_COLOR) {
                if (x < x0) x0 = x;
                if (x > x1) x1 = x;
                if (y < y0) y0 = y;
                if (y > y1) y1 = y;
            }
    s_px  = a->passive.pixels;
    s_box = x1 < 0 ? (rect_t){ 0, 0, pw, ph } : (rect_t){ x0, y0, x1 - x0 + 1, y1 - y0 + 1 };
    return s_box;
}

static void held_item_size(uint8_t item, int *w, int *h)
{
    const item_asset_t *a = item_get(item);
    if (!a || a->passive.frame_count == 0) { *w = 16; *h = 16; return; }   // gray placeholder, as in draw_item_icon()
    rect_t g = held_giant_box(item);
    if (g.w) {   // giant: its longer side becomes HELD_GIANT_MAX
        int big = g.w > g.h ? g.w : g.h;
        *w = g.w * HELD_GIANT_MAX / big;
        *h = g.h * HELD_GIANT_MAX / big;
        if (*w < 1) *w = 1;
        if (*h < 1) *h = 1;
        return;
    }
    *w = a->passive.w;
    *h = a->passive.h;
    int big = *w > *h ? *w : *h;
    if (big > HELD_ITEM_MAX) {   // bigger art (a wide prop): shrunk to fit, whole
        *w = *w * HELD_ITEM_MAX / big; if (*w < 1) *w = 1;
        *h = *h * HELD_ITEM_MAX / big; if (*h < 1) *h = 1;
    }
}

// Top-left of the held item: centred over the head.
static void held_item_xy(const player_look_t *l, int iw, int ih, int *x, int *y)
{
    *x = l->x + (PLAYER_W - iw) / 2;
    *y = l->y - HELD_ITEM_GAP - ih + HELD_ITEM_DROP + l->squash - l->lift;   // down with a squashed head; up when floating
}

// What the player should look like this frame.
static player_look_t player_look_now(void)
{
    uint32_t      now = (uint32_t)(esp_timer_get_time() / 1000);
    player_look_t l   = { .x = s_player_x, .y = s_player_y, .night = (uint8_t)s_night_shown };

    // An override animation replaces the walk frame and hides the held item.
    const uint16_t *override = player_anim_frame_now(now);
    if (override) {
        l.sprite = override;
        l.sw     = s_pa.w;
        l.sh     = s_pa.h;
        l.item   = ITEM_NONE;
        return l;
    }

    l.item = inv_held_item();
    l.sw   = PLAYER_W;
    l.sh   = PLAYER_H;
    player_dir_t row = player_dir_from_facing(s_player_facing);
    l.sprite = (l.item != ITEM_NONE ? s_player_held_frames : s_player_frames)[row][s_player_anim_frame];
    if (l.item != ITEM_NONE) {
        l.item_q = s_inv[s_inv_held].quality;
        if (l.item != s_held_anim_item || l.item_q != s_held_anim_q) {
            s_held_anim_item  = l.item;
            s_held_anim_q     = l.item_q;
            s_held_anim_start = now;
        }
        uint32_t ms = now - s_held_anim_start;
        const item_asset_t *a = item_get(l.item);
        if (a) l.item_frame = bundle_frame_looping(&a->passive, ms);
        uint8_t mut = QUALITY_MUT(l.item_q);   // MUTATIONS: its own animation, and how it's held
        l.mfx = mut_frame(mut, ms);
        if (mut == MUT_HEAVY) {   // straining under it: pressed down, easing up a little, pressed down again
            static const uint8_t k_strain[6] = { 4, 4, 3, 2, 3, 4 };
            l.squash = (uint8_t)(k_strain[(ms / 200) % 6] * MUT_SQUASH_PX / 4);
        } else if (mut == MUT_FLOATY) {
            l.lift = (int8_t)(MUT_FLOAT_LIFT + lroundf(MUT_FLOAT_BOB * sinf((float)(ms % MUT_FLOAT_MS) * 6.2831853f / MUT_FLOAT_MS)));
        }
        if (QUALITY_IS_WET(l.item_q)) l.drip = (uint8_t)((ms / WET_DRIP_MS) % WET_DRIP_FRAMES);   // WET ITEMS
    }
    return l;
}

static bool player_look_equal(const player_look_t *a, const player_look_t *b)
{
    return a->x == b->x && a->y == b->y && a->sprite == b->sprite && a->sw == b->sw && a->sh == b->sh &&
           a->item == b->item && a->item_frame == b->item_frame && a->item_q == b->item_q && a->mfx == b->mfx &&
           a->squash == b->squash && a->lift == b->lift && a->drip == b->drip && a->night == b->night;
}

// Screen rect a look covers: the sprite plus the held item above it (and,
// wet, the drops falling off it — they land over the head, inside the sprite's rows).
static rect_t player_look_rect(const player_look_t *l)
{
    rect_t r = player_sprite_rect(l);
    if (l->item == ITEM_NONE) return r;
    int iw, ih, ix, iy;
    held_item_size(l->item, &iw, &ih);
    held_item_xy(l, iw, ih, &ix, &iy);
    return rect_union(r, (rect_t){ ix, iy, iw, ih + (QUALITY_IS_WET(l->item_q) ? WET_DRIP_PX + 2 : 0) });
}

// Wet (WET ITEMS): drops dripping off the held item drawn at (ix,iy), iw wide.
// bottom[col] = the item's lowest drawn row in that column (-1: none). A drop
// swells on the underside, hangs, falls WET_DRIP_PX and is gone; the lanes take turns.
static void wet_paint_drips(const player_look_t *l, int ix, int iy, int iw, const int8_t *bottom)
{
    const uint16_t body = COLOR_RGB565(140, 196, 255), shine = COLOR_RGB565(232, 246, 255);
    int lanes = iw >= 20 ? 3 : 2;
    for (int k = 0; k < lanes; k++) {
        int want = iw * (k + 1) / (lanes + 1), col = -1;
        for (int d = 0; d < iw && col < 0; d++) {   // the nearest column that has something to drip off
            if (want - d >= 0 && bottom[want - d] >= 0) col = want - d;
            else if (want + d < iw && bottom[want + d] >= 0) col = want + d;
        }
        if (col < 0) continue;
        int ph = (l->drip + k * 9) % WET_DRIP_FRAMES, x = ix + col, y = iy + bottom[col] + 1, len;
        if (ph < 5)       len = 1;                                            // swelling
        else if (ph < 10) len = 2;                                            // hanging
        else if (ph < 16) { int t = ph - 9; y += t * t * WET_DRIP_PX / 36; len = 2; }   // falling, faster and faster
        else continue;                                                        // gone; the next one forms
        for (int j = 0; j < len; j++) {
            uint16_t c = j == 0 && len > 1 ? shine : body;
            draw_pixel(x, y + j, l->night ? night_px(&s_night_lut, c) : c);
        }
    }
}

// Draws a look — sprite, then the held item (colorkeyed) — and puts
// foreground scenery back over both, so they go UNDER it.
static void player_paint(const player_look_t *l)
{
    rect_t s = player_sprite_rect(l);
    if (!l->squash) {
        draw_image_keyed_night(s.x, s.y, s.w, s.h, l->sprite);   // 0x0000 = transparent; darkened at night like the map
    } else {   // squashed under a Heavy item: the sprite stretched to s
        for (int row = 0; row < s.h; row++)
            for (int col = 0; col < s.w; col++) {
                uint16_t c = l->sprite[(row * l->sh / s.h) * l->sw + col * l->sw / s.w];
                if (c != FB_TRANSPARENT_COLOR) draw_pixel(s.x + col, s.y + row, l->night ? night_px(&s_night_lut, c) : c);
            }
    }
    if (l->item != ITEM_NONE) {
        int iw, ih, ix, iy;
        held_item_size(l->item, &iw, &ih);
        held_item_xy(l, iw, ih, &ix, &iy);
        const item_asset_t *a = item_get(l->item);
        if (!a || a->passive.frame_count == 0) {
            fill_rect(ix, iy, iw, ih, 0x8410);
            draw_rect(ix, iy, iw, ih, COLOR_WHITE);
        } else {
            const uint16_t *frame = a->passive.pixels + (size_t)l->item_frame * a->passive.w * a->passive.h;
            rect_t g = held_giant_box(l->item);   // giant: its visible part, scaled up to iw x ih
            if (!g.w) g = (rect_t){ 0, 0, a->passive.w, a->passive.h };   // else all of it (shrunk if it's big)
            // mutated: recoloured, at its animation frame (MUTATIONS); wet: soaked, dripping (WET ITEMS)
            int8_t bottom[HELD_GIANT_MAX];   // each column's lowest drawn row: where the drops hang
            memset(bottom, -1, sizeof(bottom));
            for (int row = 0; row < ih; row++) {
                for (int col = 0; col < iw; col++) {
                    int sx = g.x + col * g.w / iw, sy = g.y + row * g.h / ih;
                    uint16_t c = l->item_q ? item_px(l->item_q, frame, a->passive.w, a->passive.h, sx, sy, l->mfx) : frame[sy * a->passive.w + sx];
                    if (c == FB_TRANSPARENT_COLOR) continue;
                    draw_pixel(ix + col, iy + row, l->night ? night_px(&s_night_lut, c) : c);
                    bottom[col] = (int8_t)row;
                }
            }
            if (QUALITY_IS_WET(l->item_q)) wet_paint_drips(l, ix, iy, iw, bottom);
        }
    }
    rect_t r = player_look_rect(l);
    redraw_foreground_over_rect(r.x, r.y, r.w, r.h);
}

// ============================================================
//  PLAYER BACKGROUND CACHE
//  - Holds whatever was on screen under the last drawn look (sprite +
//    held item), and where that was (s_player_bg_rect)
//  - Reads straight from the live framebuffer, so it works with or
//    without a map loaded (menu scene, map ground/foreground, etc.)
//  - Caveat: only one frame deep. Fine for a single player sprite;
//    if another moving sprite could touch the same tile the same
//    frame, use restore_map_rect() (map-truth based) instead.
// ============================================================
#define PLAYER_BG_MAX_W_ (PLAYER_W + MUT_SQUASH_PX > HELD_GIANT_MAX ? PLAYER_W + MUT_SQUASH_PX : HELD_GIANT_MAX)   // a Heavy item widens the player
#define PLAYER_BG_MAX_W  (PLAYER_BG_MAX_W_ > PLAYER_ANIM_MAX ? PLAYER_BG_MAX_W_ : PLAYER_ANIM_MAX)
#define PLAYER_BG_MAX_H_ (PLAYER_H + HELD_ITEM_GAP + HELD_GIANT_MAX + MUT_FLOAT_LIFT + MUT_FLOAT_BOB)  // item above the head, floating at its highest (HELD_ITEM_DROP only shrinks this)
#define PLAYER_BG_MAX_H  (PLAYER_BG_MAX_H_ > PLAYER_ANIM_MAX ? PLAYER_BG_MAX_H_ : PLAYER_ANIM_MAX)

static uint16_t      s_player_bg[PLAYER_BG_MAX_W * PLAYER_BG_MAX_H];
static rect_t        s_player_bg_rect;            // where s_player_bg came from (row stride = its w)
static player_look_t s_player_drawn;              // the look that is on screen there
static bool          s_player_bg_valid = false;   // false = the player isn't on screen (not drawn yet, or wiped by a full repaint)

// True if (px,py) is currently on screen where the player sprite is drawn
// right now — used by draw_pixel_xor()/tile_highlight_covers() so the
// selected-tile outline never gets XOR'd on top of the player: the player
// always draws OVER the highlight, the same way ui_overlay_covers() keeps
// the hotbar/touch button on top of it. Rect-based (not per-pixel sprite
// opacity), same approximation ui_overlay_covers() already makes.
static bool player_area_covers(int px, int py)
{
    if (!s_player_bg_valid) return false;
    rect_t r = s_player_bg_rect;
    return px >= r.x && px < r.x + r.w && py >= r.y && py < r.y + r.h;
}

// Copies rect r from s_fb into s_player_bg. Call right before drawing the
// player there. s_player_bg always holds the TRUE pixels, with the
// selected-tile XOR stripped out. Otherwise the outline gets baked into the
// cache: once the highlight moves to another tile, restore_player_bg()
// would paste the old outline back and leave a trail of stray boxes behind
// the player. restore_player_bg() + restamp_tile_highlight() then re-apply
// whatever highlight is current at restore time.
static void save_player_bg(rect_t r)
{
    int cx0 = r.x < 0 ? 0 : r.x, cx1 = r.x + r.w > LCD_H_RES ? LCD_H_RES : r.x + r.w;   // the on-screen columns
    for (int row = 0; row < r.h; row++) {
        int       sy  = r.y + row;
        uint16_t *dst = &s_player_bg[row * r.w];
        if (sy < 0 || sy >= LCD_V_RES || cx0 >= cx1) {
            for (int col = 0; col < r.w; col++) dst[col] = COLOR_BLACK;
            continue;
        }
        for (int col = 0; col < cx0 - r.x; col++) dst[col] = COLOR_BLACK;
        memcpy(&dst[cx0 - r.x], &s_fb[sy * LCD_H_RES + cx0], (size_t)(cx1 - cx0) * sizeof(uint16_t));
        for (int col = cx1 - r.x; col < r.w; col++) dst[col] = COLOR_BLACK;
    }
    // Un-XOR the outline: only the selected tile's own 16x16 box can hold any of it.
    if (s_selected_tile_x >= 0 && s_selected_tile_y >= 0) {
        int tx = s_selected_tile_x * TILE_SIZE, ty = s_selected_tile_y * TILE_SIZE;
        int x0 = r.x > tx ? r.x : tx, x1 = r.x + r.w < tx + TILE_SIZE ? r.x + r.w : tx + TILE_SIZE;
        int y0 = r.y > ty ? r.y : ty, y1 = r.y + r.h < ty + TILE_SIZE ? r.y + r.h : ty + TILE_SIZE;
        for (int sy = y0; sy < y1; sy++)
            for (int sx = x0; sx < x1; sx++)
                if (tile_highlight_covers(sx, sy)) s_player_bg[(sy - r.y) * r.w + (sx - r.x)] ^= 0xFFFF;
    }
    s_player_bg_rect = r;
}

// Pastes s_player_bg back where it came from, erasing the drawn look.
static void restore_player_bg(void)
{
    if (!s_player_bg_valid) return;
    draw_image(s_player_bg_rect.x, s_player_bg_rect.y, s_player_bg_rect.w, s_player_bg_rect.h, s_player_bg);
}

// True if a PLAYER_W-wide, PLAYER_FEET_H-tall box at the BOTTOM of a
// sprite placed at (x,y) would overlap a blocked map pixel. Only the
// feet collide (see PLAYER_FEET_H above) — checked at all 4 corners,
// which is enough to catch collisions against the 1-bit-per-pixel map
// hitbox without scanning every pixel in the box.
static bool s_dev_noclip = false;   // DEV LINK "noclip on": the player walks through anything
static int  s_dev_speed  = 1;       // DEV LINK "speed N": N x the walking speed
static bool player_feet_blocked(int x, int y)
{
    if (s_dev_noclip) return false;
    int fx0 = x, fx1 = x + PLAYER_W - 1;
    int fy0 = y + PLAYER_H - PLAYER_FEET_H, fy1 = y + PLAYER_H - 1;
    return map_pixel_blocked(fx0, fy0) || map_pixel_blocked(fx1, fy0) ||
           map_pixel_blocked(fx0, fy1) || map_pixel_blocked(fx1, fy1);
}

// Un-XORs any highlight currently drawn and marks "no highlight" so the
// next update_player() call redraws cleanly instead of assuming the
// framebuffer still matches its last known XOR state. Call this any
// time something else repaints the screen out from under the highlight
// — right now: before a menu is drawn, and whenever a new map loads.
void player_reset_selected_tile(void)
{
    if (s_selected_tile_x >= 0 && s_selected_tile_y >= 0) {
        draw_tile_highlight_xor(s_selected_tile_x, s_selected_tile_y);
    }
    s_selected_tile_x = -1;
    s_selected_tile_y = -1;
}

// Marks the cached "pixels under the player" as unusable. Call this any
// time the whole screen was repainted without the player sprite on it
// (a new map fading in, the camera view closing) — otherwise the next move
// would paste stale pixels from before the repaint back onto the screen,
// and the animation player would think the sprite is still there to redraw.
void player_invalidate_bg(void)
{
    s_player_bg_valid = false;
}

// Erases the look currently on screen (if any) and draws `l`, keeping the
// selected-tile outline and the hotbar / touch button right.
static void player_redraw(const player_look_t *l)
{
    bool   had = s_player_bg_valid;
    rect_t old = s_player_bg_rect;
    rect_t r   = player_look_rect(l);

    // Erase + redraw off screen, then show both spots in one copy — done
    // straight on screen, the panel sometimes caught the erased player.
    compose_begin(had ? rect_union(old, r) : r);
    if (had) {
        restore_player_bg();
        s_player_bg_valid = false;   // the player isn't there anymore — let the highlight land on the vacated spot
        restamp_tile_highlight(old.x, old.y, old.w, old.h);
    }

    // Snapshot the real pixels at the new spot BEFORE drawing, then paste
    // them straight back: the item is colorkeyed and doesn't fill its whole
    // rect, and every pixel of the rect must be raw (un-XOR'd) before the
    // outline is restamped over it below.
    save_player_bg(r);
    s_player_bg_valid = true;
    s_player_drawn    = *l;
    restore_player_bg();
    player_paint(l);
    restamp_tile_highlight(r.x, r.y, r.w, r.h);

    // Hotbar / touch button stay on top. The old spot too: the cached
    // background pasted back there may hold an out-of-date hotbar.
    if (had) ui_overlays_redraw_if_overlap(old.x, old.y, old.w, old.h);
    ui_overlays_redraw_if_overlap(r.x, r.y, r.w, r.h);
    compose_end();
}

// Puts the player back on screen where it stands, after a full-screen
// repaint (map load, closing the camera view) — otherwise it would stay
// invisible until the next step.
static void player_draw_fresh(void)
{
    s_player_bg_valid = false;   // whatever was cached belongs to the screen that got replaced
    player_look_t l = player_look_now();
    player_redraw(&l);
}

static void hotbar_follow_player(void);   // HUD section: moves the hotbar out from under the player

// Call this once per frame from your main loop (update_input() does): walks
// the current tap-to-walk path, redraws the player and the tile outline.
void update_player(void)
{
    direction_t dir1 = DIR_CENTER;
    int dx = 0, dy = 0;

    // Tap-to-walk: head for the current walk's next waypoint (if there is one).
    int  nav_wx = 0, nav_wy = 0;
    bool nav_act = false, nav_on = false;
    direction_t nav_face = DIR_CENTER;
    if ((nav_on = nav_next_waypoint(&nav_wx, &nav_wy, &nav_act, &nav_face))) {
        dx = (nav_wx > s_player_x) - (nav_wx < s_player_x);
        dy = (nav_wy > s_player_y) - (nav_wy < s_player_y);
        // Straight lines only. Waypoints are one tile apart along one axis,
        // but getting onto the first one can need both (the player wasn't on
        // the tile grid): do the shorter leg first, then the long straight one.
        if (dx && dy) {
            if (abs(nav_wx - s_player_x) <= abs(nav_wy - s_player_y)) dy = 0;
            else                                                      dx = 0;
        }
        dir1 = nav_delta_to_dir(dx, dy);
    }

    if (dir1 != DIR_CENTER) {
        s_player_facing = dir1;
    }
    if (nav_face != DIR_CENTER) s_player_facing = nav_face;   // arrived next to what was tapped: face it

    // Whole pixels to move this frame (s_game_ticks ticks of it); the fraction carries over to the next.
    static int s_move_accum_q = 0;
    int step = 0;
    if (dx != 0 || dy != 0) {
        s_move_accum_q += PLAYER_SPEED_Q * s_dev_speed * s_game_ticks;
        step            = s_move_accum_q / 4;
        s_move_accum_q %= 4;
    } else {
        s_move_accum_q = 0;
    }
    bool hold = (dx != 0 || dy != 0) && step == 0;   // walking, but a quick frame: no step due yet (not a stop)

    // Propose the move, clamp to screen, then resolve collision PER AXIS
    // (checked separately) so the player slides along a wall instead of
    // getting stopped dead by diagonal contact with it. At most 2 px at a
    // time, so a long step (a slow frame) can't hop over something thin.
    int start_x = s_player_x, start_y = s_player_y;
    int left = step;
    while (left > 0) {
        int s = left < 2 ? left : 2;
        left -= s;
        int new_x = s_player_x + dx * s;
        int new_y = s_player_y + dy * s;
        if (new_x < 0) new_x = 0;
        if (new_y < PLAYER_MIN_Y) new_y = PLAYER_MIN_Y;
        if (new_x > LCD_H_RES - PLAYER_W) new_x = LCD_H_RES - PLAYER_W;
        if (new_y > LCD_V_RES - PLAYER_H) new_y = LCD_V_RES - PLAYER_H;
        if (nav_on) {   // stop exactly on the waypoint instead of stepping past it
            if ((dx > 0 && new_x > nav_wx) || (dx < 0 && new_x < nav_wx)) new_x = nav_wx;
            if ((dy > 0 && new_y > nav_wy) || (dy < 0 && new_y < nav_wy)) new_y = nav_wy;
        }

        if (dx != 0 && player_feet_blocked(new_x, s_player_y)) new_x = s_player_x;
        if (dy != 0 && player_feet_blocked(s_player_x, new_y)) new_y = s_player_y;
        if (new_x == s_player_x && new_y == s_player_y) { left += s; break; }   // blocked, or on the waypoint
        left += s - abs(new_x - s_player_x) - abs(new_y - s_player_y);          // stopped short on the waypoint
        s_player_x = new_x;
        s_player_y = new_y;
        if (nav_on && s_player_x == nav_wx && s_player_y == nav_wy) break;
    }
    // Reached a waypoint with pixels to spare: they go toward the next one
    // next frame, instead of being lost at every tile (more so on a slow frame).
    if (nav_on && left > 0 && s_player_x == nav_wx && s_player_y == nav_wy) s_move_accum_q += left * 4;
    bool moved = (s_player_x != start_x) || (s_player_y != start_y);
    if (nav_on && !hold) nav_progress(moved);
    if (moved) {
        s_player_anim_counter += s_game_ticks;
        if (s_player_anim_counter >= PLAYER_ANIM_TICKS) {
            s_player_anim_counter = 0;
            s_player_anim_frame = (s_player_anim_frame + 1) % PLAYER_ANIM_FRAMES;
        }
    } else if (!hold) {
        s_player_anim_frame   = 0; // idle pose — first frame of whichever direction
        s_player_anim_counter = 0;
    }

    // The hotbar gets out of the way first, so nothing is drawn under it.
    hotbar_follow_player();

    // Only touch the framebuffer when the look actually changed (moved,
    // turned, walk frame, held item or its animation frame) — this is what
    // stops the constant-redraw flicker.
    player_look_t look = player_look_now();
    if (moved || (s_player_bg_valid && !player_look_equal(&look, &s_player_drawn))) {
        player_redraw(&look);
    }

    // The selected area is whichever TILE_SIZE tile the player's FEET are
    // standing on, shifted one tile over in the direction they're facing.
    // (Feet = bottom-center of the sprite, not the sprite's vertical
    // middle — the sprite is 2 tiles tall, so the middle would be wrong.)
    int facing_dx, facing_dy;
    direction_to_delta(s_player_facing, &facing_dx, &facing_dy);
    int player_tile_x = (s_player_x + PLAYER_W / 2) / TILE_SIZE;
    int player_tile_y = (s_player_y + PLAYER_H - 1) / TILE_SIZE;
    int new_selected_tile_x = player_tile_x + facing_dx;
    int new_selected_tile_y = player_tile_y + facing_dy;
    if (new_selected_tile_x < 0) new_selected_tile_x = 0;
    if (new_selected_tile_y < 0) new_selected_tile_y = 0;
    if (new_selected_tile_x > TILE_COLS - 1) new_selected_tile_x = TILE_COLS - 1;
    if (new_selected_tile_y > TILE_ROWS - 1) new_selected_tile_y = TILE_ROWS - 1;

    // Only touch the highlight when it actually moves to a new tile —
    // un-XOR the old tile's border, then XOR the new one.
    if (new_selected_tile_x != s_selected_tile_x || new_selected_tile_y != s_selected_tile_y) {
        if (s_selected_tile_x >= 0 && s_selected_tile_y >= 0) {
            draw_tile_highlight_xor(s_selected_tile_x, s_selected_tile_y);
        }
        s_selected_tile_x = new_selected_tile_x;
        s_selected_tile_y = new_selected_tile_y;
        draw_tile_highlight_xor(s_selected_tile_x, s_selected_tile_y);
    }

    // "Action": fires once when a tap-to-walk onto something solid (a tree,
    // a chest) arrives next to it.
    if (nav_act) {
        ESP_LOGI(TAG, "player: action, selected area (%d, %d) on map \"%s\"",
                 s_selected_tile_x, s_selected_tile_y, current_map_name());
        // current_map_name() tells you WHICH MAP the player is on (the map
        // file's name, e.g. "cave" for cave.map), and s_selected_tile_x/y
        // is the highlighted tile's coordinates — check_selected_area()
        // matches those against the registry. Inline, it's just:
        //   if (strcmp(current_map_name(), "cave") == 0 &&
        //       s_selected_tile_x == MY_TILE_X && s_selected_tile_y == MY_TILE_Y) { ... }
        check_selected_area(current_map_name(), s_selected_tile_x, s_selected_tile_y);
        if (!trig_on_action(s_selected_tile_x, s_selected_tile_y) &&   // an object with actions (a shop) takes the press
            !ranch_on_action() &&                                      // ...or the animal / grass the walk was for (ANIMALS — before a rug under it)
            !place_on_action() &&                                      // ...or putting down / picking up a prop (PLACEMENT)
            !fish_on_action()) {                                       // ...or casting a fishing rod into water (FISHING)
            brk_on_action();   // hit whatever breakable is in reach (needs the right held item)
            farm_on_action();  // plant the held seeds / harvest the crop on the faced tile
        }
    }
}

// ============================================================
//  ANIMATION PLAYBACK — advances every animation on the loaded map when
//  its interval is up, and repaints just that animation's rectangle.
//  Called once per frame from update_input() while the player is
//  walking around (paused while a menu is open, so nothing paints over
//  the menu panel).
//
//  Everything drawn ON TOP of the ground has to survive a repaint, so
//  after writing the new frame this puts back, in the same order
//  update_player() draws them:
//    1. the player sprite, if it overlaps the animation — refreshing the
//       cached "pixels under the player" first so the next step of the
//       player pastes the CURRENT frame back, not a stale one;
//    2. foreground-layer pixels, so the player still walks UNDER a
//       foreground animation (anim_restamp_foreground);
//    3. the XOR'd selected-tile outline.
//  Collision needs nothing here — it lives in the map's bitmask.
// ============================================================
static inline int anim_imin(int a, int b) { return a < b ? a : b; }
static inline int anim_imax(int a, int b) { return a > b ? a : b; }

static inline bool anim_rects_overlap(int ax, int ay, int aw, int ah, int bx, int by, int bw, int bh)
{
    return ax < bx + bw && bx < ax + aw && ay < by + bh && by < ay + ah;
}

// (x,y,w,h) was just repainted from underneath the player (still raw — no
// highlight XOR yet). If that touched the drawn player, refresh the cached
// background there from the screen and put the player (and held item) back
// on top. Returns true if it did; the caller then restamps the outline over
// s_player_bg_rect too, since all of it was rewritten raw here.
static bool player_restack_over(int x, int y, int w, int h)
{
    if (!s_player_bg_valid) return false;
    rect_t b = s_player_bg_rect;
    if (!anim_rects_overlap(x, y, w, h, b.x, b.y, b.w, b.h)) return false;

    compose_begin(b);   // callers compose their own rect already; this adds the player's to it
    int ox0 = anim_imax(anim_imax(x, b.x), 0),                 oy0 = anim_imax(anim_imax(y, b.y), 0);
    int ox1 = anim_imin(anim_imin(x + w, b.x + b.w), LCD_H_RES), oy1 = anim_imin(anim_imin(y + h, b.y + b.h), LCD_V_RES);
    for (int py = oy0; py < oy1; py++) {
        for (int px = ox0; px < ox1; px++) {
            s_player_bg[(py - b.y) * b.w + (px - b.x)] = s_fb[py * LCD_H_RES + px];
        }
    }
    restore_player_bg();              // the whole look's area back to raw background...
    player_paint(&s_player_drawn);    // ...then the same look on top, foreground over it
    compose_end();
    return true;
}

// True if (px,py) is a pixel the selected-tile outline is currently
// flipping. draw_tile_highlight_xor() touches each border pixel once,
// except the four corners, which it flips twice (net: unchanged) — so
// the outline effectively has notched corners, and this matches that.
static bool anim_highlight_covers(int px, int py)
{
    if (s_selected_tile_x < 0 || s_selected_tile_y < 0) return false;
    if (ui_overlay_covers(px, py)) return false;   // draw_pixel_xor() skips these too
    if (player_area_covers(px, py)) return false;  // ditto — the player draws over the highlight, not under it
    int x0 = s_selected_tile_x * TILE_SIZE, y0 = s_selected_tile_y * TILE_SIZE;
    int x1 = x0 + TILE_SIZE - 1,            y1 = y0 + TILE_SIZE - 1;
    if (px < x0 || px > x1 || py < y0 || py > y1) return false;
    bool on_x_edge = (px == x0 || px == x1);
    bool on_y_edge = (py == y0 || py == y1);
    if (on_x_edge && on_y_edge) return false;   // corner: flipped twice
    return on_x_edge || on_y_edge;
}

// Flips the outline back on wherever (x,y,w,h) was rewritten, except inside
// *skip (done already; NULL = nothing to skip). Only the selected tile's own
// box can hold any of it, so only that part of the rect is looked at — a
// big repaint (a crowd walking) costs no more than a small one.
static void highlight_restamp_rect(int x, int y, int w, int h, const rect_t *skip)
{
    if (s_selected_tile_x < 0 || s_selected_tile_y < 0) return;
    int tx = s_selected_tile_x * TILE_SIZE, ty = s_selected_tile_y * TILE_SIZE;
    int x0 = x > tx ? x : tx, y0 = y > ty ? y : ty;
    int x1 = x + w < tx + TILE_SIZE ? x + w : tx + TILE_SIZE, y1 = y + h < ty + TILE_SIZE ? y + h : ty + TILE_SIZE;
    for (int py = y0; py < y1; py++)
        for (int px = x0; px < x1; px++) {
            if (skip && px >= skip->x && px < skip->x + skip->w && py >= skip->y && py < skip->y + skip->h) continue;
            if (anim_highlight_covers(px, py)) draw_pixel_xor(px, py);
        }
}

// Writes the instance's current frame to the screen and puts back
// whatever is layered IN FRONT of it — foreground-layer map scenery,
// other overlapping foreground animations, the player sprite, and the
// selected-tile outline — so a repaint never erases something that's
// supposed to sit on top of it.
static void anim_paint_instance(const anim_instance_t *a)
{
    const uint16_t *frame = anim_frame(a);
    if (!frame) return;           // not off the card yet: the map buffer's first frame is showing

    // All of the below lands off screen and shows up in one copy at the
    // end — otherwise a player standing in the footprint blinks out
    // between step 1 and step 2 on every frame of the animation.
    compose_begin_over((rect_t){ a->x, a->y, a->w, a->h });   // the frame covers all of it

    // 1) The footprint's ground truth is the frame itself (background baked in),
    //    with any breakable placed above it on top, as it looks right now.
    draw_image(a->x, a->y, a->w, a->h, frame);
    brk_restamp_over_anim(a->x, a->y, a->x + a->w, a->y + a->h, false);

    // 1b) This footprint may itself sit partly BEHIND static foreground
    // scenery (a tree, a bridge rail) or another animated foreground
    // object — draw_image above just overwrote that with raw ground
    // pixels, so put it back. redraw_foreground_over_rect() only touches
    // pixels actually marked foreground, so this is a no-op everywhere
    // that isn't layered in front of this animation.
    redraw_foreground_over_rect(a->x, a->y, a->w, a->h);

    // 1c) Shoppers and a fishing line / bobber over it: back on top, in the
    //     same order map_repaint_rect() draws them (otherwise each new frame
    //     wipes them until they next move — the bobber on animated water blinked).
    nav_trail_paint_rect(a->x, a->y, a->w, a->h);
    ranch_paint_rect(a->x, a->y, a->w, a->h);
    machine_paint_rect(a->x, a->y, a->w, a->h);
    npc_paint_rect(a->x, a->y, a->w, a->h);
    fish_paint_rect(a->x, a->y, a->w, a->h);

    // 2) Is the player (or its held item) standing in it? Put it back on
    //    top. Reads s_fb itself (not the raw animation frame) into the
    //    player's cached background, so this stays correct even where 1b
    //    just restamped foreground scenery over the animation.
    bool   over_player = player_restack_over(a->x, a->y, a->w, a->h);
    rect_t p           = s_player_bg_rect;

    // 3) Everything above was written over the selected-tile outline (XOR
    //    bits live in the framebuffer itself), so flip it back on wherever
    //    the pixels were rewritten: the footprint, plus the player's box
    //    if the player was redrawn.
    rect_t foot = { a->x, a->y, a->w, a->h };
    highlight_restamp_rect(foot.x, foot.y, foot.w, foot.h, NULL);
    if (over_player) highlight_restamp_rect(p.x, p.y, p.w, p.h, &foot);

    // 4) hotbar / touch button back on top of whatever was just painted
    ui_overlays_redraw_if_overlap(a->x, a->y, a->w, a->h);
    if (over_player) ui_overlays_redraw_if_overlap(p.x, p.y, p.w, p.h);
    compose_end();
}

// Call once per frame (see update_input). Cheap when nothing is due: one
// integer compare per playing bundle. Frame index/finished come from
// bundle_frame_by_loop_count()'s elapsed-time math (frame_bundle.h)
// rather than being stepped or unrolled — a finite bundle (loop_count
// >= 0, e.g. a one-shot splash placed on the map) naturally stops
// costing anything once `finished` sticks. The clock is per bundle (every
// placement of one runs in step), and a frame change repaints each of its
// placements, in depth order.
static void update_animations(void)
{
    if (!s_map_loaded || s_anim.inst_count == 0) return;

    uint32_t now = (uint32_t)(esp_timer_get_time() / 1000);
    bool any = false;
    for (int i = 0; i < s_bundles.count; i++) {
        bundle_play_t *p = &s_bundles.play[i];
        p->changed = false;
        if (!p->used || !p->started || p->finished) continue;   // not played / finite bundle already played out
        if ((int32_t)(now - p->next_ms) < 0) continue;          // not due yet (safe across the 32-bit ms wrap)

        const frame_bundle_t *bd = &s_bundles.items[i];
        uint32_t elapsed = now - p->start_ms;
        bool finished = false;
        uint16_t f = bundle_frame_by_loop_count(bd, elapsed, &finished);
        int16_t before = p->shown_frame;
        if (!play_show(i, f)) { p->next_ms = now + STREAM_RETRY_MS; continue; }   // still coming off the card: hold this frame a moment
        p->finished = finished;
        p->next_ms  = bundle_next_boundary_ms(bd, p->start_ms, elapsed);
        if ((int32_t)(now - p->next_ms) >= 0) {
            // we fell behind (menu, SD load) — resync the clock, don't fast-forward through missed frames
            p->start_ms = now;
            p->next_ms  = bundle_next_boundary_ms(bd, p->start_ms, 0);
        }
        p->changed = (p->shown_frame != before);
        any |= p->changed;
        play_prefetch(i);
    }
    if (!any) return;
    for (int n = 0; n < s_anim.inst_count; n++) {
        const anim_instance_t *a = &s_anim.inst[n];
        if (s_bundles.play[a->bi].changed) anim_paint_instance(a);
    }
}

// Draws every animation's current frame — used after something repainted
// the whole screen from the map buffer (the camera closing, a night stage), which leaves
// the map's first frame showing instead of wherever the animations are.
// Same foreground restamp as anim_paint_instance() and for the same
// reason: the map buffer's baked-in scenery can't already reflect a
// non-first animation frame, so a plain draw_image() here would erase
// any foreground object overlapping the footprint.
static void anim_draw_all_current(void)
{
    for (int n = 0; n < s_anim.inst_count; n++) {
        const anim_instance_t *a = &s_anim.inst[n];
        const uint16_t *frame = anim_frame(a);
        if (!frame) continue;
        draw_image(a->x, a->y, a->w, a->h, frame);
        brk_restamp_over_anim(a->x, a->y, a->x + a->w, a->y + a->h, false);
        redraw_foreground_over_rect(a->x, a->y, a->w, a->h);
    }
    brk_fall_restamp(0, 0, LCD_H_RES, LCD_V_RES);   // a breakable falling: back on top of the whole screen
}
// ============================================================
//  BREAKABLE RUNTIME + HELD-ITEM HUD
//
//  How a breakable stays consistent with the rest of the engine:
//   - s_map_pixels, s_map_hitbox and s_map_fgmask are ALWAYS kept equal
//     to what the object looks like / blocks right now (each frame is
//     copied into the footprint before it is painted). So the menu-close
//     repaint, restore_map_rect(), redraw_foreground_over_rect() and
//     map_pixel_blocked() all just work without knowing breakables exist.
//   - map_repaint_rect() does the on-screen part: repaint the rectangle
//     from the map buffer, then put the player and the selected-tile
//     outline back on top (same layering anim_paint_instance() uses).
//   - Breakables may overlap each other in a MAP10 file: any change
//     rebuilds the whole footprint with brk_compose() (background with no
//     breakables, then every overlapping one in draw order). Older files
//     paste one object's baked look instead, which brings back an
//     overlapping neighbour as it was placed — re-export them.
//   - Don't let a breakable's footprint overlap an animated object's
//     footprint or the HUD box (top-left) — they would repaint each other.
// ============================================================

