// Keyboard Test row: shows what was typed last (see menu_action_keyboard_test).
static char s_kb_test_label[48] = "Keyboard Test";

// ---- Dev Tools: what's left of each memory, plus the developer rows ----
// The memory rows are refreshed when the screen opens, every second while
// it's open, and when you tap one.
//   Flash: the running app partition, minus the app image in it
//   SRAM:  the internal heap (what's left after the app's static data)
//   PSRAM: the external heap
static char s_dev_flash_label[32] = "Flash free: ...";
static char s_dev_sram_label[32]  = "SRAM free: ...";
static char s_dev_psram_label[32] = "PSRAM free: ...";
static char s_boot_audio_label[48];

// Rewrites the three memory labels. Returns true if any of them changed.
static bool dev_mem_refresh(void)
{
    static uint32_t app_used, app_size;   // the app can't change size while it runs: read once
    if (!app_size) {
        const esp_partition_t *p = esp_ota_get_running_partition();
        if (p) {
            esp_partition_pos_t pos = { .offset = p->address, .size = p->size };
            esp_image_metadata_t md;
            if (esp_image_get_metadata(&pos, &md) == ESP_OK) app_used = md.image_len;
            app_size = p->size;
        }
    }
    char flash[32], sram[32], psram[32];
    if (app_size) {   // in MB with one decimal (tenths rounded), so it fits the row at full size
        unsigned long free_t = ((unsigned long)(app_size - app_used) * 10 + 524288) / 1048576;
        unsigned long size_t10 = ((unsigned long)app_size * 10 + 524288) / 1048576;
        snprintf(flash, sizeof(flash), "Flash free: %lu.%lu/%lu.%lu MB",
                 free_t / 10, free_t % 10, size_t10 / 10, size_t10 % 10);
    }
    else          snprintf(flash, sizeof(flash), "Flash free: ?");
    snprintf(sram, sizeof(sram), "SRAM free: %u/%u KB",
             (unsigned)(heap_caps_get_free_size(MALLOC_CAP_INTERNAL) / 1024),
             (unsigned)(heap_caps_get_total_size(MALLOC_CAP_INTERNAL) / 1024));
    snprintf(psram, sizeof(psram), "PSRAM free: %u/%u KB",
             (unsigned)(heap_caps_get_free_size(MALLOC_CAP_SPIRAM) / 1024),
             (unsigned)(heap_caps_get_total_size(MALLOC_CAP_SPIRAM) / 1024));
    bool changed = strcmp(flash, s_dev_flash_label) || strcmp(sram, s_dev_sram_label) ||
                   strcmp(psram, s_dev_psram_label);
    snprintf(s_dev_flash_label, sizeof(s_dev_flash_label), "%s", flash);
    snprintf(s_dev_sram_label,  sizeof(s_dev_sram_label),  "%s", sram);
    snprintf(s_dev_psram_label, sizeof(s_dev_psram_label), "%s", psram);
    return changed;
}

